import React, { useState, useEffect } from 'react';
import { User, UserRole } from './types';
import Login from './views/Login';
import Register from './views/Register';
import ForgotPassword from './views/ForgotPassword';
import CustomerDashboard from './views/CustomerDashboard';
import TechnicianDashboard from './views/TechnicianDashboard';
import AdminDashboard from './views/AdminDashboard';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [view, setView] = useState<'login' | 'register' | 'forgot'>('login');
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const savedUser = localStorage.getItem('alOstaUser');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }
    setIsLoading(false);
  }, []);

  const handleLogin = (userData: User) => {
    setUser(userData);
    localStorage.setItem('alOstaUser', JSON.stringify(userData));
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('alOstaUser');
    setView('login');
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-screen bg-gray-900">
        <div className="text-white text-2xl font-bold animate-pulse">جاري التحميل...</div>
      </div>
    );
  }

  if (!user) {
    if (view === 'register') return <Register onSwitch={() => setView('login')} />;
    if (view === 'forgot') return <ForgotPassword onSwitch={() => setView('login')} />;
    return <Login onLogin={handleLogin} onSwitchRegister={() => setView('register')} onSwitchForgot={() => setView('forgot')} />;
  }

  // Role-based routing
  switch (user.role) {
    case 'customer':
      return <CustomerDashboard user={user} onLogout={handleLogout} />;
    case 'technician':
      return <TechnicianDashboard user={user} onLogout={handleLogout} />;
    case 'admin':
    case 'manager':
      return <AdminDashboard user={user} onLogout={handleLogout} />;
    default:
      return <div className="p-10 text-center">خطأ في تحديد الدور</div>;
  }
};

export default App;

import React, { useState } from 'react';
import { collection, query, where, getDocs } from 'firebase/firestore';
import { db } from '../firebase';
import { User } from '../types';

interface LoginProps {
  onLogin: (user: User) => void;
  onSwitchRegister: () => void;
  onSwitchForgot: () => void;
}

const Login: React.FC<LoginProps> = ({ onLogin, onSwitchRegister, onSwitchForgot }) => {
  const [phone, setPhone] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setError('');

    // Predefined Admin Check
    if ((phone === 'manager123' || phone === 'admin123') && password) {
       try {
         const q = query(collection(db, 'users'), where('phone', '==', phone));
         const snap = await getDocs(q);
         if (!snap.empty) {
           const userData = { id: snap.docs[0].id, ...snap.docs[0].data() } as User;
           if (userData.password === password) {
             onLogin(userData);
             return;
           }
         }
       } catch (err) { console.error(err); }
    }

    try {
      const q = query(collection(db, 'users'), where('phone', '==', phone));
      const querySnapshot = await getDocs(q);

      if (querySnapshot.empty) {
        setError('المستخدم غير موجود');
      } else {
        const userData = { id: querySnapshot.docs[0].id, ...querySnapshot.docs[0].data() } as User;
        if (userData.password === password) {
          onLogin(userData);
        } else {
          setError('كلمة المرور غير صحيحة');
        }
      }
    } catch (err) {
      setError('حدث خطأ أثناء الاتصال بالقاعدة');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-900 to-indigo-900 px-4">
      <div className="bg-white w-full max-w-md p-8 rounded-2xl shadow-2xl">
        <div className="text-center mb-10">
          <h1 className="text-4xl font-extrabold text-blue-900 mb-2">الأسطى</h1>
          <p className="text-gray-500 font-medium">بوابة خدمات الصيانة والمقاولات</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div>
            <label className="block text-sm font-bold text-gray-700 mb-2">رقم الهاتف أو اسم المستخدم</label>
            <input
              type="text"
              required
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition"
              placeholder="مثال: 010xxxxxxxx"
            />
          </div>

          <div>
            <label className="block text-sm font-bold text-gray-700 mb-2">كلمة المرور</label>
            <input
              type="password"
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition"
              placeholder="••••••••"
            />
          </div>

          {error && <p className="text-red-500 text-sm font-bold text-center">{error}</p>}

          <button
            type="submit"
            disabled={isSubmitting}
            className="w-full bg-blue-700 hover:bg-blue-800 text-white font-bold py-3 rounded-lg shadow-lg hover:shadow-xl transition-all disabled:opacity-50"
          >
            {isSubmitting ? 'جاري الدخول...' : 'تسجيل الدخول'}
          </button>
        </form>

        <div className="mt-8 flex flex-col items-center space-y-3">
          <button onClick={onSwitchForgot} className="text-blue-600 text-sm hover:underline font-bold">نسيت كلمة المرور؟</button>
          <div className="text-gray-400 text-sm">ليس لديك حساب؟ 
            <button onClick={onSwitchRegister} className="text-indigo-600 font-bold ml-1 hover:underline">سجل الآن</button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState } from 'react';
import { collection, addDoc, query, where, getDocs } from 'firebase/firestore';
import { db } from '../firebase';
import { UserRole } from '../types';

interface RegisterProps {
  onSwitch: () => void;
}

const Register: React.FC<RegisterProps> = ({ onSwitch }) => {
  const [role, setRole] = useState<UserRole>('customer');
  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    password: '',
    address: '',
    securityQuestion: 'ما هو اسم مدرستك الابتدائية؟',
    securityAnswer: '',
    specialty: 'نجار',
    experience: 1,
    area: ''
  });
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const specialties = ['نجار', 'كهربائي', 'سباك', 'فني دش', 'نقاش'];

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setError('');

    try {
      // Check if phone already exists
      const q = query(collection(db, 'users'), where('phone', '==', formData.phone));
      const snap = await getDocs(q);
      if (!snap.empty) {
        setError('هذا الهاتف مسجل مسبقاً');
        setIsSubmitting(false);
        return;
      }

      await addDoc(collection(db, 'users'), {
        ...formData,
        role,
        createdAt: Date.now()
      });
      setSuccess('تم إنشاء الحساب بنجاح! يمكنك الآن تسجيل الدخول.');
      setTimeout(onSwitch, 2000);
    } catch (err) {
      setError('حدث خطأ أثناء التسجيل');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen py-10 bg-gray-100 flex items-center justify-center px-4">
      <div className="bg-white w-full max-w-2xl p-8 rounded-2xl shadow-xl">
        <h2 className="text-3xl font-extrabold text-blue-900 mb-6 text-center">إنشاء حساب جديد</h2>

        <div className="flex bg-gray-100 p-1 rounded-lg mb-8">
          <button 
            onClick={() => setRole('customer')}
            className={`flex-1 py-2 rounded-md font-bold transition ${role === 'customer' ? 'bg-white shadow-md text-blue-800' : 'text-gray-500'}`}
          >عميل</button>
          <button 
            onClick={() => setRole('technician')}
            className={`flex-1 py-2 rounded-md font-bold transition ${role === 'technician' ? 'bg-white shadow-md text-blue-800' : 'text-gray-500'}`}
          >فني</button>
        </div>

        <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="col-span-1">
            <label className="block text-sm font-bold text-gray-700 mb-1">الاسم بالكامل</label>
            <input name="name" required onChange={handleInputChange} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
          </div>
          <div className="col-span-1">
            <label className="block text-sm font-bold text-gray-700 mb-1">رقم الهاتف</label>
            <input name="phone" required onChange={handleInputChange} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
          </div>
          <div className="col-span-1">
            <label className="block text-sm font-bold text-gray-700 mb-1">كلمة المرور</label>
            <input name="password" type="password" required onChange={handleInputChange} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
          </div>
          <div className="col-span-1">
            <label className="block text-sm font-bold text-gray-700 mb-1">العنوان</label>
            <input name="address" required onChange={handleInputChange} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
          </div>

          <div className="col-span-2">
            <label className="block text-sm font-bold text-gray-700 mb-1">سؤال الأمان</label>
            <select name="securityQuestion" onChange={handleInputChange} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white">
              <option>ما هو اسم مدرستك الابتدائية؟</option>
              <option>ما هو اسم حيوانك الأليف؟</option>
              <option>ما هي مدينتك المفضلة؟</option>
            </select>
          </div>
          <div className="col-span-2">
            <label className="block text-sm font-bold text-gray-700 mb-1">إجابة سؤال الأمان</label>
            <input name="securityAnswer" required onChange={handleInputChange} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
          </div>

          {role === 'technician' && (
            <>
              <div className="col-span-1">
                <label className="block text-sm font-bold text-gray-700 mb-1">التخصص</label>
                <select name="specialty" onChange={handleInputChange} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white">
                  {specialties.map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>
              <div className="col-span-1">
                <label className="block text-sm font-bold text-gray-700 mb-1">سنوات الخبرة</label>
                <input name="experience" type="number" required onChange={handleInputChange} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
              </div>
              <div className="col-span-2">
                <label className="block text-sm font-bold text-gray-700 mb-1">منطقة العمل</label>
                <input name="area" required onChange={handleInputChange} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
              </div>
            </>
          )}

          {error && <p className="col-span-2 text-red-500 text-sm font-bold text-center">{error}</p>}
          {success && <p className="col-span-2 text-green-500 text-sm font-bold text-center">{success}</p>}

          <div className="col-span-2 pt-4">
            <button
              type="submit"
              disabled={isSubmitting}
              className="w-full bg-blue-700 hover:bg-blue-800 text-white font-bold py-3 rounded-lg shadow transition-all disabled:opacity-50"
            >
              {isSubmitting ? 'جاري التسجيل...' : 'تسجيل الحساب'}
            </button>
            <button onClick={onSwitch} type="button" className="w-full mt-4 text-gray-500 hover:underline">رجوع لتسجيل الدخول</button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default Register;

import React, { useState } from 'react';
import { collection, query, where, getDocs, doc, updateDoc } from 'firebase/firestore';
import { db } from '../firebase';

interface ForgotPasswordProps {
  onSwitch: () => void;
}

const ForgotPassword: React.FC<ForgotPasswordProps> = ({ onSwitch }) => {
  const [step, setStep] = useState(1);
  const [phone, setPhone] = useState('');
  const [user, setUser] = useState<any>(null);
  const [answer, setAnswer] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const findUser = async () => {
    setError('');
    const q = query(collection(db, 'users'), where('phone', '==', phone));
    const snap = await getDocs(q);
    if (snap.empty) {
      setError('المستخدم غير موجود');
    } else {
      setUser({ id: snap.docs[0].id, ...snap.docs[0].data() });
      setStep(2);
    }
  };

  const verifyAnswer = () => {
    if (answer === user.securityAnswer) {
      setStep(3);
    } else {
      setError('إجابة خاطئة');
    }
  };

  const resetPassword = async () => {
    try {
      const userRef = doc(db, 'users', user.id);
      await updateDoc(userRef, { password: newPassword });
      setSuccess('تم تغيير كلمة المرور بنجاح');
      setTimeout(onSwitch, 2000);
    } catch (err) {
      setError('خطأ في تحديث البيانات');
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100 p-4">
      <div className="bg-white max-w-md w-full p-8 rounded-2xl shadow-xl">
        <h2 className="text-2xl font-bold text-blue-900 mb-6 text-center">استعادة كلمة المرور</h2>

        {step === 1 && (
          <div className="space-y-4">
            <p className="text-gray-600 text-sm">أدخل رقم الهاتف للبحث عن حسابك</p>
            <input value={phone} onChange={e => setPhone(e.target.value)} className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" placeholder="رقم الهاتف" />
            <button onClick={findUser} className="w-full bg-blue-700 text-white font-bold py-3 rounded-lg">بحث</button>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-4">
            <p className="text-blue-800 font-bold">{user.securityQuestion}</p>
            <input value={answer} onChange={e => setAnswer(e.target.value)} className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" placeholder="أدخل الإجابة" />
            <button onClick={verifyAnswer} className="w-full bg-blue-700 text-white font-bold py-3 rounded-lg">تحقق</button>
          </div>
        )}

        {step === 3 && (
          <div className="space-y-4">
            <p className="text-gray-600 text-sm">أدخل كلمة المرور الجديدة</p>
            <input type="password" value={newPassword} onChange={e => setNewPassword(e.target.value)} className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" placeholder="كلمة المرور الجديدة" />
            <button onClick={resetPassword} className="w-full bg-green-600 text-white font-bold py-3 rounded-lg">حفظ التغييرات</button>
          </div>
        )}

        {error && <p className="mt-4 text-red-500 font-bold text-center">{error}</p>}
        {success && <p className="mt-4 text-green-500 font-bold text-center">{success}</p>}

        <button onClick={onSwitch} className="w-full mt-6 text-gray-500 hover:underline">العودة لتسجيل الدخول</button>
      </div>
    </div>
  );
};

export default ForgotPassword;

import React, { useState, useEffect } from 'react';
import { collection, addDoc, query, where, onSnapshot, orderBy, updateDoc, doc } from 'firebase/firestore';
import { db } from '../firebase';
import { User, Order, OrderStatus } from '../types';

interface CustomerDashboardProps {
  user: User;
  onLogout: () => void;
}

const CustomerDashboard: React.FC<CustomerDashboardProps> = ({ user, onLogout }) => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [serviceType, setServiceType] = useState<'نجار' | 'كهربائي' | 'سباك' | 'فني دش' | 'نقاش'>('كهربائي');
  const [isOrdering, setIsOrdering] = useState(false);
  const [rating, setRating] = useState<{[key: string]: number}>({});

  useEffect(() => {
    const q = query(
      collection(db, 'orders'),
      where('customerId', '==', user.id),
      orderBy('createdAt', 'desc')
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const ordersData = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));
      setOrders(ordersData);
    });

    return () => unsubscribe();
  }, [user.id]);

  const handleCreateOrder = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsOrdering(true);
    try {
      await addDoc(collection(db, 'orders'), {
        customerId: user.id,
        customerName: user.name,
        customerPhone: user.phone,
        address: user.address,
        serviceType,
        status: 'pending',
        createdAt: Date.now()
      });
      alert('تم إرسال طلبك بنجاح!');
    } catch (err) {
      alert('فشل إرسال الطلب');
    } finally {
      setIsOrdering(false);
    }
  };

  const handleRating = async (orderId: string, val: number) => {
    try {
      const orderRef = doc(db, 'orders', orderId);
      await updateDoc(orderRef, { rating: val });
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div className="min-h-screen bg-gray-100 pb-12">
      <nav className="bg-blue-900 text-white p-4 shadow-lg sticky top-0 z-50">
        <div className="container mx-auto flex justify-between items-center">
          <h1 className="text-2xl font-bold">الأسطى - {user.name}</h1>
          <button onClick={onLogout} className="bg-red-500 hover:bg-red-600 px-4 py-2 rounded-lg font-bold transition">خروج</button>
        </div>
      </nav>

      <div className="container mx-auto px-4 mt-8">
        <div className="bg-white rounded-2xl shadow-md p-6 mb-8 border-t-4 border-orange-500">
          <h2 className="text-xl font-bold text-blue-900 mb-4">طلب خدمة جديدة</h2>
          <form onSubmit={handleCreateOrder} className="flex flex-col md:flex-row gap-4 items-end">
            <div className="flex-1 w-full">
              <label className="block text-sm font-bold text-gray-700 mb-2">اختر الخدمة المطلوبة</label>
              <select 
                value={serviceType} 
                onChange={e => setServiceType(e.target.value as any)}
                className="w-full p-3 border rounded-lg bg-gray-50 outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="كهربائي">كهربائي</option>
                <option value="سباك">سباك</option>
                <option value="نجار">نجار</option>
                <option value="فني دش">فني دش</option>
                <option value="نقاش">نقاش</option>
              </select>
            </div>
            <button 
              type="submit" 
              disabled={isOrdering}
              className="bg-orange-600 hover:bg-orange-700 text-white font-bold px-8 py-3 rounded-lg shadow-md transition disabled:opacity-50"
            >
              {isOrdering ? 'جاري الطلب...' : 'إرسال الطلب الآن'}
            </button>
          </form>
        </div>

        <h2 className="text-2xl font-bold text-gray-800 mb-4">طلباتك الحالية والسابقة</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {orders.length === 0 ? (
            <p className="text-gray-500 col-span-3 text-center py-10">لا توجد طلبات حتى الآن</p>
          ) : (
            orders.map(order => (
              <div key={order.id} className="bg-white p-5 rounded-xl shadow-sm border border-gray-200 hover:shadow-md transition">
                <div className="flex justify-between items-start mb-3">
                  <span className="bg-blue-100 text-blue-800 text-xs font-bold px-2 py-1 rounded">{order.serviceType}</span>
                  <span className={`text-xs font-bold px-2 py-1 rounded ${
                    order.status === 'pending' ? 'bg-yellow-100 text-yellow-800' :
                    order.status === 'assigned' ? 'bg-blue-100 text-blue-800' :
                    order.status === 'completed' ? 'bg-green-100 text-green-800' :
                    'bg-red-100 text-red-800'
                  }`}>
                    {order.status === 'pending' && 'قيد الانتظار'}
                    {order.status === 'assigned' && 'تم التعيين'}
                    {order.status === 'completed' && 'تم التنفيذ'}
                    {order.status === 'failed' && 'حدث خطأ'}
                  </span>
                </div>
                <div className="mb-3">
                  <p className="text-gray-400 text-xs">تاريخ الطلب: {new Date(order.createdAt).toLocaleString('ar-EG')}</p>
                </div>
                {order.technicianName && (
                  <div className="bg-gray-50 p-3 rounded-lg border border-dashed border-gray-300 mb-3">
                    <p className="text-sm font-bold text-blue-900">الفني: {order.technicianName}</p>
                    <p className="text-xs text-gray-600">هاتف الفني: {order.technicianPhone}</p>
                  </div>
                )}

                {order.status === 'completed' && !order.rating && (
                  <div className="mt-4 pt-4 border-t border-gray-100">
                    <p className="text-sm text-gray-600 mb-2">قيم الفني:</p>
                    <div className="flex gap-2">
                      {[1, 2, 3, 4, 5].map(star => (
                        <button 
                          key={star} 
                          onClick={() => handleRating(order.id, star)}
                          className="text-2xl hover:scale-110 transition grayscale hover:grayscale-0 focus:grayscale-0"
                        >⭐</button>
                      ))}
                    </div>
                  </div>
                )}
                {order.rating && (
                  <div className="mt-4 pt-4 border-t border-gray-100">
                    <p className="text-sm font-bold text-yellow-600">تقييمك: {'⭐'.repeat(order.rating)}</p>
                  </div>
                )}
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

export default CustomerDashboard;

import React, { useState, useEffect } from 'react';
import { collection, query, where, onSnapshot, updateDoc, doc, orderBy } from 'firebase/firestore';
import { db } from '../firebase';
import { User, Order } from '../types';

interface TechnicianDashboardProps {
  user: User;
  onLogout: () => void;
}

const TechnicianDashboard: React.FC<TechnicianDashboardProps> = ({ user, onLogout }) => {
  const [availableOrders, setAvailableOrders] = useState<Order[]>([]);
  const [myOrders, setMyOrders] = useState<Order[]>([]);

  useEffect(() => {
    // Orders in technician's specialty that are pending
    const qAvailable = query(
      collection(db, 'orders'),
      where('serviceType', '==', user.specialty),
      where('status', '==', 'pending'),
      orderBy('createdAt', 'desc')
    );

    // Orders assigned to this technician
    const qMy = query(
      collection(db, 'orders'),
      where('technicianId', '==', user.id),
      orderBy('createdAt', 'desc')
    );

    const unsubAvailable = onSnapshot(qAvailable, (snapshot) => {
      setAvailableOrders(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order)));
    });

    const unsubMy = onSnapshot(qMy, (snapshot) => {
      setMyOrders(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order)));
    });

    return () => {
      unsubAvailable();
      unsubMy();
    };
  }, [user.id, user.specialty]);

  const acceptOrder = async (orderId: string) => {
    try {
      const orderRef = doc(db, 'orders', orderId);
      await updateDoc(orderRef, {
        status: 'assigned',
        technicianId: user.id,
        technicianName: user.name,
        technicianPhone: user.phone
      });
      alert('تم قبول المهمة بنجاح!');
    } catch (err) {
      alert('حدث خطأ أثناء قبول المهمة');
    }
  };

  const updateStatus = async (orderId: string, status: 'completed' | 'failed') => {
    try {
      const orderRef = doc(db, 'orders', orderId);
      await updateDoc(orderRef, { status });
    } catch (err) {
      alert('حدث خطأ أثناء التحديث');
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 pb-12">
      <nav className="bg-green-700 text-white p-4 shadow-lg sticky top-0 z-50">
        <div className="container mx-auto flex justify-between items-center">
          <div>
            <h1 className="text-2xl font-bold">الأسطى - {user.name}</h1>
            <p className="text-xs bg-green-800 px-2 py-0.5 rounded inline-block">تخصص: {user.specialty}</p>
          </div>
          <button onClick={onLogout} className="bg-white text-green-700 px-4 py-2 rounded-lg font-bold transition">خروج</button>
        </div>
      </nav>

      <div className="container mx-auto px-4 mt-8 grid grid-cols-1 lg:grid-cols-2 gap-10">
        {/* Available Tasks Section */}
        <div>
          <h2 className="text-xl font-bold text-gray-800 mb-4 flex items-center gap-2">
            <span className="w-3 h-3 bg-red-500 rounded-full animate-pulse"></span>
            مهام متاحة في تخصصك ({availableOrders.length})
          </h2>
          <div className="space-y-4">
            {availableOrders.length === 0 ? (
              <p className="text-gray-400 italic">لا توجد مهام جديدة حالياً</p>
            ) : (
              availableOrders.map(order => (
                <div key={order.id} className="bg-white p-6 rounded-xl shadow-sm border border-gray-200">
                  <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-lg text-blue-900">{order.customerName}</h3>
                    <span className="text-sm text-gray-500">{new Date(order.createdAt).toLocaleTimeString('ar-EG')}</span>
                  </div>
                  <p className="text-gray-600 mb-2">📍 {order.address}</p>
                  <p className="text-gray-600 mb-6">📞 {order.customerPhone}</p>
                  <button 
                    onClick={() => acceptOrder(order.id)}
                    className="w-full bg-green-600 hover:bg-green-700 text-white font-bold py-2 rounded-lg transition"
                  >
                    قبول المهمة
                  </button>
                </div>
              ))
            )}
          </div>
        </div>

        {/* My Tasks Section */}
        <div>
          <h2 className="text-xl font-bold text-gray-800 mb-4">مهامك النشطة والسجل</h2>
          <div className="space-y-4">
            {myOrders.length === 0 ? (
              <p className="text-gray-400 italic">ليس لديك مهام مسجلة بعد</p>
            ) : (
              myOrders.map(order => (
                <div key={order.id} className="bg-white p-6 rounded-xl shadow-sm border border-blue-200">
                  <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-blue-900">{order.customerName}</h3>
                    <span className={`text-xs font-bold px-2 py-1 rounded ${
                      order.status === 'assigned' ? 'bg-blue-100 text-blue-800' :
                      order.status === 'completed' ? 'bg-green-100 text-green-800' :
                      'bg-red-100 text-red-800'
                    }`}>
                      {order.status === 'assigned' ? 'جاري العمل' : order.status === 'completed' ? 'تم التنفيذ' : 'فشل'}
                    </span>
                  </div>
                  <p className="text-gray-600 text-sm mb-4">📍 {order.address}</p>

                  {order.status === 'assigned' && (
                    <div className="flex gap-2">
                      <button 
                        onClick={() => updateStatus(order.id, 'completed')}
                        className="flex-1 bg-green-100 text-green-700 font-bold py-2 rounded-lg hover:bg-green-200 transition"
                      >تم التنفيذ ✅</button>
                      <button 
                        onClick={() => updateStatus(order.id, 'failed')}
                        className="flex-1 bg-red-100 text-red-700 font-bold py-2 rounded-lg hover:bg-red-200 transition"
                      >حدث خطأ ❌</button>
                    </div>
                  )}
                  {order.rating && (
                    <p className="mt-2 text-yellow-500 font-bold">تقييم العميل: {'⭐'.repeat(order.rating)}</p>
                  )}
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default TechnicianDashboard;

import React, { useState, useEffect, useRef } from 'react';
import { collection, query, onSnapshot, orderBy, doc, updateDoc, deleteDoc, getDocs } from 'firebase/firestore';
import { db } from '../firebase';
import { User, Order } from '../types';

interface AdminDashboardProps {
  user: User;
  onLogout: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user, onLogout }) => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [activeTab, setActiveTab] = useState<'stats' | 'orders' | 'users' | 'settings'>('stats');
  const [newPassword, setNewPassword] = useState('');
  const prevOrdersCount = useRef(0);

  useEffect(() => {
    const unsubOrders = onSnapshot(query(collection(db, 'orders'), orderBy('createdAt', 'desc')), (snap) => {
      const ordersData = snap.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));

      // Visual & Audio Alert for new orders
      if (ordersData.length > prevOrdersCount.current && prevOrdersCount.current !== 0) {
        const audio = new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3');
        audio.play().catch(e => console.log('Audio error', e));
        alert('تنبيه: يوجد طلب خدمة جديد في النظام!');
      }
      prevOrdersCount.current = ordersData.length;
      setOrders(ordersData);
    });

    const unsubUsers = onSnapshot(collection(db, 'users'), (snap) => {
      setUsers(snap.docs.map(doc => ({ id: doc.id, ...doc.data() } as User)));
    });

    return () => {
      unsubOrders();
      unsubUsers();
    };
  }, []);

  const changeAdminPassword = async () => {
    if (!newPassword) return;
    try {
      const userRef = doc(db, 'users', user.id);
      await updateDoc(userRef, { password: newPassword });
      alert('تم تغيير كلمة المرور بنجاح');
      setNewPassword('');
    } catch (err) {
      alert('خطأ في التغيير');
    }
  };

  const deleteUser = async (userId: string) => {
    if (confirm('هل أنت متأكد من حذف هذا المستخدم؟')) {
      await deleteDoc(doc(db, 'users', userId));
    }
  };

  const stats = {
    totalOrders: orders.length,
    activeOrders: orders.filter(o => o.status === 'pending' || o.status === 'assigned').length,
    completedOrders: orders.filter(o => o.status === 'completed').length,
    totalCustomers: users.filter(u => u.role === 'customer').length,
    totalTechnicians: users.filter(u => u.role === 'technician').length,
  };

  return (
    <div className="min-h-screen bg-gray-100 flex">
      {/* Sidebar */}
      <aside className="w-64 bg-gray-900 text-white hidden md:block">
        <div className="p-6">
          <h1 className="text-2xl font-bold mb-2">لوحة الإدارة</h1>
          <p className="text-gray-400 text-sm">مرحباً {user.role === 'manager' ? 'مدير النظام' : 'مشرف'}</p>
        </div>
        <nav className="mt-10 px-4 space-y-2">
          <button 
            onClick={() => setActiveTab('stats')}
            className={`w-full text-right p-3 rounded transition ${activeTab === 'stats' ? 'bg-blue-700' : 'hover:bg-gray-800'}`}
          >📊 الإحصائيات العامة</button>
          <button 
            onClick={() => setActiveTab('orders')}
            className={`w-full text-right p-3 rounded transition ${activeTab === 'orders' ? 'bg-blue-700' : 'hover:bg-gray-800'}`}
          >📦 إدارة الطلبات</button>
          <button 
            onClick={() => setActiveTab('users')}
            className={`w-full text-right p-3 rounded transition ${activeTab === 'users' ? 'bg-blue-700' : 'hover:bg-gray-800'}`}
          >👥 قاعدة بيانات المستخدمين</button>
          <button 
            onClick={() => setActiveTab('settings')}
            className={`w-full text-right p-3 rounded transition ${activeTab === 'settings' ? 'bg-blue-700' : 'hover:bg-gray-800'}`}
          >⚙️ الإعدادات</button>
          <div className="pt-10">
            <button onClick={onLogout} className="w-full bg-red-600 p-3 rounded font-bold hover:bg-red-700 transition">تسجيل الخروج</button>
          </div>
        </nav>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto">
        <div className="p-8">
          {activeTab === 'stats' && (
            <div>
              <h2 className="text-3xl font-bold text-gray-800 mb-8">نظرة عامة على النظام</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <StatCard title="إجمالي الطلبات" val={stats.totalOrders} color="bg-blue-500" />
                <StatCard title="طلبات نشطة" val={stats.activeOrders} color="bg-orange-500" />
                <StatCard title="مهام مكتملة" val={stats.completedOrders} color="bg-green-500" />
                <StatCard title="عدد الفنيين" val={stats.totalTechnicians} color="bg-indigo-500" />
              </div>
            </div>
          )}

          {activeTab === 'orders' && (
            <div>
              <h2 className="text-2xl font-bold mb-6">قائمة الطلبات</h2>
              <div className="bg-white rounded-xl shadow-sm overflow-hidden border">
                <table className="w-full text-right border-collapse">
                  <thead className="bg-gray-50 border-b">
                    <tr>
                      <th className="p-4 text-sm font-bold">العميل</th>
                      <th className="p-4 text-sm font-bold">الخدمة</th>
                      <th className="p-4 text-sm font-bold">الفني</th>
                      <th className="p-4 text-sm font-bold">الحالة</th>
                      <th className="p-4 text-sm font-bold">التاريخ</th>
                    </tr>
                  </thead>
                  <tbody>
                    {orders.map(order => (
                      <tr key={order.id} className="border-b hover:bg-gray-50 transition">
                        <td className="p-4 text-sm font-medium">{order.customerName}</td>
                        <td className="p-4 text-sm font-medium">{order.serviceType}</td>
                        <td className="p-4 text-sm text-gray-500">{order.technicianName || '—'}</td>
                        <td className="p-4 text-sm">
                          <span className={`px-2 py-1 rounded-full text-xs font-bold ${
                            order.status === 'pending' ? 'bg-yellow-100 text-yellow-800' :
                            order.status === 'assigned' ? 'bg-blue-100 text-blue-800' :
                            'bg-green-100 text-green-800'
                          }`}>
                            {order.status}
                          </span>
                        </td>
                        <td className="p-4 text-sm text-gray-400">{new Date(order.createdAt).toLocaleDateString('ar-EG')}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {activeTab === 'users' && (
            <div>
              <h2 className="text-2xl font-bold mb-6">إدارة المستخدمين</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {users.map(u => (
                  <div key={u.id} className="bg-white p-5 rounded-xl border flex justify-between items-start">
                    <div>
                      <p className="font-bold text-gray-800">{u.name}</p>
                      <p className="text-xs text-blue-600 font-bold uppercase">{u.role}</p>
                      <p className="text-sm text-gray-500">{u.phone}</p>
                      {u.specialty && <p className="text-xs text-gray-400">تخصص: {u.specialty}</p>}
                    </div>
                    {u.role !== 'manager' && (
                      <button onClick={() => deleteUser(u.id)} className="text-red-500 hover:text-red-700">🗑️</button>
                    )}
                  </div>
                ))}
              </div>
            </div>
          )}

          {activeTab === 'settings' && (
            <div className="max-w-md">
              <h2 className="text-2xl font-bold mb-6">إعدادات الحساب</h2>
              <div className="bg-white p-6 rounded-xl border">
                <label className="block text-sm font-bold mb-2">تغيير كلمة المرور</label>
                <input 
                  type="password" 
                  value={newPassword} 
                  onChange={e => setNewPassword(e.target.value)}
                  className="w-full p-2 border rounded mb-4" 
                  placeholder="كلمة المرور الجديدة"
                />
                <button onClick={changeAdminPassword} className="w-full bg-blue-700 text-white py-2 rounded font-bold">تحديث كلمة المرور</button>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

const StatCard = ({ title, val, color }: { title: string, val: number, color: string }) => (
  <div className={`${color} text-white p-6 rounded-2xl shadow-lg`}>
    <p className="text-white/80 text-sm font-bold">{title}</p>
    <p className="text-4xl font-extrabold mt-1">{val}</p>
  </div>
);

export default AdminDashboard;

