    // مراقبة الطلبات لحظياً
    const unsubOrders = onSnapshot(query(collection(db, 'orders'), orderBy('createdAt', 'desc')), (snap) => {
      const ordersData = snap.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));

      // تنبيه صوتي ومرئي عند دخول طلب جديد فقط (ليس عند التحميل الأول)
      if (prevOrdersCount.current !== null && ordersData.length > prevOrdersCount.current) {
        const audio = new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3');
        audio.play().catch(e => console.log('Audio disabled by browser policy until interaction', e));

        // إشعار مرئي
        if (Notification.permission === "granted") {
          new Notification("الأسطى: طلب جديد!", { body: `يوجد طلب جديد لخدمة ${ordersData[0].serviceType}` });
        }
      }
      prevOrdersCount.current = ordersData.length;
      setOrders(ordersData);
    });

    // مراقبة المستخدمين لحظياً
    const unsubUsers = onSnapshot(collection(db, 'users'), (snap) => {
      setUsers(snap.docs.map(doc => ({ id: doc.id, ...doc.data() } as User)));
    });

    // طلب إذن التنبيهات
    if (Notification.permission !== "granted") {
      Notification.requestPermission();
    }

    return () => {
      unsubOrders();
      unsubUsers();
    };
  }, []);

  const changeAdminPassword = async () => {
    if (!newPassword) return;
    try {
      const userRef = doc(db, 'users', user.id);
      await updateDoc(userRef, { password: newPassword });
      alert('تم تغيير كلمة المرور بنجاح');
      setNewPassword('');
    } catch (err) {
      alert('خطأ في التغيير');
    }
  };

  const deleteUser = async (userId: string) => {
    if (confirm('هل أنت متأكد من حذف هذا المستخدم نهائياً؟')) {
      await deleteDoc(doc(db, 'users', userId));
    }
  };

  const stats = {
    totalOrders: orders.length,
    activeOrders: orders.filter(o => o.status === 'pending' || o.status === 'assigned').length,
    completedOrders: orders.filter(o => o.status === 'completed').length,
    totalCustomers: users.filter(u => u.role === 'customer').length,
    totalTechnicians: users.filter(u => u.role === 'technician').length,
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row">
      {/* Sidebar */}
      <aside className="w-full md:w-64 bg-slate-900 text-white shadow-2xl">
        <div className="p-8 text-center border-b border-slate-800">
          <h1 className="text-3xl font-black text-blue-400 mb-1">الأسطى</h1>
          <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">لوحة التحكم</p>
        </div>
        <nav className="mt-8 px-4 space-y-2">
          {[
            { id: 'stats', label: '📊 الإحصائيات', icon: 'Chart' },
            { id: 'orders', label: '📦 الطلبات', icon: 'Orders' },
            { id: 'users', label: '👥 المستخدمين', icon: 'Users' },
            { id: 'settings', label: '⚙️ الإعدادات', icon: 'Settings' }
          ].map(item => (
            <button 
              key={item.id}
              onClick={() => setActiveTab(item.id as any)}
              className={`w-full text-right p-4 rounded-xl font-bold transition-all duration-300 flex items-center justify-between ${
                activeTab === item.id ? 'bg-blue-600 text-white shadow-lg translate-x-1' : 'text-slate-400 hover:bg-slate-800 hover:text-white'
              }`}
            >
              <span>{item.label}</span>
              {activeTab === item.id && <div className="w-2 h-2 bg-white rounded-full"></div>}
            </button>
          ))}
          <div className="pt-10 border-t border-slate-800 mt-10">
            <button onClick={onLogout} className="w-full bg-red-500/10 text-red-500 p-4 rounded-xl font-bold hover:bg-red-500 hover:text-white transition-all shadow-sm">تسجيل الخروج</button>
          </div>
        </nav>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto p-4 md:p-10">
        <header className="mb-10 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <h2 className="text-3xl font-extrabold text-slate-800">أهلاً بك، {user.name}</h2>
            <p className="text-slate-500 font-medium">نظام المراقبة يعمل الآن بصورة لحظية 🟢</p>
          </div>
          <div className="flex items-center gap-3 bg-white p-3 rounded-2xl shadow-sm border border-slate-100">
