            <StatCard title="طلبات نشطة" val={stats.activeOrders} color="from-orange-500 to-orange-700" />
            <StatCard title="مهام مكتملة" val={stats.completedOrders} color="from-emerald-500 to-emerald-700" />
            <StatCard title="الفنيين المتاحين" val={stats.totalTechnicians} color="from-indigo-500 to-indigo-700" />
          </div>
        )}

