import React, { useState, useEffect } from 'react';
import { User } from './types';
import Login from './views/Login';
import Register from './views/Register';
import ForgotPassword from './views/ForgotPassword';
import CustomerDashboard from './views/CustomerDashboard';
import TechnicianDashboard from './views/TechnicianDashboard';
import AdminDashboard from './views/AdminDashboard';
import Home from './views/Home';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [view, setView] = useState<'home' | 'login' | 'register' | 'forgot'>('home');
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const savedUser = localStorage.getItem('alOstaUser');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }
    setIsLoading(false);
  }, []);

  const handleLogin = (userData: User) => {
    setUser(userData);
    localStorage.setItem('alOstaUser', JSON.stringify(userData));
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('alOstaUser');
    setView('home');
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-screen bg-slate-900">
        <div className="text-white text-2xl font-bold animate-pulse">الأسطى... جاري التحميل</div>
      </div>
    );
  }

  // If user is logged in, show their dashboard
  if (user) {
    switch (user.role) {
      case 'customer':
        return <CustomerDashboard user={user} onLogout={handleLogout} />;
      case 'technician':
        return <TechnicianDashboard user={user} onLogout={handleLogout} />;
      case 'admin':
      case 'manager':
        return <AdminDashboard user={user} onLogout={handleLogout} />;
      default:
        return <div className="p-10 text-center">خطأ في تحديد الدور</div>;
    }
  }

  // If not logged in, handle public views
  switch (view) {
    case 'register':
      return <Register onSwitch={() => setView('login')} />;
    case 'forgot':
      return <ForgotPassword onSwitch={() => setView('login')} />;
    case 'login':
      return <Login 
        onLogin={handleLogin} 
        onSwitchRegister={() => setView('register')} 
        onSwitchForgot={() => setView('forgot')}
        onBackHome={() => setView('home')}
      />;
    default:
      return <Home 
        onStartService={() => setView('login')} 
        onJoinAsTech={() => setView('register')}
        onLoginNav={() => setView('login')}
        onRegisterNav={() => setView('register')}
      />;
  }
};

export default App;

