import React, { useState, useEffect } from 'react';
import { collection, addDoc, query, where, onSnapshot, updateDoc, doc } from 'firebase/firestore';
import { db } from '../firebase';
import { User, Order, OrderStatus } from '../types';

interface CustomerDashboardProps {
  user: User;
  onLogout: () => void;
}

const CustomerDashboard: React.FC<CustomerDashboardProps> = ({ user, onLogout }) => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [serviceType, setServiceType] = useState<'نجار' | 'كهربائي' | 'سباك' | 'فني دش' | 'نقاش'>('كهربائي');
  const [isOrdering, setIsOrdering] = useState(false);

  useEffect(() => {
    // إزالة orderBy لتجنب الحاجة لفهرس مركب
    const q = query(
      collection(db, 'orders'),
      where('customerId', '==', user.id)
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const ordersData = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));
      // الترتيب يدوياً في المتصفح لضمان ظهور الأحدث أولاً
      const sortedOrders = ordersData.sort((a, b) => b.createdAt - a.createdAt);
      setOrders(sortedOrders);
    });

    return () => unsubscribe();
  }, [user.id]);

  const handleCreateOrder = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsOrdering(true);
    try {
      await addDoc(collection(db, 'orders'), {
        customerId: user.id,
        customerName: user.name,
        customerPhone: user.phone,
        address: user.address,
        serviceType,
        status: 'pending',
        createdAt: Date.now()
      });
      alert('تم إرسال طلبك بنجاح!');
    } catch (err) {
      alert('فشل إرسال الطلب');
    } finally {
      setIsOrdering(false);
    }
  };

  const handleRating = async (orderId: string, val: number) => {
    try {
      const orderRef = doc(db, 'orders', orderId);
      await updateDoc(orderRef, { rating: val });
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div className="min-h-screen bg-gray-100 pb-12">
      <nav className="bg-blue-900 text-white p-4 shadow-lg sticky top-0 z-50">
        <div className="container mx-auto flex justify-between items-center">
          <h1 className="text-2xl font-bold">الأسطى - {user.name}</h1>
          <button onClick={onLogout} className="bg-red-500 hover:bg-red-600 px-4 py-2 rounded-lg font-bold transition">خروج</button>
        </div>
      </nav>

      <div className="container mx-auto px-4 mt-8">
        <div className="bg-white rounded-2xl shadow-md p-6 mb-8 border-t-4 border-orange-500">
          <h2 className="text-xl font-bold text-blue-900 mb-4">طلب خدمة جديدة</h2>
          <form onSubmit={handleCreateOrder} className="flex flex-col md:flex-row gap-4 items-end">
            <div className="flex-1 w-full">
              <label className="block text-sm font-bold text-gray-700 mb-2">اختر الخدمة المطلوبة</label>
              <select 
                value={serviceType} 
                onChange={e => setServiceType(e.target.value as any)}
                className="w-full p-3 border rounded-lg bg-gray-50 outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="كهربائي">كهربائي</option>
                <option value="سباك">سباك</option>
                <option value="نجار">نجار</option>
                <option value="فني دش">فني دش</option>
                <option value="نقاش">نقاش</option>
              </select>
            </div>
            <button 
              type="submit" 
              disabled={isOrdering}
              className="bg-orange-600 hover:bg-orange-700 text-white font-bold px-8 py-3 rounded-lg shadow-md transition disabled:opacity-50"
            >
              {isOrdering ? 'جاري الطلب...' : 'إرسال الطلب الآن'}
            </button>
          </form>
        </div>

        <h2 className="text-2xl font-bold text-gray-800 mb-4">طلباتك الحالية والسابقة</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {orders.length === 0 ? (
            <p className="text-gray-500 col-span-3 text-center py-10">لا توجد طلبات حتى الآن</p>
          ) : (
            orders.map(order => (
              <div key={order.id} className="bg-white p-5 rounded-xl shadow-sm border border-gray-200 hover:shadow-md transition">
                <div className="flex justify-between items-start mb-3">
                  <span className="bg-blue-100 text-blue-800 text-xs font-bold px-2 py-1 rounded">{order.serviceType}</span>
                  <span className={`text-xs font-bold px-2 py-1 rounded ${
                    order.status === 'pending' ? 'bg-yellow-100 text-yellow-800' :
                    order.status === 'assigned' ? 'bg-blue-100 text-blue-800' :
                    order.status === 'completed' ? 'bg-green-100 text-green-800' :
                    'bg-red-100 text-red-800'
                  }`}>
                    {order.status === 'pending' && 'قيد الانتظار'}
                    {order.status === 'assigned' && 'تم التعيين'}
                    {order.status === 'completed' && 'تم التنفيذ'}
                    {order.status === 'failed' && 'حدث خطأ'}
                  </span>
                </div>
                <div className="mb-3">
                  <p className="text-gray-400 text-xs">تاريخ الطلب: {new Date(order.createdAt).toLocaleString('ar-EG')}</p>
                </div>
                {order.technicianName && (
                  <div className="bg-gray-50 p-3 rounded-lg border border-dashed border-gray-300 mb-3">
                    <p className="text-sm font-bold text-blue-900">الفني: {order.technicianName}</p>
                    <p className="text-xs text-gray-600">هاتف الفني: {order.technicianPhone}</p>
                  </div>
                )}

                {order.status === 'completed' && !order.rating && (
                  <div className="mt-4 pt-4 border-t border-gray-100">
                    <p className="text-sm text-gray-600 mb-2">قيم الفني:</p>
                    <div className="flex gap-2">
                      {[1, 2, 3, 4, 5].map(star => (
                        <button 
                          key={star} 
                          onClick={() => handleRating(order.id, star)}
                          className="text-2xl hover:scale-110 transition grayscale hover:grayscale-0 focus:grayscale-0"
                        >⭐</button>
                      ))}
                    </div>
                  </div>
                )}
                {order.rating && (
                  <div className="mt-4 pt-4 border-t border-gray-100">
                    <p className="text-sm font-bold text-yellow-600">تقييمك: {'⭐'.repeat(order.rating)}</p>
                  </div>
                )}
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

export default CustomerDashboard;

