const StatCard = ({ title, val, color }: { title: string, val: number, color: string }) => {
  return (
    <div className={`bg-gradient-to-br ${color} text-white p-8 rounded-[2rem] shadow-2xl relative overflow-hidden group hover:scale-[1.02] transition-transform cursor-default`}>
