import React, { useState, useEffect } from 'react';
import { collection, addDoc, query, where, onSnapshot, updateDoc, doc } from 'firebase/firestore';
import { db } from '../firebase';
import { User, Order } from '../types';

interface CustomerDashboardProps {
  user: User;
  onLogout: () => void;
}

const CustomerDashboard: React.FC<CustomerDashboardProps> = ({ user, onLogout }) => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [serviceType, setServiceType] = useState<'نجار' | 'كهربائي' | 'سباك' | 'فني دش' | 'نقاش'>('كهربائي');
  const [isOrdering, setIsOrdering] = useState(false);

  useEffect(() => {
    const q = query(collection(db, 'orders'), where('customerId', '==', user.id));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const ordersData = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));
      setOrders(ordersData.sort((a, b) => b.createdAt - a.createdAt));
    });
    return () => unsubscribe();
  }, [user.id]);

  const addActivityLog = async (action: string) => {
    try {
      await addDoc(collection(db, 'activity_logs'), {
        userId: user.id,
        userName: user.name,
        action,
        timestamp: Date.now()
      });
    } catch (e) { console.error(e); }
  };

  const handleCreateOrder = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsOrdering(true);
    try {
      await addDoc(collection(db, 'orders'), {
        customerId: user.id,
        customerName: user.name,
        customerPhone: user.phone,
        address: user.address,
        serviceType,
        status: 'pending',
        createdAt: Date.now()
      });
      await addActivityLog(`طلب خدمة جديدة: ${serviceType}`);
      alert('تم إرسال طلبك بنجاح!');
    } catch (err) {
      alert('فشل إرسال الطلب');
    } finally {
      setIsOrdering(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row font-sans">
      {/* Sidebar for stats & log */}
      <aside className="w-full md:w-80 bg-white border-l border-gray-100 p-8 shadow-sm">
        <div className="mb-10 text-center">
           <div className="w-20 h-20 bg-blue-100 rounded-3xl flex items-center justify-center mx-auto mb-4 text-3xl">👤</div>
           <h2 className="text-xl font-black text-blue-900">{user.name}</h2>
           <p className="text-gray-400 font-bold text-sm">عميل مميز</p>
        </div>

        <div className="space-y-6">
           <h3 className="text-sm font-black text-blue-900/40 uppercase tracking-widest">سجل النشاطات</h3>
           <div className="space-y-4 max-h-[400px] overflow-y-auto pr-2">
              {orders.slice(0, 5).map(o => (
                <div key={o.id} className="flex gap-4 items-start border-r-2 border-orange-500 pr-4 py-2">
                   <div>
                      <p className="text-xs font-black text-blue-900">طلب {o.serviceType}</p>
                      <p className="text-[10px] text-gray-400 font-bold">{new Date(o.createdAt).toLocaleString('ar-EG')}</p>
                   </div>
                </div>
              ))}
              {orders.length === 0 && <p className="text-xs text-gray-300 italic">لا توجد نشاطات مؤخراً</p>}
           </div>
        </div>

        <button onClick={onLogout} className="w-full mt-12 bg-red-50 text-red-500 font-black py-4 rounded-2xl hover:bg-red-500 hover:text-white transition-all">تسجيل الخروج</button>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-8 md:p-12 overflow-y-auto">
        <div className="max-w-4xl mx-auto">
          <header className="mb-12">
             <h1 className="text-4xl font-black text-blue-900 mb-2">أهلاً بك في الأسطى</h1>
             <p className="text-gray-400 font-bold">كل ما تحتاجه لصيانة منزلك في مكان واحد</p>
          </header>

          <section className="bg-white p-10 rounded-[2.5rem] shadow-xl border border-gray-50 mb-12">
            <h3 className="text-2xl font-black text-blue-900 mb-6">طلب خدمة جديدة</h3>
            <form onSubmit={handleCreateOrder} className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-sm font-black text-gray-400 mb-2 uppercase">نوع الفني</label>
                  <select 
                    value={serviceType} 
                    onChange={e => setServiceType(e.target.value as any)}
                    className="w-full bg-gray-50 p-4 rounded-2xl border-none outline-none focus:ring-2 focus:ring-blue-500 font-bold"
                  >
                    <option value="كهربائي">كهربائي</option>
                    <option value="سباك">سباك</option>
                    <option value="نجار">نجار</option>
                    <option value="فني دش">فني دش</option>
                    <option value="نقاش">نقاش</option>
                  </select>
                </div>
                <div className="flex items-end">
                  <button type="submit" disabled={isOrdering} className="w-full bg-orange-500 hover:bg-orange-600 text-white font-black py-4 rounded-2xl shadow-xl shadow-orange-500/20 transition-all transform hover:scale-[1.02]">
                    {isOrdering ? 'جاري الإرسال...' : 'تأكيد الطلب'}
                  </button>
                </div>
              </div>
            </form>
          </section>

          <h3 className="text-2xl font-black text-blue-900 mb-6">طلباتي السابقة</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {orders.map(order => (
              <div key={order.id} className="bg-white p-6 rounded-[2rem] shadow-sm border border-gray-100 hover:shadow-md transition-shadow">
                <div className="flex justify-between items-center mb-4">
                  <span className="bg-blue-50 text-blue-600 px-4 py-1 rounded-full text-xs font-black uppercase tracking-tighter">{order.serviceType}</span>
                  <span className={`text-[10px] font-black px-3 py-1 rounded-lg ${
                    order.status === 'pending' ? 'bg-amber-100 text-amber-600' :
                    order.status === 'assigned' ? 'bg-blue-100 text-blue-600' :
                    'bg-emerald-100 text-emerald-600'
                  }`}>
                    {order.status === 'pending' ? 'بانتظار فني' : order.status === 'assigned' ? 'جاري التنفيذ' : 'مكتمل'}
                  </span>
                </div>
                <p className="text-xs text-gray-400 font-bold mb-4">{new Date(order.createdAt).toLocaleDateString('ar-EG')}</p>
                {order.technicianName && (
                  <div className="bg-gray-50 p-4 rounded-2xl">
                     <p className="text-sm font-black text-blue-900">الفني: {order.technicianName}</p>
                     <p className="text-xs text-gray-400 font-bold">هاتف: {order.technicianPhone}</p>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      </main>
    </div>
  );
};

export default CustomerDashboard;

