import React, { useState, useEffect, useRef } from 'react';
import { collection, query, onSnapshot, doc, updateDoc, deleteDoc } from 'firebase/firestore';
import { db } from '../firebase';
import { User, Order } from '../types';

const StatCard = ({ title, val, color }: { title: string, val: number, color: string }) => {
  return (
    <div className={`bg-gradient-to-br ${color} text-white p-8 rounded-[2rem] shadow-2xl relative overflow-hidden group hover:scale-[1.02] transition-transform cursor-default`}>
      <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -mr-16 -mt-16 group-hover:scale-150 transition-transform duration-700"></div>
      <p className="text-white/80 text-xs font-black uppercase tracking-widest mb-2 relative z-10">{title}</p>
      <p className="text-5xl font-black relative z-10">{val}</p>
    </div>
  );
};

interface AdminDashboardProps {
  user: User;
  onLogout: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user, onLogout }) => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [activeTab, setActiveTab] = useState<'stats' | 'orders' | 'completed-log' | 'users' | 'settings'>('stats');
  const [newPassword, setNewPassword] = useState('');
  const prevOrdersCount = useRef<number | null>(null);

  useEffect(() => {
    const unsubOrders = onSnapshot(collection(db, 'orders'), (snap) => {
      const ordersData = snap.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));
      const sorted = ordersData.sort((a, b) => b.createdAt - a.createdAt);

      if (prevOrdersCount.current !== null && sorted.length > prevOrdersCount.current) {
        const audio = new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3');
        audio.play().catch(e => console.log('Audio disabled by browser policy', e));

        if (Notification.permission === "granted") {
          new Notification("الأسطى: طلب جديد!", { body: `يوجد طلب جديد لخدمة ${sorted[0].serviceType}` });
        }
      }
      prevOrdersCount.current = sorted.length;
      setOrders(sorted);
    });

    const unsubUsers = onSnapshot(collection(db, 'users'), (snap) => {
      setUsers(snap.docs.map(doc => ({ id: doc.id, ...doc.data() } as User)));
    });

    if (Notification.permission !== "granted") {
      Notification.requestPermission();
    }

    return () => {
      unsubOrders();
      unsubUsers();
    };
  }, []);

  const changeAdminPassword = async () => {
    if (!newPassword) return;
    try {
      const userRef = doc(db, 'users', user.id);
      await updateDoc(userRef, { password: newPassword });
      alert('تم تغيير كلمة المرور بنجاح');
      setNewPassword('');
    } catch (err) {
      alert('خطأ في التغيير');
    }
  };

  const deleteUser = async (userId: string) => {
    if (confirm('هل أنت متأكد من حذف هذا المستخدم نهائياً؟')) {
      await deleteDoc(doc(db, 'users', userId));
    }
  };

  const deleteOrder = async (orderId: string) => {
    if (confirm('هل أنت متأكد من حذف هذا الطلب نهائياً؟')) {
      await deleteDoc(doc(db, 'orders', orderId));
    }
  };

  const stats = {
    totalOrders: orders.length,
    activeOrders: orders.filter(o => o.status === 'pending' || o.status === 'assigned').length,
    completedOrders: orders.filter(o => o.status === 'completed' || o.status === 'failed').length,
    totalCustomers: users.filter(u => u.role === 'customer').length,
    totalTechnicians: users.filter(u => u.role === 'technician').length,
  };

  // تصفية الطلبات النشطة والمكتملة
  const currentActiveOrders = orders.filter(o => o.status === 'pending' || o.status === 'assigned');
  const completedOrdersLog = orders.filter(o => o.status === 'completed' || o.status === 'failed');

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row">
      <aside className="w-full md:w-64 bg-slate-900 text-white shadow-2xl">
        <div className="p-8 text-center border-b border-slate-800">
          <h1 className="text-3xl font-black text-blue-400 mb-1">الأسطى</h1>
          <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">لوحة التحكم</p>
        </div>
        <nav className="mt-8 px-4 space-y-2">
          {[
            { id: 'stats', label: '📊 الإحصائيات' },
            { id: 'orders', label: '📦 الطلبات الحالية' },
            { id: 'completed-log', label: '📜 سجل المكتملة' },
            { id: 'users', label: '👥 المستخدمين' },
            { id: 'settings', label: '⚙️ الإعدادات' }
          ].map(item => (
            <button 
              key={item.id}
              onClick={() => setActiveTab(item.id as any)}
              className={`w-full text-right p-4 rounded-xl font-bold transition-all duration-300 flex items-center justify-between ${
                activeTab === item.id ? 'bg-blue-600 text-white shadow-lg translate-x-1' : 'text-slate-400 hover:bg-slate-800 hover:text-white'
              }`}
            >
              <span>{item.label}</span>
              {activeTab === item.id && <div className="w-2 h-2 bg-white rounded-full"></div>}
            </button>
          ))}
          <div className="pt-10 border-t border-slate-800 mt-10">
            <button onClick={onLogout} className="w-full bg-red-500/10 text-red-500 p-4 rounded-xl font-bold hover:bg-red-500 hover:text-white transition-all shadow-sm">تسجيل الخروج</button>
          </div>
        </nav>
      </aside>

      <main className="flex-1 overflow-y-auto p-4 md:p-10">
        <header className="mb-10 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <h2 className="text-3xl font-extrabold text-slate-800">أهلاً بك، {user.name}</h2>
            <p className="text-slate-500 font-medium">نظام المراقبة يعمل الآن بصورة لحظية 🟢</p>
          </div>
          <div className="flex items-center gap-3 bg-white p-3 rounded-2xl shadow-sm border border-slate-100">
             <div className="w-3 h-3 bg-green-500 rounded-full animate-ping"></div>
             <span className="text-sm font-bold text-slate-600">اتصال Firestore نشط</span>
          </div>
        </header>

        {activeTab === 'stats' && (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 animate-fadeIn">
            <StatCard title="إجمالي الطلبات" val={stats.totalOrders} color="from-blue-500 to-blue-700" />
            <StatCard title="طلبات نشطة" val={stats.activeOrders} color="from-orange-500 to-orange-700" />
            <StatCard title="مهام منتهية" val={stats.completedOrders} color="from-emerald-500 to-emerald-700" />
            <StatCard title="الفنيين المتاحين" val={stats.totalTechnicians} color="from-indigo-500 to-indigo-700" />
          </div>
        )}

        {(activeTab === 'orders' || activeTab === 'completed-log') && (
          <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-100 animate-fadeIn">
             <div className="p-6 border-b border-slate-50 flex justify-between items-center">
                <h3 className="font-black text-xl text-slate-800">{activeTab === 'orders' ? 'الطلبات قيد التنفيذ' : 'سجل الطلبات المكتملة'}</h3>
             </div>
            <div className="overflow-x-auto">
              <table className="w-full text-right">
                <thead className="bg-slate-50 border-b border-slate-100">
                  <tr>
                    <th className="p-5 text-sm font-black text-slate-600">العميل</th>
                    <th className="p-5 text-sm font-black text-slate-600">نوع الخدمة</th>
                    <th className="p-5 text-sm font-black text-slate-600">الفني</th>
                    <th className="p-5 text-sm font-black text-slate-600">الحالة</th>
                    <th className="p-5 text-sm font-black text-slate-600">التاريخ</th>
                    <th className="p-5 text-sm font-black text-slate-600">إجراءات</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {(activeTab === 'orders' ? currentActiveOrders : completedOrdersLog).map(order => (
                    <tr key={order.id} className="hover:bg-blue-50/30 transition-colors">
                      <td className="p-5">
                        <p className="font-bold text-slate-800">{order.customerName}</p>
                        <p className="text-xs text-slate-400">{order.customerPhone}</p>
                      </td>
                      <td className="p-5">
                        <span className="bg-slate-100 text-slate-700 px-3 py-1 rounded-full text-xs font-bold">{order.serviceType}</span>
                      </td>
                      <td className="p-5 text-sm text-slate-600 font-medium">{order.technicianName || <span className="text-slate-300 italic">بانتظار فني...</span>}</td>
                      <td className="p-5 text-sm">
                        <span className={`px-4 py-1.5 rounded-full text-xs font-black uppercase tracking-tighter ${
                          order.status === 'pending' ? 'bg-amber-100 text-amber-700' :
                          order.status === 'assigned' ? 'bg-blue-100 text-blue-700' :
                          order.status === 'completed' ? 'bg-emerald-100 text-emerald-700' :
                          'bg-red-100 text-red-700'
                        }`}>
                          {order.status}
                        </span>
                      </td>
                      <td className="p-5 text-xs text-slate-400 font-bold">{new Date(order.createdAt).toLocaleString('ar-EG')}</td>
                      <td className="p-5">
                         <button 
                          onClick={() => deleteOrder(order.id)}
                          className="bg-red-50 text-red-500 px-3 py-1 rounded-lg font-bold text-xs hover:bg-red-500 hover:text-white transition"
                         >حذف</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {(activeTab === 'orders' ? currentActiveOrders : completedOrdersLog).length === 0 && (
                <div className="p-10 text-center text-slate-400 font-bold">لا توجد بيانات للعرض</div>
              )}
            </div>
          </div>
        )}

        {activeTab === 'users' && (
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 animate-fadeIn">
            {users.map(u => (
              <div key={u.id} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm hover:shadow-md transition-shadow flex justify-between items-center group">
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <p className="font-black text-slate-800">{u.name}</p>
                    <span className={`text-[10px] font-black px-2 py-0.5 rounded uppercase ${
                      u.role === 'customer' ? 'bg-blue-50 text-blue-600' : 
                      u.role === 'technician' ? 'bg-emerald-50 text-emerald-600' : 
                      'bg-purple-50 text-purple-600'
                    }`}>{u.role}</span>
                  </div>
                  <p className="text-sm text-slate-500 font-bold">{u.phone}</p>
                  {u.specialty && <p className="text-xs text-slate-400 mt-1 font-medium">تخصص: <span className="text-emerald-600">{u.specialty}</span></p>}
                </div>
                {u.role !== 'manager' && (
                  <button onClick={() => deleteUser(u.id)} className="w-10 h-10 flex items-center justify-center rounded-2xl bg-red-50 text-red-500 opacity-0 group-hover:opacity-100 transition-opacity hover:bg-red-500 hover:text-white">
                    <span className="text-lg">🗑️</span>
                  </button>
                )}
              </div>
            ))}
          </div>
        )}

        {activeTab === 'settings' && (
          <div className="max-w-xl animate-fadeIn">
            <div className="bg-white p-8 rounded-3xl border border-slate-100 shadow-xl">
              <h3 className="text-xl font-black text-slate-800 mb-6">تأمين الحساب</h3>
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-bold text-slate-700 mb-2">كلمة المرور الجديدة</label>
                  <input 
                    type="password" 
                    value={newPassword} 
                    onChange={e => setNewPassword(e.target.value)}
                    className="w-full p-4 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 outline-none transition-all" 
                    placeholder="••••••••"
                  />
                </div>
                <button onClick={changeAdminPassword} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black hover:bg-blue-600 transition-colors shadow-lg shadow-blue-500/10">حفظ التغييرات</button>
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

