import React, { useState } from 'react';
import { collection, query, where, getDocs } from 'firebase/firestore';
import { db } from '../firebase';
import { User } from '../types';

interface LoginProps {
  onLogin: (user: User) => void;
  onSwitchRegister: () => void;
  onSwitchForgot: () => void;
  onBackHome: () => void;
  onAdminPortal: () => void;
}

const Login: React.FC<LoginProps> = ({ onLogin, onSwitchRegister, onSwitchForgot, onBackHome, onAdminPortal }) => {
  const [phone, setPhone] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setError('');

    try {
      const q = query(collection(db, 'users'), where('phone', '==', phone));
      const querySnapshot = await getDocs(q);

      if (querySnapshot.empty) {
        setError('المستخدم غير موجود');
      } else {
        const userData = { id: querySnapshot.docs[0].id, ...querySnapshot.docs[0].data() } as User;
        if (userData.password === password) {
          onLogin(userData);
        } else {
          setError('كلمة المرور غير صحيحة');
        }
      }
    } catch (err) {
      setError('حدث خطأ أثناء الاتصال بالقاعدة');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col font-sans">
      <nav className="w-full bg-white px-6 py-4 flex justify-between items-center border-b border-gray-100">
        <div className="flex items-center gap-10">
          <div onClick={onBackHome} className="text-2xl font-black flex items-center gap-1 cursor-pointer">
            <span className="text-blue-900">EL OSTAA</span>
            <span className="text-orange-500">الأسطى</span>
          </div>
          <div className="hidden md:flex gap-6 text-sm font-bold text-gray-400">
             <span onClick={onBackHome} className="cursor-pointer hover:text-orange-500">الرئيسية</span>
          </div>
        </div>
        <div className="flex items-center gap-4">
          <button onClick={onSwitchRegister} className="bg-orange-500 text-white px-6 py-2 rounded-lg font-bold text-sm shadow-lg shadow-orange-500/20 hover:bg-orange-600 transition">سجل الآن</button>
        </div>
      </nav>

      <div className="flex-1 flex items-center justify-center p-6">
        <div className="bg-white w-full max-w-4xl rounded-[3rem] shadow-2xl overflow-hidden flex flex-col md:flex-row min-h-[500px]">
          <div className="flex-1 p-10 flex flex-col justify-center items-center text-center">
            <h2 className="text-3xl font-black text-blue-900 mb-8">دخول المستخدمين</h2>
            <form onSubmit={handleSubmit} className="w-full max-w-sm space-y-4">
              <input type="text" required value={phone} onChange={(e) => setPhone(e.target.value)} className="w-full bg-gray-50 px-6 py-4 rounded-2xl border-none outline-none focus:ring-2 focus:ring-blue-500 text-center font-bold" placeholder="رقم الهاتف" />
              <div className="relative w-full">
                <input 
                  type={showPassword ? "text" : "password"} 
                  required 
                  value={password} 
                  onChange={(e) => setPassword(e.target.value)} 
                  className="w-full bg-gray-50 px-6 py-4 rounded-2xl border-none outline-none focus:ring-2 focus:ring-blue-500 text-center font-bold" 
                  placeholder="كلمة المرور" 
                />
                <button 
                  type="button" 
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute left-4 top-1/2 -translate-y-1/2 text-xl hover:scale-110 transition p-2"
                >
                  {showPassword ? '🙈' : '👁️'}
                </button>
              </div>
              {error && <p className="text-red-500 text-sm font-bold">{error}</p>}
              <button type="submit" disabled={isSubmitting} className="w-full bg-blue-900 hover:bg-blue-800 text-white font-black py-4 rounded-2xl shadow-xl transition-all disabled:opacity-50 text-xl">
                {isSubmitting ? 'جاري الدخول...' : 'دخول'}
              </button>
            </form>
            <div className="mt-8 text-sm font-bold text-gray-400">
               ليس لديك حساب؟ <button onClick={onSwitchRegister} className="text-orange-500 underline">سجل الآن</button>
               <br />
               <button onClick={onSwitchForgot} className="mt-2 text-blue-900 hover:underline">نسيت كلمة المرور؟</button>
            </div>
          </div>

          <div className="w-full md:w-[40%] bg-blue-950 p-10 flex flex-col items-center justify-center text-white text-center relative overflow-hidden">
             <div className="relative z-10 space-y-6">
                <div className="w-20 h-20 bg-orange-500/20 border-2 border-orange-500 rounded-2xl flex items-center justify-center mx-auto mb-4">
                   <span className="text-4xl text-orange-500">🛡️</span>
                </div>
                <h3 className="text-2xl font-black">البوابة الإدارية</h3>
                <p className="text-white/60 font-medium">لوحة التحكم للمدير والمشرفين لمتابعة النظام</p>
                <button onClick={onAdminPortal} className="bg-white text-blue-900 px-8 py-3 rounded-xl font-black transition-all hover:bg-orange-500 hover:text-white shadow-lg">
                    دخول المشرفين
                </button>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

