interface AdminLoginProps {
  role: 'admin' | 'manager';
  onLogin: (name: string, pass: string) => void;
  onBack: () => void;
}

const AdminLogin: React.FC<AdminLoginProps> = ({ role, onLogin, onBack }) => {
  const [name, setName] = useState('');
  const [pass, setPass] = useState('');
  const [showPass, setShowPass] = useState(false);

  return (
    <div className="min-h-screen bg-blue-950 flex items-center justify-center p-6 font-sans">
      <div className="bg-white w-full max-w-md rounded-[3rem] shadow-2xl p-10 text-center">
