          <span className="text-4xl">{role === 'manager' ? '⚙️' : '👥'}</span>
        </div>

        <h2 className="text-2xl font-black text-blue-900 mb-2">دخول {role === 'manager' ? 'المدير العام' : 'المشرف'}</h2>
        <p className="text-gray-400 font-bold mb-8">يرجى إدخال بيانات الاعتماد</p>

        <form onSubmit={(e) => { e.preventDefault(); onLogin(name, pass); }} className="space-y-4">
          <input 
            type="text" 
            placeholder="اسم المستخدم (للسجل)" 
            required 
            value={name}
            onChange={e => setName(e.target.value)}
            className="w-full bg-gray-50 p-4 rounded-2xl border-none outline-none focus:ring-2 focus:ring-blue-500 text-center font-bold"
          />
          <div className="relative">
            <input 
              type={showPass ? "text" : "password"} 
              placeholder="كلمة المرور" 
              required 
              value={pass}
              onChange={e => setPass(e.target.value)}
              className="w-full bg-gray-50 p-4 rounded-2xl border-none outline-none focus:ring-2 focus:ring-blue-500 text-center font-bold"
            />
            <button 
              type="button" 
              onClick={() => setShowPass(!showPass)}
              className="absolute left-4 top-1/2 -translate-y-1/2 text-2xl hover:scale-110 transition p-2"
            >
              {showPass ? '🙈' : '👁️'}
            </button>
          </div>
          <button type="submit" className={`w-full py-4 rounded-2xl text-white font-black text-xl shadow-xl transition-all ${role === 'manager' ? 'bg-orange-500 hover:bg-orange-600' : 'bg-blue-900 hover:bg-blue-800'}`}>
            دخول النظام
          </button>
        </form>

        <button onClick={onBack} className="mt-6 text-gray-400 font-bold text-sm hover:text-blue-900 transition">تغيير نوع الصلاحية</button>
      </div>
    </div>
  );
};

export default AdminLogin;

