          <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-100 animate-fadeIn">
             <div className="p-6 border-b border-slate-50 flex justify-between items-center bg-slate-50/50">
                <h3 className="font-black text-xl text-slate-800">{activeTab === 'orders' ? 'الطلبات الجارية حالياً' : 'سجل الأرشيف (الطلبات المكتملة)'}</h3>
             </div>
            <div className="overflow-x-auto">
              <table className="w-full text-right">
                <thead className="bg-slate-100/50 border-b border-slate-100">
                  <tr>
                    <th className="p-5 text-sm font-black text-slate-600">العميل</th>
                    <th className="p-5 text-sm font-black text-slate-600">نوع الخدمة</th>
                    <th className="p-5 text-sm font-black text-slate-600">الفني</th>
                    <th className="p-5 text-sm font-black text-slate-600">الحالة</th>
                    <th className="p-5 text-sm font-black text-slate-600">التاريخ</th>
                    {user.role === 'manager' && <th className="p-5 text-sm font-black text-slate-600">إجراءات</th>}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {(activeTab === 'orders' ? currentActiveOrders : completedOrdersLog).map(order => (
                    <tr key={order.id} className="hover:bg-blue-50/30 transition-colors">
                      <td className="p-5">
                        <p className="font-bold text-slate-800">{order.customerName}</p>
                        <p className="text-xs text-slate-400">{order.customerPhone}</p>
                      </td>
                      <td className="p-5">
                        <span className="bg-slate-100 text-slate-700 px-3 py-1 rounded-full text-xs font-bold">{order.serviceType}</span>
                      </td>
                      <td className="p-5 text-sm text-slate-600 font-medium">{order.technicianName || <span className="text-slate-300 italic">بانتظار فني...</span>}</td>
                      <td className="p-5 text-sm">
                        <span className={`px-4 py-1.5 rounded-full text-xs font-black uppercase tracking-tighter ${
                          order.status === 'pending' ? 'bg-amber-100 text-amber-700' :
                          order.status === 'assigned' ? 'bg-blue-100 text-blue-700' :
                          order.status === 'completed' ? 'bg-emerald-100 text-emerald-700' :
                          'bg-red-100 text-red-700'
                        }`}>
                          {order.status === 'pending' ? 'انتظار' : order.status === 'assigned' ? 'جاري' : order.status === 'completed' ? 'مكتمل' : 'فشل'}
                        </span>
                      </td>
                      <td className="p-5 text-xs text-slate-400 font-bold">{new Date(order.createdAt).toLocaleString('ar-EG')}</td>
                      {user.role === 'manager' && (
                        <td className="p-5">
                           <button 
                            onClick={(e) => { e.preventDefault(); e.stopPropagation(); deleteOrder(order.id); }}
                            className="bg-red-50 text-red-600 px-4 py-2 rounded-xl font-black text-xs hover:bg-red-600 hover:text-white transition-all shadow-sm flex items-center gap-1"
                           >
                            <span>🗑️</span> حذف
                           </button>
                        </td>
                      )}
                    </tr>
                  ))}
                </tbody>
              </table>
              {(activeTab === 'orders' ? currentActiveOrders : completedOrdersLog).length === 0 && (
                <div className="p-20 text-center text-slate-300 font-bold flex flex-col items-center gap-4">
                   <span className="text-4xl">📭</span>
                   لا توجد بيانات حالياً
                </div>
              )}
            </div>
          </div>
        )}

        {activeTab === 'users' && (
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 animate-fadeIn">
            {users.map(u => (
              <div key={u.id} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm hover:shadow-md transition-shadow flex justify-between items-center group">
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <p className="font-black text-slate-800">{u.name}</p>
                    <span className={`text-[10px] font-black px-2 py-0.5 rounded uppercase ${
                      u.role === 'customer' ? 'bg-blue-50 text-blue-600' : 
                      u.role === 'technician' ? 'bg-emerald-50 text-emerald-600' : 
                      'bg-purple-50 text-purple-600'
                    }`}>{u.role}</span>
                  </div>
                  <p className="text-sm text-slate-500 font-bold">{u.phone}</p>
                  {u.specialty && <p className="text-xs text-slate-400 mt-1 font-medium">تخصص: <span className="text-emerald-600">{u.specialty}</span></p>}
                </div>
                {user.role === 'manager' && u.id !== user.id && u.phone !== 'ADMIN_SESSION' && (
                  <button 
                    onClick={(e) => { e.preventDefault(); deleteUser(u.id); }} 
                    className="w-12 h-12 flex items-center justify-center rounded-2xl bg-red-50 text-red-600 opacity-0 group-hover:opacity-100 transition-all hover:bg-red-600 hover:text-white shadow-sm"
                    title="حذف نهائي"
                  >
                    <span className="text-xl">🗑️</span>
                  </button>
                )}
              </div>
            ))}
          </div>
        )}

        {activeTab === 'settings' && (
          <div className="max-w-xl animate-fadeIn">
            <div className="bg-white p-8 rounded-3xl border border-slate-100 shadow-xl">
              <h3 className="text-xl font-black text-slate-800 mb-6">تأمين الحساب</h3>
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-bold text-slate-700 mb-2">كلمة المرور الجديدة</label>
                  <input 
                    type="password" 
                    value={newPassword} 
                    onChange={e => setNewPassword(e.target.value)}
                    className="w-full p-4 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 outline-none transition-all text-center font-bold" 
                    placeholder="••••••••"
                  />
                </div>
                <button onClick={changeAdminPassword} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black hover:bg-blue-600 transition-colors shadow-lg shadow-blue-500/10">حفظ التغييرات</button>
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

