            <span className="w-4 h-4 bg-red-500 rounded-full animate-pulse shadow-lg shadow-red-500/50"></span>
            طلبات جديدة بانتظارك ({availableOrders.length})
          </h2>
          <div className="space-y-6">
            {availableOrders.length === 0 ? (
              <div className="bg-white p-12 rounded-[2rem] text-center border border-gray-100 text-gray-400 font-bold shadow-sm">
                 <span className="text-4xl block mb-4">☕</span>
