      const orderRef = doc(db, 'orders', failingOrderId);
      await updateDoc(orderRef, { 
        status: 'failed',
        failureReason: failureReason,
        adminResolved: false 
      });
      setFailingOrderId(null);
      setFailureReason('');
      alert('تم تسجيل المشكلة وإبلاغ الإدارة ❌');
