                      <button 
                        onClick={() => setFailingOrderId(order.id)}
                        className="flex-1 bg-gray-100 text-gray-500 font-black py-3 rounded-2xl hover:bg-red-500 hover:text-white transition"
                      >حدثت مشكلة ❌</button>
                    </div>
                  )}

                  {/* Failure Notes Input */}
                  {failingOrderId === order.id && (
                    <div className="mt-4 p-4 bg-gray-50 rounded-2xl border-2 border-red-500 space-y-4 animate-fadeIn">
                       <label className="block text-xs font-black text-red-600">ما الذي حدث؟ (اكتب الملاحظات للمدير)</label>
                       <textarea 
                          value={failureReason}
                          onChange={e => setFailureReason(e.target.value)}
                          className="w-full p-3 rounded-xl border border-gray-200 outline-none focus:ring-2 focus:ring-red-500 font-bold text-sm"
                          placeholder="مثلاً: العميل لم يرد، المشكلة تتطلب قطع غيار غير متوفرة..."
                       />
                       <div className="flex gap-2">
                          <button onClick={handleFail} className="flex-1 bg-red-600 text-white py-2 rounded-xl font-black text-sm shadow-lg shadow-red-600/20">تأكيد الإبلاغ</button>
                          <button onClick={() => setFailingOrderId(null)} className="px-4 bg-gray-200 text-gray-600 py-2 rounded-xl font-black text-sm">إلغاء</button>
                       </div>
                    </div>
                  )}

                  {order.rating && (
                    <div className="mt-4 pt-4 border-t border-gray-50 flex items-center justify-between">
                       <p className="text-xs font-black text-gray-400">تقييم العميل لك:</p>
                       <p className="text-orange-500 font-bold">{'⭐'.repeat(order.rating)}</p>
                    </div>
                  )}
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

