                  <div className="flex items-center gap-2 mb-1">
                    <p className="font-black text-slate-800">{u.name}</p>
                    <span className={`text-[10px] font-black px-2 py-0.5 rounded uppercase ${
                      u.role === 'customer' ? 'bg-blue-50 text-blue-600' : 
                      u.role === 'technician' ? 'bg-emerald-50 text-emerald-600' : 
                      'bg-purple-50 text-purple-600'
                    }`}>{u.role}</span>
                  </div>
                  <p className="text-sm text-slate-500 font-bold">{u.phone}</p>
                  {u.specialty && <p className="text-xs text-slate-400 mt-1 font-medium">تخصص: <span className="text-emerald-600">{u.specialty}</span></p>}
                </div>
                {user.role === 'manager' && u.id !== user.id && u.phone !== 'ADMIN_SESSION' && (
                  <button 
                    onClick={(e) => { e.preventDefault(); deleteUser(u.id); }} 
                    className="w-12 h-12 flex items-center justify-center rounded-2xl bg-red-50 text-red-600 opacity-0 group-hover:opacity-100 transition-all hover:bg-red-600 hover:text-white shadow-sm"
                  >
                    <span className="text-xl">🗑️</span>
                  </button>
                )}
              </div>
            ))}
          </div>
        )}
      </main>
    </div>
  );
};

