import React, { useState, useEffect } from 'react';
import { collection, addDoc, query, where, onSnapshot } from 'firebase/firestore';
import { db } from '../firebase';
import { User, Order } from '../types';

interface CustomerDashboardProps {
  user: User;
  onLogout: () => void;
}

const CustomerDashboard: React.FC<CustomerDashboardProps> = ({ user, onLogout }) => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [serviceType, setServiceType] = useState<string>('');
  const [description, setDescription] = useState('');
  const [detailedLocation, setDetailedLocation] = useState('');
  const [timing, setTiming] = useState('الآن');
  const [hourIndex, setHourIndex] = useState(2); // Default to 'عصراً' (index 2)
  const [isOrdering, setIsOrdering] = useState(false);

  const hourOptions = [
    { label: 'صباحاً', time: '8:00 ص' },
    { label: 'ظهراً', time: '12:00 م' },
    { label: 'عصراً', time: '4:00 م' },
    { label: 'مساءً', time: '8:00 م' },
    { label: 'ليلاً', time: '12:00 ل' }
  ];

  useEffect(() => {
    const q = query(collection(db, 'orders'), where('customerId', '==', user.id));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const ordersData = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));
      setOrders(ordersData.sort((a, b) => b.createdAt - a.createdAt));
    });
    return () => unsubscribe();
  }, [user.id]);

  const handleCreateOrder = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!serviceType) return alert('يرجى اختيار نوع الخدمة أولاً');

    setIsOrdering(true);
    try {
      await addDoc(collection(db, 'orders'), {
        customerId: user.id,
        customerName: user.name,
        customerPhone: user.phone,
        address: user.address || '',
        detailedLocation,
        serviceType,
        description,
        preferredTiming: timing,
        specificTime: `${hourOptions[hourIndex].label} (${hourOptions[hourIndex].time})`,
        status: 'pending',
        createdAt: Date.now()
      });
      alert('تم إرسال طلبك بنجاح! سيقوم أحد الفنيين بالتواصل معك قريباً.');
      // Reset form
      setServiceType('');
      setDescription('');
      setDetailedLocation('');
    } catch (err) {
      alert('فشل إرسال الطلب، حاول مرة أخرى');
    } finally {
      setIsOrdering(false);
    }
  };

  const serviceOptions = ['سباك', 'كهربائي', 'نجار', 'فني أجهزة', 'نقاش', 'فني كاميرات'];
  const timingOptions = [
    { label: 'الآن', icon: '⚡', range: 'فوري' },
    { label: 'خلال ساعة', icon: '🕒', range: '1-2 ساعة' },
    { label: 'اليوم مساءً', icon: '🌙', range: '6م - 9م' },
    { label: 'غداً صباحاً', icon: '☀️', range: '8ص - 11ص' }
  ];

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row font-sans">
      <aside className="w-full md:w-80 bg-white border-l border-gray-100 p-8 shadow-sm">
        <div className="mb-10 text-center">
           <div className="w-20 h-20 bg-blue-100 rounded-3xl flex items-center justify-center mx-auto mb-4 text-3xl">👤</div>
           <h2 className="text-xl font-black text-blue-900">{user.name}</h2>
           <p className="text-gray-400 font-bold text-sm">عميل الأسطى</p>
        </div>

        <div className="space-y-6">
           <h3 className="text-sm font-black text-blue-900/40 uppercase tracking-widest">سجل الطلبات</h3>
           <div className="space-y-4 max-h-[400px] overflow-y-auto pr-2">
              {orders.slice(0, 5).map(o => (
                <div key={o.id} className="flex gap-4 items-start border-r-2 border-orange-500 pr-4 py-2">
                   <div>
                      <p className="text-xs font-black text-blue-900">{o.serviceType}</p>
                      <p className="text-[10px] text-gray-400 font-bold">{new Date(o.createdAt).toLocaleDateString('ar-EG')}</p>
                   </div>
                </div>
              ))}
              {orders.length === 0 && <p className="text-xs text-gray-300 italic">لا توجد طلبات سابقة</p>}
           </div>
        </div>

        <button onClick={onLogout} className="w-full mt-12 bg-red-50 text-red-500 font-black py-4 rounded-2xl hover:bg-red-500 hover:text-white transition-all">تسجيل الخروج</button>
      </aside>

      <main className="flex-1 p-4 md:p-8 overflow-y-auto">
        <div className="max-w-3xl mx-auto">
          <div className="bg-blue-700 text-white p-8 rounded-t-[2.5rem] flex flex-col items-center text-center shadow-lg relative overflow-hidden">
             <div className="absolute top-0 right-0 p-4 opacity-10 text-8xl">📋</div>
             <h1 className="text-3xl font-black mb-2">اطلب فني الآن</h1>
             <p className="text-blue-100 font-bold">أخبرنا بما تحتاجه وسنقوم بالباقي</p>
          </div>

          <form onSubmit={handleCreateOrder} className="bg-white p-8 md:p-12 rounded-b-[2.5rem] shadow-2xl border border-gray-100 space-y-10">
            {/* Step 1: Service Type */}
            <div>
              <div className="flex items-center gap-3 mb-6">
                <span className="w-6 h-6 bg-blue-100 text-blue-700 rounded-full flex items-center justify-center text-xs font-black">1</span>
                <h3 className="font-black text-gray-700">نوع الخدمة</h3>
              </div>
              <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                {serviceOptions.map(opt => (
                  <button
                    key={opt}
                    type="button"
                    onClick={() => setServiceType(opt)}
                    className={`p-4 rounded-2xl font-bold transition-all text-sm border-2 ${
                      serviceType === opt 
                      ? 'bg-blue-50 border-blue-600 text-blue-900 shadow-md' 
                      : 'bg-gray-50 border-transparent text-gray-500 hover:border-blue-200'
                    }`}
                  >
                    {opt}
                  </button>
                ))}
              </div>
            </div>

            {/* Step 2: Problem Details */}
            <div>
              <div className="flex items-center gap-3 mb-6">
                <span className="w-6 h-6 bg-blue-100 text-blue-700 rounded-full flex items-center justify-center text-xs font-black">2</span>
                <h3 className="font-black text-gray-700">تفاصيل المشكلة</h3>
              </div>
              <textarea
                required
                value={description}
                onChange={e => setDescription(e.target.value)}
                placeholder="مثلاً: صنبور المطبخ يسرب ماء، أو عطل في لوحة الكهرباء..."
                className="w-full bg-gray-50 p-6 rounded-3xl border-2 border-transparent focus:border-blue-500 focus:bg-white outline-none font-bold text-gray-700 min-h-[120px] transition-all"
              />
            </div>

            {/* Step 3: Location and Timing */}
            <div>
              <div className="flex items-center gap-3 mb-6">
                <span className="w-6 h-6 bg-blue-100 text-blue-700 rounded-full flex items-center justify-center text-xs font-black">3</span>
                <h3 className="font-black text-gray-700">الموقع والموعد</h3>
              </div>

              <div className="relative mb-8">
                <input 
                  type="text" 
                  required
                  value={detailedLocation}
                  onChange={e => setDetailedLocation(e.target.value)}
                  placeholder="الحي، الشارع، رقم الشقة..." 
                  className="w-full bg-gray-50 p-5 pr-12 rounded-2xl border-2 border-transparent focus:border-blue-500 focus:bg-white outline-none font-bold text-gray-700"
                />
                <span className="absolute right-4 top-1/2 -translate-y-1/2 text-xl opacity-30">📍</span>
              </div>

              <div className="bg-blue-50/50 p-6 rounded-[2rem] border border-blue-100/50">
                <div className="flex items-center justify-between mb-6">
                   <h4 className="text-xs font-black text-orange-600 uppercase">اختيار سريع</h4>
                </div>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-10">
                  {timingOptions.map(opt => (
                    <button
                      key={opt.label}
                      type="button"
                      onClick={() => setTiming(opt.label)}
                      className={`p-4 rounded-2xl flex flex-col items-center gap-1 transition-all ${
                        timing === opt.label 
                        ? 'bg-white shadow-xl scale-105 border-2 border-orange-500' 
                        : 'hover:bg-white/50 border-2 border-transparent'
                      }`}
                    >
                      <span className="text-2xl">{opt.icon}</span>
                      <span className="text-xs font-black text-blue-900">{opt.label}</span>
                      <span className="text-[9px] font-bold text-gray-400">{opt.range}</span>
                    </button>
                  ))}
                </div>

                <div className="relative pt-6 px-4">
                   <div className="flex justify-between mb-2">
                      {hourOptions.map((h, idx) => (
                        <button 
                          key={h.label}
                          type="button"
                          onClick={() => setHourIndex(idx)}
                          className={`text-[10px] font-black transition-all flex flex-col items-center ${hourIndex === idx ? 'text-orange-500 scale-110' : 'text-gray-400 opacity-70'}`}
                        >
                          <span>{h.label}</span>
                        </button>
                      ))}
                   </div>
                   <input 
                      type="range" 
                      min="0" 
                      max="4" 
                      step="1"
                      value={hourIndex}
                      onChange={(e) => setHourIndex(parseInt(e.target.value))}
                      className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-orange-500 mb-2"
                   />
                   <div className="flex justify-between text-[9px] font-black text-gray-400">
                      {hourOptions.map((h, idx) => (
                        <span key={idx} className={hourIndex === idx ? 'text-blue-900' : ''}>{h.time}</span>
                      ))}
                   </div>
                </div>

                <div className="mt-8 bg-blue-900 text-white p-4 rounded-2xl flex items-center justify-between shadow-lg">
                   <div className="flex items-center gap-3">
                      <span className="text-2xl">⏰</span>
                      <div>
                         <p className="text-[10px] opacity-60 font-bold uppercase">الموعد المختار</p>
                         <p className="text-sm font-black">{timing} • {hourOptions[hourIndex].label} ({hourOptions[hourIndex].time})</p>
                      </div>
                   </div>
                </div>
              </div>
            </div>

            <button
              type="submit"
              disabled={isOrdering}
              className="w-full bg-orange-500 hover:bg-orange-600 text-white font-black py-5 rounded-[2rem] shadow-2xl shadow-orange-500/30 transition-all transform hover:scale-[1.02] flex items-center justify-center gap-3 text-xl"
            >
              <span>{isOrdering ? 'جاري الحجز...' : 'تأكيد الطلب 🚀'}</span>
            </button>
          </form>
        </div>
      </main>
    </div>
  );
};

