            {/* Step 3: Location and Timing */}
            <div>
              <div className="flex items-center gap-3 mb-6">
                <span className="w-8 h-8 bg-blue-100 text-blue-700 rounded-full flex items-center justify-center text-sm font-black shadow-sm">3</span>
                <h3 className="font-black text-gray-700 text-lg">الموقع والموعد</h3>
              </div>

              <div className="relative mb-10">
                <input 
                  type="text" 
                  required
                  value={detailedLocation}
                  onChange={e => setDetailedLocation(e.target.value)}
                  placeholder="الحي، الشارع، علامة مميزة..." 
                  className="w-full bg-gray-50 p-6 pr-14 rounded-2xl border-2 border-transparent focus:border-blue-500 focus:bg-white outline-none font-bold text-gray-700 shadow-inner"
                />
                <span className="absolute right-5 top-1/2 -translate-y-1/2 text-2xl opacity-40">📍</span>
              </div>

              <div className="bg-blue-50/50 p-8 rounded-[2.5rem] border border-blue-100/50">
                <div className="flex items-center justify-between mb-8">
                   <h4 className="text-xs font-black text-orange-600 uppercase tracking-tighter">🕒 اختيار سريع للوقت</h4>
                </div>

                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-14">
                  {timingOptions.map(opt => (
                    <button
                      key={opt.label}
                      type="button"
                      onClick={() => setTiming(opt.label)}
                      className={`p-4 rounded-3xl flex flex-col items-center gap-1 transition-all border-2 ${
                        timing === opt.label 
                        ? 'bg-white shadow-2xl scale-110 border-orange-500' 
                        : 'bg-white/40 hover:bg-white border-transparent text-gray-400'
                      }`}
                    >
                      <span className="text-3xl mb-1">{opt.icon}</span>
                      <span className={`text-[11px] font-black ${timing === opt.label ? 'text-blue-900' : 'text-gray-500'}`}>{opt.label}</span>
                      <span className={`text-[9px] font-bold ${timing === opt.label ? 'text-orange-500' : 'text-gray-300'}`}>{opt.timeLabel}</span>
                    </button>
                  ))}
                </div>

                <div className="relative pt-6 px-6">
                   <div className="flex justify-between mb-4">
                      {hourOptions.map((h, idx) => (
                        <button 
                          key={h.label}
                          type="button"
                          onClick={() => setHourIndex(idx)}
                          className={`text-[11px] font-black transition-all flex flex-col items-center gap-1 ${hourIndex === idx ? 'text-orange-600 scale-125' : 'text-gray-400 opacity-60'}`}
                        >
                          <span>{h.label}</span>
                        </button>
                      ))}
                   </div>

                   <div className="relative h-12 flex items-center mb-4">
                      <input 
                        type="range" 
                        min="0" 
                        max="4" 
                        step="1"
                        value={hourIndex}
                        onChange={(e) => setHourIndex(parseInt(e.target.value))}
                        className="w-full h-3 bg-gray-200 rounded-full appearance-none cursor-pointer accent-orange-500 relative z-10"
                      />
                      <div className="absolute inset-x-0 flex justify-between px-1 pointer-events-none">
                        {[0,1,2,3,4].map(i => (
                          <div key={i} className="w-1.5 h-1.5 bg-gray-400 rounded-full"></div>
                        ))}
                      </div>
                   </div>

                   <div className="flex justify-between px-1">
                      {hourOptions.map((h, idx) => (
                        <span key={idx} className={`text-[10px] font-black ${hourIndex === idx ? 'text-blue-900 bg-blue-50 px-2 py-0.5 rounded-full' : 'text-gray-300'}`}>
                          {h.time}
                        </span>
                      ))}
                   </div>
                </div>

                <div className="mt-12 bg-blue-900 text-white p-6 rounded-[2rem] flex items-center justify-between shadow-2xl shadow-blue-900/40 transform hover:scale-[1.01] transition-transform">
                   <div className="flex items-center gap-4">
                      <div className="w-14 h-14 bg-white/10 rounded-2xl flex items-center justify-center text-3xl">🕗</div>
                      <div>
                         <p className="text-[10px] opacity-60 font-black uppercase mb-1 tracking-widest">توقيت وصول الفني</p>
                         <p className="text-lg font-black text-orange-400">
                           {timing} • {hourOptions[hourIndex].label} <span className="text-white/80 text-sm">({hourOptions[hourIndex].time})</span>
                         </p>
                      </div>
                   </div>
                </div>
              </div>
            </div>

            <button
              type="submit"
              disabled={isOrdering}
              className="w-full bg-orange-500 hover:bg-orange-600 text-white font-black py-6 rounded-[2.5rem] shadow-2xl shadow-orange-500/30 transition-all transform hover:scale-[1.02] flex items-center justify-center gap-4 text-2xl active:scale-95"
            >
              <span>{isOrdering ? 'جاري إرسال طلبك...' : 'تأكيد وحجز المهمة 🚀'}</span>
            </button>
          </form>
        </div>
      </main>
    </div>
  );
};

export default CustomerDashboard;

import React, { useState, useEffect, useRef } from 'react';
import { collection, query, onSnapshot, doc, updateDoc, deleteDoc } from 'firebase/firestore';
import { db } from '../firebase';
import { User, Order } from '../types';

const StatCard = ({ title, val, color }: { title: string, val: number, color: string }) => {
  return (
    <div className={`bg-gradient-to-br ${color} text-white p-8 rounded-[2rem] shadow-2xl relative overflow-hidden group hover:scale-[1.02] transition-transform cursor-default`}>
      <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -mr-16 -mt-16 group-hover:scale-150 transition-transform duration-700"></div>
      <p className="text-white/80 text-xs font-black uppercase tracking-widest mb-2 relative z-10">{title}</p>
      <p className="text-5xl font-black relative z-10">{val}</p>
    </div>
  );
};

interface AdminDashboardProps {
  user: User;
  onLogout: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user, onLogout }) => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [activeTab, setActiveTab] = useState<'stats' | 'orders' | 'completed-log' | 'users' | 'settings'>('stats');
  const [newPassword, setNewPassword] = useState('');
  const prevOrdersCount = useRef<number | null>(null);

  useEffect(() => {
    // تحديث لحظي للطلبات مع معالجة الأخطاء
    const unsubOrders = onSnapshot(collection(db, 'orders'), (snap) => {
      const ordersData = snap.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));
      const sorted = ordersData.sort((a, b) => b.createdAt - a.createdAt);

      if (prevOrdersCount.current !== null && sorted.length > prevOrdersCount.current) {
        const audio = new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3');
        audio.play().catch(e => console.log('Audio error handled', e));

        if (Notification.permission === "granted") {
          new Notification("الأسطى: طلب جديد!", { body: `يوجد طلب جديد لخدمة ${sorted[0].serviceType}` });
        }
      }
      prevOrdersCount.current = sorted.length;
      setOrders(sorted);
    }, (err) => console.error("Snapshot Error:", err));

    const unsubUsers = onSnapshot(collection(db, 'users'), (snap) => {
      setUsers(snap.docs.map(doc => ({ id: doc.id, ...doc.data() } as User)));
    }, (err) => console.error("Snapshot Error:", err));

    if (Notification.permission !== "granted") {
      Notification.requestPermission();
    }

    return () => {
      unsubOrders();
      unsubUsers();
    };
  }, []);

  const changeAdminPassword = async () => {
    if (!newPassword) return;
    try {
      const userRef = doc(db, 'users', user.id);
      await updateDoc(userRef, { password: newPassword });
      alert('تم تغيير كلمة المرور بنجاح');
      setNewPassword('');
    } catch (err) {
      alert('خطأ في التحديث، تأكد من الاتصال بقاعدة البيانات');
    }
  };

  const deleteUser = async (userId: string) => {
    if (window.confirm('🚨 تحذير: هل أنت متأكد من حذف هذا المستخدم نهائياً؟ لا يمكن التراجع عن هذا الإجراء.')) {
      try {
        await deleteDoc(doc(db, 'users', userId));
      } catch (err) {
        alert('فشل الحذف، يرجى المحاولة لاحقاً');
      }
    }
  };

  const deleteOrder = async (orderId: string) => {
    if (window.confirm('⚠️ حذف نهائي: هل أنت متأكد من حذف هذا الطلب من السجلات؟ سيتم مسحه من قاعدة البيانات فوراً.')) {
      try {
        await deleteDoc(doc(db, 'orders', orderId));
        alert('✅ تم حذف الطلب نهائياً من قاعدة البيانات');
      } catch (err) {
        console.error("Order Delete Error:", err);
        alert('❌ فشل في حذف الطلب من السيرفر، يرجى التحقق من اتصالك');
      }
    }
  };

  const resolveFailure = async (orderId: string) => {
    try {
      const orderRef = doc(db, 'orders', orderId);
      await updateDoc(orderRef, { adminResolved: true });
      alert('تمت معالجة التنبيه بنجاح');
    } catch (err) {
      alert('فشل في معالجة الطلب');
    }
  };

  const stats = {
    totalOrders: orders.length,
    activeOrders: orders.filter(o => o.status === 'pending' || o.status === 'assigned').length,
    completedOrders: orders.filter(o => o.status === 'completed' || o.status === 'failed').length,
    totalCustomers: users.filter(u => u.role === 'customer').length,
    totalTechnicians: users.filter(u => u.role === 'technician').length,
  };

  const currentActiveOrders = orders.filter(o => o.status === 'pending' || o.status === 'assigned');
  const completedOrdersLog = orders.filter(o => o.status === 'completed' || o.status === 'failed');
  const failedAlerts = orders.filter(o => o.status === 'failed' && o.adminResolved === false);

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row">
      <aside className="w-full md:w-64 bg-slate-900 text-white shadow-2xl">
        <div className="p-8 text-center border-b border-slate-800">
          <h1 className="text-3xl font-black text-blue-400 mb-1">الأسطى</h1>
          <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">إدارة النظام</p>
        </div>
        <nav className="mt-8 px-4 space-y-2">
          {[
            { id: 'stats', label: '📊 الإحصائيات' },
            { id: 'orders', label: '📦 الطلبات الجارية' },
            { id: 'completed-log', label: '📜 سجل الأرشيف' },
            { id: 'users', label: '👥 المستخدمين' },
            { id: 'settings', label: '⚙️ الإعدادات' }
          ].map(item => (
            <button 
              key={item.id}
              onClick={() => setActiveTab(item.id as any)}
              className={`w-full text-right p-4 rounded-xl font-bold transition-all duration-300 flex items-center justify-between ${
                activeTab === item.id ? 'bg-blue-600 text-white shadow-lg translate-x-1' : 'text-slate-400 hover:bg-slate-800 hover:text-white'
              }`}
            >
              <span>{item.label}</span>
              {activeTab === item.id && <div className="w-2 h-2 bg-white rounded-full"></div>}
            </button>
          ))}
          <div className="pt-10 border-t border-slate-800 mt-10">
            <button onClick={onLogout} className="w-full bg-red-500/10 text-red-500 p-4 rounded-xl font-bold hover:bg-red-500 hover:text-white transition-all shadow-sm">خروج آمن</button>
          </div>
        </nav>
      </aside>

      <main className="flex-1 overflow-y-auto p-4 md:p-10">
        <header className="mb-6 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <h2 className="text-3xl font-extrabold text-slate-800">أهلاً بك، {user.name}</h2>
            <p className="text-slate-500 font-medium">مستوى الصلاحية: <span className="text-blue-600 font-black uppercase">{user.role}</span> 🟢 متصل بالبيانات</p>
          </div>
          <div className="flex items-center gap-3 bg-white p-3 rounded-2xl shadow-sm border border-slate-100">
             <div className="w-3 h-3 bg-green-500 rounded-full animate-pulse"></div>
             <span className="text-sm font-bold text-slate-600">Database Active</span>
          </div>
        </header>

        {failedAlerts.length > 0 && (
          <div className="mb-8 p-6 bg-red-50 border-2 border-red-200 rounded-[2rem] shadow-xl">
             <div className="flex items-center gap-4 mb-4">
                <span className="text-3xl animate-bounce">⚠️</span>
                <div>
                   <h3 className="text-xl font-black text-red-900">تنبيهات الفشل (تحتاج مراجعة)</h3>
                   <p className="text-sm font-bold text-red-600">هناك {failedAlerts.length} طلبات سجلت كمشكلة من قبل الفنيين</p>
                </div>
             </div>
             <div className="space-y-3">
                {failedAlerts.map(alert => (
                  <div key={alert.id} className="bg-white p-5 rounded-2xl border border-red-100 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                     <div>
                        <p className="text-sm font-black text-blue-900">{alert.customerName} - {alert.serviceType}</p>
                        <p className="text-xs text-red-500 font-black italic">السبب: {alert.failureReason}</p>
                        <p className="text-[10px] text-gray-400 mt-1 font-bold">الفني: {alert.technicianName} ({alert.technicianPhone})</p>
                     </div>
                     <button onClick={() => resolveFailure(alert.id)} className="w-full md:w-auto bg-emerald-500 text-white px-8 py-3 rounded-xl font-black text-xs shadow-lg shadow-emerald-500/20 hover:scale-105 transition-transform">تم المراجعة والحل</button>
                  </div>
                ))}
             </div>
          </div>
        )}

        {activeTab === 'stats' && (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 animate-fadeIn">
            <StatCard title="إجمالي الطلبات" val={stats.totalOrders} color="from-blue-500 to-blue-700" />
            <StatCard title="طلبات نشطة" val={stats.activeOrders} color="from-orange-500 to-orange-700" />
            <StatCard title="مهام منتهية" val={stats.completedOrders} color="from-emerald-500 to-emerald-700" />
            <StatCard title="الفنيين المتاحين" val={stats.totalTechnicians} color="from-indigo-500 to-indigo-700" />
          </div>
        )}

        {(activeTab === 'orders' || activeTab === 'completed-log') && (
          <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-100 animate-fadeIn">
             <div className="p-6 border-b border-slate-50 flex justify-between items-center bg-slate-50/50">
                <h3 className="font-black text-xl text-slate-800">{activeTab === 'orders' ? 'الطلبات الجارية حالياً' : 'سجل الأرشيف والمكتملة'}</h3>
             </div>
            <div className="overflow-x-auto">
              <table className="w-full text-right">
                <thead className="bg-slate-100/50 border-b border-slate-100">
                  <tr>
                    <th className="p-5 text-sm font-black text-slate-600">العميل / المشكلة</th>
                    <th className="p-5 text-sm font-black text-slate-600">نوع الخدمة</th>
                    <th className="p-5 text-sm font-black text-slate-600">الفني</th>
                    <th className="p-5 text-sm font-black text-slate-600">الحالة</th>
                    <th className="p-5 text-sm font-black text-slate-600">التاريخ</th>
                    {user.role === 'manager' && <th className="p-5 text-sm font-black text-slate-600">إجراءات</th>}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {(activeTab === 'orders' ? currentActiveOrders : completedOrdersLog).map(order => (
                    <tr key={order.id} className="hover:bg-blue-50/30 transition-colors">
                      <td className="p-5 max-w-xs">
                        <p className="font-bold text-slate-800">{order.customerName}</p>
                        <p className="text-[10px] text-orange-600 font-black mb-1">📍 {order.detailedLocation || order.address}</p>
                        <p className="text-xs text-slate-400 line-clamp-2">{order.description}</p>
                      </td>
                      <td className="p-5">
                        <span className="bg-slate-100 text-slate-700 px-3 py-1 rounded-full text-[10px] font-black">{order.serviceType}</span>
                      </td>
                      <td className="p-5">
                         <p className="text-xs font-black text-blue-900">{order.technicianName || <span className="text-gray-300 italic">لم يتم القبول بعد</span>}</p>
                         <p className="text-[10px] text-gray-400 font-bold">{order.technicianPhone}</p>
                      </td>
                      <td className="p-5 text-sm">
                        <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-tighter ${
                          order.status === 'pending' ? 'bg-amber-100 text-amber-700' :
                          order.status === 'assigned' ? 'bg-blue-100 text-blue-700' :
                          order.status === 'completed' ? 'bg-emerald-100 text-emerald-700' :
                          'bg-red-100 text-red-700'
                        }`}>
                          {order.status === 'pending' ? 'بانتظار فني' : order.status === 'assigned' ? 'جاري التنفيذ' : order.status === 'completed' ? 'تم الانتهاء' : 'فشل'}
                        </span>
                        {order.status === 'failed' && (
                          <div className="mt-2 text-[10px] text-red-500 font-bold max-w-[150px] leading-tight italic bg-red-50 p-1 rounded">
                            {order.failureReason}
                          </div>
                        )}
                      </td>
                      <td className="p-5 text-xs text-slate-400 font-bold">{new Date(order.createdAt).toLocaleString('ar-EG')}</td>
                      {user.role === 'manager' && (
                        <td className="p-5">
                           <button 
                            onClick={(e) => { e.preventDefault(); e.stopPropagation(); deleteOrder(order.id); }}
                            className="bg-red-50 text-red-600 px-4 py-2 rounded-xl font-black text-[10px] hover:bg-red-600 hover:text-white transition-all shadow-sm flex items-center gap-1 group"
                           >
                            <span className="group-hover:scale-125 transition-transform">🗑️</span> حذف نهائي
                           </button>
                        </td>
                      )}
                    </tr>
                  ))}
                </tbody>
