import React, { useState, useEffect } from 'react';
import { collection, addDoc, query, where, onSnapshot } from 'firebase/firestore';
import { db } from '../firebase';
import { User, Order } from '../types';

interface CustomerDashboardProps {
  user: User;
  onLogout: () => void;
}

const CustomerDashboard: React.FC<CustomerDashboardProps> = ({ user, onLogout }) => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [serviceType, setServiceType] = useState<string>('');
  const [description, setDescription] = useState('');
  const [detailedLocation, setDetailedLocation] = useState('');
  const [timing, setTiming] = useState('الآن');
  const [hourIndex, setHourIndex] = useState(2); // الافتراضي ظهراً
  const [isOrdering, setIsOrdering] = useState(false);

  const hourOptions = [
    { label: 'صباحاً', range: '8ص - 11ص' },
    { label: 'ظهراً', range: '12ظ - 2م' },
    { label: 'عصراً', range: '3م - 5م' },
    { label: 'مساءً', range: '6م - 9م' },
    { label: 'ليلاً', range: '10م - 12ل' }
  ];

  useEffect(() => {
    const q = query(collection(db, 'orders'), where('customerId', '==', user.id));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const ordersData = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));
      setOrders(ordersData.sort((a, b) => b.createdAt - a.createdAt));
    });
    return () => unsubscribe();
  }, [user.id]);

  const handleCreateOrder = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!serviceType) return alert('يرجى اختيار نوع الخدمة أولاً');

    setIsOrdering(true);
    try {
      await addDoc(collection(db, 'orders'), {
        customerId: user.id,
        customerName: user.name,
        customerPhone: user.phone,
        address: user.address || '',
        detailedLocation,
        serviceType,
        description,
        preferredTiming: timing,
        specificTime: `${hourOptions[hourIndex].label} (${hourOptions[hourIndex].range})`,
        status: 'pending',
        createdAt: Date.now(),
        adminResolved: true // الوضع الطبيعي
      });
      alert('تم إرسال طلبك بنجاح!');
      setServiceType('');
      setDescription('');
    } catch (err) {
      alert('فشل إرسال الطلب');
    } finally {
      setIsOrdering(false);
    }
  };

  const serviceOptions = ['سباك', 'كهربائي', 'نجار', 'فني أجهزة', 'نقاش', 'فني كاميرات'];
  const timingOptions = [
    { label: 'الآن', icon: '⚡', desc: 'فوري' },
    { label: 'خلال ساعة', icon: '🕒', desc: 'مستعجل' },
    { label: 'اليوم مساءً', icon: '🌙', desc: 'بعد 6م' },
    { label: 'غداً صباحاً', icon: '☀️', desc: '9ص - 12ظ' }
  ];

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row font-sans">
      <aside className="w-full md:w-80 bg-white border-l border-gray-100 p-8 shadow-sm">
        <div className="mb-10 text-center">
           <div className="w-20 h-20 bg-blue-100 rounded-3xl flex items-center justify-center mx-auto mb-4 text-3xl">👤</div>
           <h2 className="text-xl font-black text-blue-900">{user.name}</h2>
           <p className="text-gray-400 font-bold text-sm">عميل الأسطى</p>
        </div>
        <div className="space-y-6">
           <h3 className="text-sm font-black text-blue-900/40 uppercase tracking-widest">طلباتي النشطة</h3>
           <div className="space-y-4 max-h-[400px] overflow-y-auto pr-2">
              {orders.filter(o => o.status !== 'completed').map(o => (
                <div key={o.id} className="flex gap-4 items-start border-r-4 border-orange-500 pr-4 py-2 bg-gray-50 rounded-xl">
                   <div>
                      <p className="text-xs font-black text-blue-900">{o.serviceType}</p>
                      <p className="text-[10px] text-gray-400 font-bold">{o.status === 'pending' ? 'بانتظار فني' : 'جاري التنفيذ'}</p>
                   </div>
                </div>
              ))}
           </div>
        </div>
        <button onClick={onLogout} className="w-full mt-12 bg-red-50 text-red-500 font-black py-4 rounded-2xl hover:bg-red-500 hover:text-white transition-all">خروج</button>
      </aside>

      <main className="flex-1 p-4 md:p-8 overflow-y-auto">
        <div className="max-w-3xl mx-auto">
          <div className="bg-blue-600 text-white p-8 rounded-t-[2.5rem] flex flex-col items-center text-center shadow-lg relative overflow-hidden">
             <div className="absolute top-0 right-0 p-4 opacity-10 text-8xl">📋</div>
             <h1 className="text-3xl font-black mb-2">اطلب فني الآن</h1>
             <p className="text-blue-100 font-bold">أخبرنا بما تحتاجه وسنقوم بالباقي</p>
          </div>

          <form onSubmit={handleCreateOrder} className="bg-white p-8 md:p-12 rounded-b-[2.5rem] shadow-2xl border border-gray-100 space-y-10">
            {/* 1. نوع الخدمة */}
            <div>
              <div className="flex items-center gap-3 mb-6">
                <span className="w-6 h-6 bg-blue-100 text-blue-700 rounded-full flex items-center justify-center text-xs font-black">1</span>
                <h3 className="font-black text-gray-700">نوع الخدمة</h3>
              </div>
              <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                {serviceOptions.map(opt => (
                  <button key={opt} type="button" onClick={() => setServiceType(opt)} className={`p-4 rounded-2xl font-bold transition-all text-sm border-2 ${serviceType === opt ? 'bg-blue-50 border-blue-600 text-blue-900 shadow-md' : 'bg-gray-50 border-transparent text-gray-500 hover:border-blue-200'}`}>{opt}</button>
                ))}
              </div>
            </div>

            {/* 2. تفاصيل المشكلة */}
            <div>
              <div className="flex items-center gap-3 mb-6">
                <span className="w-6 h-6 bg-blue-100 text-blue-700 rounded-full flex items-center justify-center text-xs font-black">2</span>
                <h3 className="font-black text-gray-700">تفاصيل المشكلة</h3>
              </div>
              <textarea required value={description} onChange={e => setDescription(e.target.value)} placeholder="مثلاً: صنبور المطبخ يسرب ماء، أو عطل في لوحة الكهرباء..." className="w-full bg-gray-50 p-6 rounded-3xl border-2 border-transparent focus:border-blue-500 focus:bg-white outline-none font-bold text-gray-700 min-h-[120px] transition-all shadow-inner" />
