                <span className="absolute right-4 top-1/2 -translate-y-1/2 text-xl opacity-30">📍</span>
              </div>

              <div className="bg-blue-50/50 p-6 rounded-[2rem] border border-blue-100/50">
                <div className="flex items-center justify-between mb-6">
                   <h4 className="text-xs font-black text-orange-600 uppercase">اختيار سريع</h4>
                </div>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-10">
                  {timingOptions.map(opt => (
                    <button key={opt.label} type="button" onClick={() => setTiming(opt.label)} className={`p-4 rounded-2xl flex flex-col items-center gap-2 transition-all ${timing === opt.label ? 'bg-white shadow-xl scale-105 border-2 border-orange-500' : 'hover:bg-white/50 border-2 border-transparent'}`}>
