    if (window.confirm('🚨 حذف نهائي: هل أنت متأكد من مسح هذا العنصر من قاعدة البيانات؟ لا يمكن التراجع!')) {
      try { 
        await deleteDoc(doc(db, type, id));
        alert('✅ تم المسح بنجاح من الـ Database');
      } catch (err) { 
        console.error("Delete error:", err);
        alert('❌ فشل الحذف، تأكد من صلاحياتك واتصالك بالإنترنت'); 
      }
    }
  };

  const stats = {
    active: orders.filter(o => o.status === 'pending' || o.status === 'assigned').length,
    failed: orders.filter(o => o.status === 'failed' && o.adminResolved === false).length,
    completed: orders.filter(o => o.status === 'completed').length,
    techs: users.filter(u => u.role === 'technician').length,
  };

  const currentFailedOrders = orders.filter(o => o.status === 'failed' && o.adminResolved === false);

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row font-sans">
      <aside className="w-full md:w-64 bg-slate-900 text-white shadow-2xl">
        <div className="p-8 text-center border-b border-slate-800">
          <h1 className="text-3xl font-black text-blue-400 mb-1 tracking-tighter italic">الأسطى</h1>
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">الإدارة والرقابة</p>
        </div>
        <nav className="mt-8 px-4 space-y-2">
          {[{id:'stats',l:'📊 الإحصائيات'},{id:'orders',l:'📦 الطلبات النشطة'},{id:'completed-log',l:'📜 سجل العمليات'},{id:'users',l:'👥 قاعدة المستخدمين'}].map(item => (
            <button key={item.id} onClick={() => setActiveTab(item.id as any)} className={`w-full text-right p-4 rounded-xl font-bold transition-all ${activeTab === item.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}>{item.l}</button>
          ))}
          <button onClick={onLogout} className="w-full mt-10 bg-red-500/10 text-red-500 p-4 rounded-xl font-bold hover:bg-red-500 hover:text-white transition-all shadow-sm">خروج آمن</button>
        </nav>
      </aside>

      <main className="flex-1 overflow-y-auto p-4 md:p-10">
