import React, { useState, useEffect } from 'react';
import { collection, query, where, onSnapshot, updateDoc, doc } from 'firebase/firestore';
import { db } from '../firebase';
import { User, Order } from '../types';

interface TechnicianDashboardProps {
  user: User;
  onLogout: () => void;
}

const TechnicianDashboard: React.FC<TechnicianDashboardProps> = ({ user, onLogout }) => {
  const [availableOrders, setAvailableOrders] = useState<Order[]>([]);
  const [myOrders, setMyOrders] = useState<Order[]>([]);
  const [errorOrderId, setErrorOrderId] = useState<string | null>(null);
  const [errorNotes, setErrorNotes] = useState('');

  useEffect(() => {
    const qAvailable = query(collection(db, 'orders'), where('serviceType', '==', user.specialty), where('status', '==', 'pending'));
    const qMy = query(collection(db, 'orders'), where('technicianId', '==', user.id));

    const unsubAvailable = onSnapshot(qAvailable, (snapshot) => {
      const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));
      setAvailableOrders(data.sort((a, b) => b.createdAt - a.createdAt));
    });

    const unsubMy = onSnapshot(qMy, (snapshot) => {
      const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));
      setMyOrders(data.sort((a, b) => b.createdAt - a.createdAt));
    });

    return () => { unsubAvailable(); unsubMy(); };
  }, [user.id, user.specialty]);

  const acceptOrder = async (orderId: string) => {
    try {
      await updateDoc(doc(db, 'orders', orderId), {
        status: 'assigned',
        technicianId: user.id,
        technicianName: user.name,
        technicianSpecialty: user.specialty,
        technicianPhone: user.phone
      });
      alert('تم قبول المهمة!');
    } catch (err) { alert('خطأ في القبول'); }
  };

  const handleFinish = async (orderId: string, status: 'completed' | 'failed') => {
    if (status === 'failed') {
      setErrorOrderId(orderId);
      return;
    }
    try {
      await updateDoc(doc(db, 'orders', orderId), { status });
      alert('تم التحديث بنجاح');
    } catch (err) { alert('خطأ في التحديث'); }
  };

  const submitError = async () => {
    if (!errorNotes.trim()) return alert('يرجى كتابة الملاحظات لتوضيح المشكلة للمدير');
    try {
      await updateDoc(doc(db, 'orders', errorOrderId!), { 
        status: 'failed', 
        failureReason: errorNotes, 
        adminResolved: false 
      });
      setErrorOrderId(null);
      setErrorNotes('');
      alert('تم إبلاغ الإدارة');
    } catch (err) { alert('خطأ في الإرسال'); }
  };

  return (
    <div className="min-h-screen bg-gray-50 pb-12 font-sans">
      <nav className="bg-blue-900 text-white p-6 shadow-xl sticky top-0 z-50">
        <div className="container mx-auto flex justify-between items-center">
          <div><h1 className="text-2xl font-black">الأسطى • {user.name}</h1><p className="text-xs font-bold text-orange-400">{user.specialty}</p></div>
          <button onClick={onLogout} className="bg-white/10 hover:bg-white/20 px-6 py-2 rounded-xl font-bold transition">خروج</button>
        </div>
      </nav>

      <div className="container mx-auto px-4 mt-8 grid grid-cols-1 lg:grid-cols-2 gap-10">
        <div className="space-y-6">
          <h2 className="text-2xl font-black text-gray-800 mb-6 flex items-center gap-3">
            <span className="w-4 h-4 bg-red-500 rounded-full animate-pulse"></span> طلبات جديدة
          </h2>
          {availableOrders.map(order => (
            <div key={order.id} className="bg-white p-8 rounded-[2rem] shadow-xl border border-gray-100 transition-all hover:scale-[1.01]">
              <div className="flex justify-between items-start mb-4">
                <h3 className="font-black text-xl text-blue-900">{order.customerName}</h3>
                <div className="bg-orange-50 text-orange-600 px-4 py-1 rounded-full text-xs font-black">{order.specificTime}</div>
              </div>
              <div className="bg-gray-50 p-5 rounded-2xl border-r-4 border-blue-500 mb-6">
                <p className="text-xs text-blue-900 font-black mb-1">وصف العطل:</p>
                <p className="text-sm font-bold text-gray-600">{order.description}</p>
                <p className="text-[10px] text-gray-400 mt-2 font-black italic">📍 {order.detailedLocation}</p>
              </div>
              <button onClick={() => acceptOrder(order.id)} className="w-full bg-blue-900 hover:bg-blue-800 text-white font-black py-4 rounded-2xl transition-all">قبول المهمة</button>
            </div>
          ))}
        </div>

        <div className="space-y-6">
          <h2 className="text-2xl font-black text-gray-800 mb-6">مهامي الحالية</h2>
          {myOrders.filter(o => o.status === 'assigned').map(order => (
            <div key={order.id} className="bg-white p-8 rounded-[2rem] shadow-xl border-2 border-blue-100">
              <h3 className="font-black text-blue-900 mb-2">{order.customerName} - {order.customerPhone}</h3>
              <p className="text-sm font-bold text-gray-400 mb-6">{order.detailedLocation}</p>
              <div className="flex gap-4">
                <button onClick={() => handleFinish(order.id, 'completed')} className="flex-1 bg-green-500 text-white py-3 rounded-2xl font-black">تم ✅</button>
                <button onClick={() => handleFinish(order.id, 'failed')} className="flex-1 bg-red-100 text-red-600 py-3 rounded-2xl font-black">فشل ❌</button>
              </div>
              {errorOrderId === order.id && (
                <div className="mt-6 p-4 bg-red-50 rounded-2xl border-2 border-red-500">
                   <p className="text-xs font-black text-red-600 mb-2">ما الذي حدث؟ (اكتب ملاحظاتك للمدير)</p>
                   <textarea value={errorNotes} onChange={e => setErrorNotes(e.target.value)} className="w-full p-3 rounded-xl border-none outline-none font-bold text-sm mb-4" placeholder="مثلاً: العميل لم يرد، المشكلة تتطلب قطع غيار غير متوفرة..." />
                   <button onClick={submitError} className="w-full bg-red-600 text-white py-2 rounded-xl font-black text-sm">إرسال البلاغ</button>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default TechnicianDashboard;

import React, { useState, useEffect, useRef } from 'react';
import { collection, query, onSnapshot, doc, updateDoc, deleteDoc } from 'firebase/firestore';
import { db } from '../firebase';
import { User, Order } from '../types';

const StatCard = ({ title, val, color }: { title: string, val: number, color: string }) => {
  return (
    <div className={`bg-gradient-to-br ${color} text-white p-8 rounded-[2rem] shadow-2xl relative overflow-hidden group hover:scale-[1.02] transition-transform cursor-default`}>
      <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -mr-16 -mt-16"></div>
      <p className="text-white/80 text-xs font-black uppercase tracking-widest mb-2 relative z-10">{title}</p>
      <p className="text-5xl font-black relative z-10">{val}</p>
    </div>
  );
};

interface AdminDashboardProps {
  user: User;
  onLogout: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user, onLogout }) => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [activeTab, setActiveTab] = useState<'stats' | 'orders' | 'completed-log' | 'users'>('stats');
  const prevOrdersCount = useRef<number | null>(null);

  useEffect(() => {
    const unsubOrders = onSnapshot(collection(db, 'orders'), (snap) => {
      const ordersData = snap.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));
      const sorted = ordersData.sort((a, b) => b.createdAt - a.createdAt);

      if (prevOrdersCount.current !== null && sorted.length > prevOrdersCount.current) {
        new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3').play().catch(() => {});
      }
      prevOrdersCount.current = sorted.length;
      setOrders(sorted);
    });

    const unsubUsers = onSnapshot(collection(db, 'users'), (snap) => {
      setUsers(snap.docs.map(doc => ({ id: doc.id, ...doc.data() } as User)));
    });

    return () => { unsubOrders(); unsubUsers(); };
  }, []);

  const deleteItem = async (e: React.MouseEvent, type: 'orders' | 'users', id: string) => {
    e.preventDefault();
    e.stopPropagation();
    if (window.confirm('🚨 هل أنت متأكد من الحذف النهائي؟ سيتم المسح من قاعدة البيانات فوراً.')) {
      try { 
        await deleteDoc(doc(db, type, id));
        alert('تم المسح بنجاح ✅');
      } catch (err) { alert('فشل الحذف'); }
    }
  };

  const resolveError = async (orderId: string) => {
    try {
      await updateDoc(doc(db, 'orders', orderId), { adminResolved: true });
      alert('تمت أرشفة المشكلة');
    } catch (err) { alert('فشل المعالجة'); }
  };

  const stats = {
    active: orders.filter(o => o.status === 'pending' || o.status === 'assigned').length,
    failed: orders.filter(o => o.status === 'failed' && !o.adminResolved).length,
    completed: orders.filter(o => o.status === 'completed').length,
    techs: users.filter(u => u.role === 'technician').length,
  };

  const currentFailedOrders = orders.filter(o => o.status === 'failed' && !o.adminResolved);

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row font-sans">
      <aside className="w-full md:w-64 bg-slate-900 text-white shadow-2xl">
        <div className="p-8 text-center border-b border-slate-800">
          <h1 className="text-3xl font-black text-blue-400 italic">الأسطى</h1>
          <p className="text-slate-400 text-[10px] font-black uppercase">لوحة التحكم المركزية</p>
        </div>
        <nav className="mt-8 px-4 space-y-2">
          {[{id:'stats',l:'📊 الإحصائيات'},{id:'orders',l:'📦 الطلبات النشطة'},{id:'completed-log',l:'📜 سجل العمليات'},{id:'users',l:'👥 المستخدمين'}].map(item => (
            <button key={item.id} onClick={() => setActiveTab(item.id as any)} className={`w-full text-right p-4 rounded-xl font-bold transition-all ${activeTab === item.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}>{item.l}</button>
          ))}
          <button onClick={onLogout} className="w-full mt-10 bg-red-500/10 text-red-500 p-4 rounded-xl font-bold hover:bg-red-500 hover:text-white transition-all">خروج</button>
        </nav>
      </aside>

      <main className="flex-1 overflow-y-auto p-4 md:p-10">
        <header className="mb-10 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div><h2 className="text-3xl font-extrabold text-slate-800">أهلاً بك، {user.name}</h2><p className="text-slate-500 font-medium">نظام المراقبة يعمل بصورة لحظية 🟢</p></div>
        </header>

        {currentFailedOrders.length > 0 && (
          <div className="mb-10 p-8 bg-red-50 border-r-8 border-red-600 rounded-3xl shadow-xl animate-fadeIn">
             <h3 className="text-2xl font-black text-red-900 mb-4 flex items-center gap-3">🚨 بلاغات توقف مهام!</h3>
             <div className="grid grid-cols-1 gap-4">
                {currentFailedOrders.map(o => (
                  <div key={o.id} className="bg-white p-6 rounded-2xl border border-red-100 flex flex-col md:flex-row justify-between items-center gap-4">
                     <div>
                        <p className="font-black text-blue-900">{o.customerName} | <span className="text-orange-600">{o.serviceType}</span></p>
                        <p className="text-sm text-red-500 font-bold italic bg-red-50 p-2 rounded mt-2">سبب التوقف: {o.failureReason}</p>
                        <p className="text-[10px] text-gray-400 mt-2 font-black">الفني: {o.technicianName} ({o.technicianPhone})</p>
                     </div>
                     <button onClick={() => resolveError(o.id)} className="bg-emerald-500 hover:bg-emerald-600 text-white px-8 py-3 rounded-xl font-black text-xs shadow-lg transition-all">تم الحل والتحقق</button>
                  </div>
                ))}
             </div>
          </div>
        )}

        {activeTab === 'stats' && (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 animate-fadeIn">
            <StatCard title="نشطة حالياً" val={stats.active} color="from-blue-600 to-blue-800" />
            <StatCard title="أعطال نشطة" val={stats.failed} color="from-red-600 to-red-800" />
            <StatCard title="إجمالي النجاح" val={stats.completed} color="from-emerald-600 to-emerald-800" />
            <StatCard title="فنيين متاحين" val={stats.techs} color="from-slate-700 to-slate-900" />
          </div>
        )}

        {(activeTab === 'orders' || activeTab === 'completed-log') && (
          <div className="bg-white rounded-[2.5rem] shadow-xl overflow-hidden border border-slate-100 animate-fadeIn mt-8">
            <div className="overflow-x-auto">
              <table className="w-full text-right">
                <thead className="bg-slate-50 border-b border-slate-100">
                  <tr>
                    <th className="p-5 text-xs font-black text-slate-600">العميل والموقع</th>
                    <th className="p-5 text-xs font-black text-slate-600">الفني والوظيفة</th>
                    <th className="p-5 text-xs font-black text-slate-600 text-center">الحالة</th>
                    <th className="p-5 text-xs font-black text-slate-600 text-center">حذف</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {(activeTab === 'orders' ? orders.filter(o => o.status !== 'completed' && o.status !== 'failed') : orders.filter(o => o.status === 'completed' || (o.status === 'failed' && o.adminResolved))).map(o => (
                    <tr key={o.id} className="hover:bg-blue-50/30 transition-colors group">
                      <td className="p-5 max-w-xs">
                        <p className="font-black text-slate-800">{o.customerName}</p>
                        <p className="text-[10px] text-orange-600 font-black tracking-tight">📍 {o.detailedLocation || o.address}</p>
                      </td>
                      <td className="p-5">
                        <p className="text-xs font-black text-blue-900">{o.technicianName || 'بانتظار فني'}</p>
                        {o.technicianSpecialty && <p className="text-[10px] text-orange-500 font-black">الوظيفة: {o.technicianSpecialty}</p>}
                      </td>
                      <td className="p-5 text-center">
                        <span className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase ${
                          o.status === 'pending' ? 'bg-amber-100 text-amber-700' : 
                          o.status === 'assigned' ? 'bg-blue-100 text-blue-700' : 
                          o.status === 'completed' ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-700'
                        }`}>{o.status}</span>
                      </td>
                      <td className="p-5 text-center">
                        <button onClick={(e) => deleteItem(e, 'orders', o.id)} className="w-10 h-10 rounded-xl bg-red-50 text-red-500 flex items-center justify-center mx-auto hover:bg-red-600 hover:text-white transition-all shadow-sm">🗑️</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activeTab === 'users' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-fadeIn mt-8">
            {users.map(u => (
              <div key={u.id} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex justify-between items-center group hover:shadow-lg transition-shadow">
                <div>
                  <p className="font-black text-slate-800 text-lg">{u.name}</p>
                  <p className="text-sm text-slate-400 font-bold">{u.phone}</p>
                  <div className="flex items-center gap-2 mt-3">
                    <span className={`text-[9px] font-black px-3 py-1 rounded-full uppercase ${u.role === 'customer' ? 'bg-blue-50 text-blue-600' : 'bg-emerald-50 text-emerald-600'}`}>{u.role}</span>
                    {u.specialty && <span className="text-[9px] font-black bg-orange-50 text-orange-600 px-3 py-1 rounded-full">{u.specialty}</span>}
                  </div>
                </div>
                {u.phone !== 'ADMIN_SESSION' && (
                  <button onClick={(e) => deleteItem(e, 'users', u.id)} className="w-10 h-10 rounded-xl bg-red-50 text-red-500 opacity-0 group-hover:opacity-100 transition-all hover:bg-red-500 hover:text-white flex items-center justify-center">🗑️</button>
                )}
              </div>
            ))}
          </div>
        )}
      </main>
    </div>
  );
};

export default AdminDashboard;

