import React, { useState, useEffect, useRef } from 'react';
import { collection, query, onSnapshot, doc, updateDoc } from 'firebase/firestore';
import { db } from '../firebase';
import { User, Order } from '../types';

const StatCard = ({ title, val, color }: { title: string, val: number, color: string }) => {
  return (
    <div className={`bg-gradient-to-br ${color} text-white p-8 rounded-[2rem] shadow-2xl relative overflow-hidden group hover:scale-[1.02] transition-transform cursor-default`}>
      <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -mr-16 -mt-16 group-hover:scale-150 transition-transform duration-700"></div>
      <p className="text-white/80 text-xs font-black uppercase tracking-widest mb-2 relative z-10">{title}</p>
      <p className="text-5xl font-black relative z-10">{val}</p>
    </div>
  );
};

interface AdminDashboardProps {
  user: User;
  onLogout: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user, onLogout }) => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [activeTab, setActiveTab] = useState<'stats' | 'orders' | 'completed-log' | 'users'>('stats');
  const prevOrdersCount = useRef<number | null>(null);

  useEffect(() => {
    const unsubOrders = onSnapshot(collection(db, 'orders'), (snap) => {
      const ordersData = snap.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));
      const sorted = ordersData.sort((a, b) => b.createdAt - a.createdAt);

      if (prevOrdersCount.current !== null && sorted.length > prevOrdersCount.current) {
        new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3').play().catch(() => {});
      }
      prevOrdersCount.current = sorted.length;
      setOrders(sorted);
    });

    const unsubUsers = onSnapshot(collection(db, 'users'), (snap) => {
      setUsers(snap.docs.map(doc => ({ id: doc.id, ...doc.data() } as User)));
    });

    return () => { unsubOrders(); unsubUsers(); };
  }, []);

  const resolveError = async (orderId: string) => {
    try {
      await updateDoc(doc(db, 'orders', orderId), { adminResolved: true });
      alert('تمت مراجعة الطلب بنجاح');
    } catch (err) { alert('فشل تحديث الحالة'); }
  };

  const stats = {
    active: orders.filter(o => o.status === 'pending' || o.status === 'assigned').length,
    failed: orders.filter(o => o.status === 'failed' && !o.adminResolved).length,
    completed: orders.filter(o => o.status === 'completed').length,
    techs: users.filter(u => u.role === 'technician').length,
  };

  const currentFailedOrders = orders.filter(o => o.status === 'failed' && !o.adminResolved);

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row font-sans">
      <aside className="w-full md:w-64 bg-slate-900 text-white shadow-2xl z-20">
        <div className="p-8 text-center border-b border-slate-800">
          <h1 className="text-3xl font-black text-blue-400 italic tracking-tighter">الأسطى</h1>
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mt-1">نظام الإدارة المركزي</p>
        </div>
        <nav className="mt-8 px-4 space-y-2">
          {[{id:'stats',l:'📊 الإحصائيات'},{id:'orders',l:'📦 الطلبات النشطة'},{id:'completed-log',l:'📜 سجل العمليات'},{id:'users',l:'👥 المستخدمين'}].map(item => (
            <button 
              key={item.id} 
              onClick={() => setActiveTab(item.id as any)} 
              className={`w-full text-right p-4 rounded-xl font-bold transition-all duration-300 ${activeTab === item.id ? 'bg-blue-600 text-white shadow-lg translate-x-1' : 'text-slate-400 hover:bg-slate-800'}`}
            >
              {item.l}
            </button>
          ))}
          <button onClick={onLogout} className="w-full mt-10 bg-red-500/10 text-red-500 p-4 rounded-xl font-bold hover:bg-red-500 hover:text-white transition-all shadow-sm">خروج آمن</button>
        </nav>
      </aside>

      <main className="flex-1 overflow-y-auto p-4 md:p-10">
        <header className="mb-10 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <h2 className="text-3xl font-extrabold text-slate-800">مرحباً، {user.name}</h2>
            <p className="text-slate-500 font-medium">مراقبة حية لكافة الأنشطة 🟢</p>
          </div>
          <div className="bg-white p-3 rounded-2xl shadow-sm border border-slate-100 flex items-center gap-3">
             <div className="w-3 h-3 bg-green-500 rounded-full animate-pulse"></div>
             <span className="text-xs font-bold text-slate-600 uppercase tracking-widest">Firestore Live</span>
          </div>
        </header>

        {currentFailedOrders.length > 0 && (
          <div className="mb-10 p-8 bg-red-50 border-r-8 border-red-600 rounded-3xl shadow-xl animate-fadeIn">
             <div className="flex items-center gap-5 mb-6">
                <div className="w-14 h-14 bg-red-600 text-white rounded-2xl flex items-center justify-center text-3xl animate-bounce shadow-lg">⚠️</div>
                <div>
                   <h3 className="text-2xl font-black text-red-900">تنبيه: مهام فاشلة / معطلة</h3>
                   <p className="text-sm font-bold text-red-600">هناك {currentFailedOrders.length} طلبات أبلغ الفنيون عن تعثرها</p>
                </div>
             </div>
             <div className="grid grid-cols-1 gap-4">
                {currentFailedOrders.map(o => (
                  <div key={o.id} className="bg-white p-6 rounded-2xl border border-red-100 flex flex-col md:flex-row justify-between items-center gap-6 shadow-sm hover:shadow-md transition-shadow">
                     <div className="flex-1">
                        <div className="flex items-center gap-2 mb-1">
                          <p className="font-black text-blue-900 text-lg">{o.customerName}</p>
                          <span className="bg-orange-100 text-orange-600 text-[10px] font-black px-2 py-0.5 rounded uppercase">{o.serviceType}</span>
