            <StatCard title="أعطال نشطة" val={stats.failed} color="from-red-600 to-red-800" />
            <StatCard title="إجمالي النجاح" val={stats.completed} color="from-emerald-600 to-emerald-800" />
            <StatCard title="فنيين معتمدين" val={stats.techs} color="from-slate-700 to-slate-900" />
          </div>
        )}

        {(activeTab === 'orders' || activeTab === 'completed-log') && (
          <div className="bg-white rounded-[2.5rem] shadow-xl overflow-hidden border border-slate-100 animate-fadeIn mt-8">
            <div className="overflow-x-auto">
              <table className="w-full text-right border-collapse">
                <thead className="bg-slate-50 border-b border-slate-100">
