                    <span className="text-[10px] font-black text-orange-600 bg-orange-50 px-3 py-1 rounded-lg">
                      تخصص: {u.specialty}
                    </span>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </main>
    </div>
  );
};

