import React, { useState } from 'react';
import { collection, addDoc, query, where, getDocs } from 'firebase/firestore';
import { db } from '../firebase';
import { UserRole } from '../types';

interface RegisterProps {
  onSwitch: () => void;
}

const Register: React.FC<RegisterProps> = ({ onSwitch }) => {
  const [role, setRole] = useState<UserRole>('customer');
  const [showPassword, setShowPassword] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    password: '',
    address: '',
    securityQuestion: 'ما هو اسم مدرستك الابتدائية؟',
    securityAnswer: '',
    specialty: 'نجار',
    experience: 1,
    area: ''
  });
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const specialties = ['نجار', 'كهربائي', 'سباك', 'فني دش', 'نقاش'];

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setError('');

    try {
      const q = query(collection(db, 'users'), where('phone', '==', formData.phone));
      const snap = await getDocs(q);
      if (!snap.empty) {
        setError('هذا الهاتف مسجل مسبقاً');
        setIsSubmitting(false);
        return;
      }

      await addDoc(collection(db, 'users'), {
        ...formData,
        role,
        isApproved: role === 'customer', // العميل معتمد تلقائياً، الفني يحتاج موافقة
        createdAt: Date.now()
      });
      setSuccess('تم إنشاء الحساب بنجاح! الفنيين يحتاجون لموافقة الإدارة قبل البدء.');
      setTimeout(onSwitch, 2500);
    } catch (err) {
      setError('حدث خطأ أثناء التسجيل');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen py-10 bg-gray-100 flex items-center justify-center px-4">
      <div className="bg-white w-full max-w-2xl p-8 rounded-2xl shadow-xl">
        <h2 className="text-3xl font-extrabold text-blue-900 mb-6 text-center">إنشاء حساب جديد</h2>

        <div className="flex bg-gray-100 p-1 rounded-lg mb-8">
          <button 
            onClick={() => setRole('customer')}
            className={`flex-1 py-2 rounded-md font-bold transition ${role === 'customer' ? 'bg-white shadow-md text-blue-800' : 'text-gray-500'}`}
          >عميل</button>
          <button 
            onClick={() => setRole('technician')}
            className={`flex-1 py-2 rounded-md font-bold transition ${role === 'technician' ? 'bg-white shadow-md text-blue-800' : 'text-gray-500'}`}
          >فني</button>
        </div>

        <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="col-span-1">
            <label className="block text-sm font-bold text-gray-700 mb-1">الاسم بالكامل</label>
            <input name="name" required onChange={handleInputChange} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
          </div>
          <div className="col-span-1">
            <label className="block text-sm font-bold text-gray-700 mb-1">رقم الهاتف</label>
            <input name="phone" required onChange={handleInputChange} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
          </div>
          <div className="col-span-1 relative">
            <label className="block text-sm font-bold text-gray-700 mb-1">كلمة المرور</label>
            <input 
              name="password" 
              type={showPassword ? "text" : "password"} 
              required 
              onChange={handleInputChange} 
              className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
            />
            <button 
              type="button" 
              onClick={() => setShowPassword(!showPassword)}
              className="absolute left-2 bottom-2 text-gray-400"
            >
              {showPassword ? '🙈' : '👁️'}
            </button>
          </div>
          <div className="col-span-1">
            <label className="block text-sm font-bold text-gray-700 mb-1">العنوان</label>
            <input name="address" required onChange={handleInputChange} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
          </div>

          <div className="col-span-2">
            <label className="block text-sm font-bold text-gray-700 mb-1">سؤال الأمان</label>
            <select name="securityQuestion" onChange={handleInputChange} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white">
              <option>ما هو اسم مدرستك الابتدائية؟</option>
              <option>ما هو اسم حيوانك الأليف؟</option>
              <option>ما هي مدينتك المفضلة؟</option>
            </select>
          </div>
          <div className="col-span-2">
            <label className="block text-sm font-bold text-gray-700 mb-1">إجابة سؤال الأمان</label>
            <input name="securityAnswer" required onChange={handleInputChange} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
          </div>

          {role === 'technician' && (
            <>
              <div className="col-span-1">
                <label className="block text-sm font-bold text-gray-700 mb-1">التخصص</label>
                <select name="specialty" onChange={handleInputChange} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white">
                  {specialties.map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>
              <div className="col-span-1">
                <label className="block text-sm font-bold text-gray-700 mb-1">سنوات الخبرة</label>
                <input name="experience" type="number" required onChange={handleInputChange} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
              </div>
              <div className="col-span-2">
                <label className="block text-sm font-bold text-gray-700 mb-1">منطقة العمل</label>
                <input name="area" required onChange={handleInputChange} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
              </div>
            </>
          )}

          {error && <p className="col-span-2 text-red-500 text-sm font-bold text-center">{error}</p>}
          {success && <p className="col-span-2 text-green-500 text-sm font-bold text-center">{success}</p>}

          <div className="col-span-2 pt-4">
            <button
              type="submit"
              disabled={isSubmitting}
              className="w-full bg-blue-700 hover:bg-blue-800 text-white font-bold py-3 rounded-lg shadow transition-all disabled:opacity-50"
            >
              {isSubmitting ? 'جاري التسجيل...' : 'تسجيل الحساب'}
            </button>
            <button onClick={onSwitch} type="button" className="w-full mt-4 text-gray-500 hover:underline">رجوع لتسجيل الدخول</button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default Register;

import React, { useState, useEffect } from 'react';
import { collection, query, where, onSnapshot, updateDoc, doc } from 'firebase/firestore';
import { db } from '../firebase';
import { User, Order } from '../types';

interface TechnicianDashboardProps {
  user: User;
  onLogout: () => void;
}

const TechnicianDashboard: React.FC<TechnicianDashboardProps> = ({ user, onLogout }) => {
  const [availableOrders, setAvailableOrders] = useState<Order[]>([]);
  const [myOrders, setMyOrders] = useState<Order[]>([]);
  const [errorOrderId, setErrorOrderId] = useState<string | null>(null);
  const [errorNotes, setErrorNotes] = useState('');
  const [currentUserData, setCurrentUserData] = useState<User>(user);

  useEffect(() => {
    // مراقبة بيانات الفني نفسه للتأكد من حالة الاعتماد
    const unsubUser = onSnapshot(doc(db, 'users', user.id), (docSnap) => {
      if (docSnap.exists()) {
        setCurrentUserData({ id: docSnap.id, ...docSnap.data() } as User);
      }
    });

    // مراقبة الطلبات (فقط إذا كان معتمداً)
    if (currentUserData.isApproved) {
      const qAvailable = query(collection(db, 'orders'), where('serviceType', '==', user.specialty), where('status', '==', 'pending'));
      const qMy = query(collection(db, 'orders'), where('technicianId', '==', user.id));

      const unsubAvailable = onSnapshot(qAvailable, (snapshot) => {
        const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));
        setAvailableOrders(data.sort((a, b) => b.createdAt - a.createdAt));
      });

      const unsubMy = onSnapshot(qMy, (snapshot) => {
        const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));
        setMyOrders(data.sort((a, b) => b.createdAt - a.createdAt));
      });

      return () => { unsubUser(); unsubAvailable(); unsubMy(); };
    }

    return () => unsubUser();
  }, [user.id, user.specialty, currentUserData.isApproved]);

  const acceptOrder = async (orderId: string) => {
    try {
      await updateDoc(doc(db, 'orders', orderId), {
        status: 'assigned',
        technicianId: user.id,
        technicianName: user.name,
        technicianSpecialty: user.specialty,
        technicianPhone: user.phone
      });
      alert('تم قبول المهمة!');
    } catch (err) { alert('خطأ في القبول'); }
  };

  const handleFinish = async (orderId: string, status: 'completed' | 'failed') => {
    if (status === 'failed') {
      setErrorOrderId(orderId);
      return;
    }
    try {
      await updateDoc(doc(db, 'orders', orderId), { status });
      alert('تم التحديث بنجاح');
    } catch (err) { alert('خطأ في التحديث'); }
  };

  const submitError = async () => {
    if (!errorNotes.trim()) return alert('يرجى كتابة الملاحظات لتوضيح المشكلة للمدير');
    try {
      await updateDoc(doc(db, 'orders', errorOrderId!), { 
        status: 'failed', 
        failureReason: errorNotes, 
        adminResolved: false 
      });
      setErrorOrderId(null);
      setErrorNotes('');
      alert('تم إبلاغ الإدارة');
    } catch (err) { alert('خطأ في الإرسال'); }
  };

  // واجهة "قيد المراجعة" إذا لم يكن معتمداً
  if (!currentUserData.isApproved) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-6 text-center">
        <div className="bg-white max-w-lg w-full p-12 rounded-[3rem] shadow-2xl animate-fadeIn">
          <div className="w-24 h-24 bg-amber-100 text-amber-500 rounded-3xl flex items-center justify-center mx-auto mb-8 animate-pulse">
            <span className="text-5xl">⏳</span>
          </div>
          <h1 className="text-3xl font-black text-slate-800 mb-4">حسابك قيد المراجعة</h1>
          <p className="text-slate-500 font-bold leading-relaxed mb-10">
            أهلاً بك يا أسطى <span className="text-blue-600">{user.name}</span>. 
            يتم الآن مراجعة بياناتك من قبل الإدارة لتفعيل حسابك. ستتمكن من استقبال الطلبات فور اعتمادك.
          </p>
          <div className="space-y-4">
            <div className="flex items-center gap-3 bg-blue-50 p-4 rounded-2xl">
               <span className="text-blue-600">📍</span>
               <p className="text-xs font-black text-blue-900">سيصلك إشعار بالقبول قريباً</p>
            </div>
            <button onClick={onLogout} className="w-full py-4 rounded-2xl bg-red-50 text-red-500 font-black hover:bg-red-500 hover:text-white transition-all">خروج</button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 pb-12 font-sans">
      <nav className="bg-blue-900 text-white p-6 shadow-xl sticky top-0 z-50">
        <div className="container mx-auto flex justify-between items-center">
          <div><h1 className="text-2xl font-black">الأسطى • {user.name}</h1><p className="text-xs font-bold text-orange-400">{user.specialty}</p></div>
          <button onClick={onLogout} className="bg-white/10 hover:bg-white/20 px-6 py-2 rounded-xl font-bold transition">خروج</button>
        </div>
      </nav>

      <div className="container mx-auto px-4 mt-8 grid grid-cols-1 lg:grid-cols-2 gap-10">
        <div className="space-y-6">
          <h2 className="text-2xl font-black text-gray-800 mb-6 flex items-center gap-3">
            <span className="w-4 h-4 bg-red-500 rounded-full animate-pulse"></span> طلبات جديدة
          </h2>
          {availableOrders.map(order => (
            <div key={order.id} className="bg-white p-8 rounded-[2rem] shadow-xl border border-gray-100 transition-all hover:scale-[1.01]">
              <div className="flex justify-between items-start mb-4">
                <h3 className="font-black text-xl text-blue-900">{order.customerName}</h3>
                <div className="bg-orange-50 text-orange-600 px-4 py-1 rounded-full text-xs font-black">{order.specificTime}</div>
              </div>
              <div className="bg-gray-50 p-5 rounded-2xl border-r-4 border-blue-500 mb-6">
                <p className="text-xs text-blue-900 font-black mb-1">وصف العطل:</p>
                <p className="text-sm font-bold text-gray-600">{order.description}</p>
                <p className="text-[10px] text-gray-400 mt-2 font-black italic">📍 {order.detailedLocation}</p>
              </div>
              <button onClick={() => acceptOrder(order.id)} className="w-full bg-blue-900 hover:bg-blue-800 text-white font-black py-4 rounded-2xl transition-all">قبول المهمة</button>
            </div>
          ))}
          {availableOrders.length === 0 && (
            <div className="text-center p-20 opacity-30 italic font-black">لا توجد طلبات متاحة حالياً في تخصصك</div>
          )}
        </div>

        <div className="space-y-6">
          <h2 className="text-2xl font-black text-gray-800 mb-6">مهامي الحالية</h2>
          {myOrders.filter(o => o.status === 'assigned').map(order => (
            <div key={order.id} className="bg-white p-8 rounded-[2rem] shadow-xl border-2 border-blue-100">
              <h3 className="font-black text-blue-900 mb-2">{order.customerName} - {order.customerPhone}</h3>
              <p className="text-sm font-bold text-gray-400 mb-6">{order.detailedLocation}</p>
              <div className="flex gap-4">
                <button onClick={() => handleFinish(order.id, 'completed')} className="flex-1 bg-green-500 text-white py-3 rounded-2xl font-black">تم ✅</button>
                <button onClick={() => handleFinish(order.id, 'failed')} className="flex-1 bg-red-100 text-red-600 py-3 rounded-2xl font-black">فشل ❌</button>
              </div>
              {errorOrderId === order.id && (
                <div className="mt-6 p-4 bg-red-50 rounded-2xl border-2 border-red-500">
                   <p className="text-xs font-black text-red-600 mb-2">ما الذي حدث؟ (اكتب ملاحظاتك للمدير)</p>
                   <textarea value={errorNotes} onChange={e => setErrorNotes(e.target.value)} className="w-full p-3 rounded-xl border-none outline-none font-bold text-sm mb-4" placeholder="مثلاً: العميل لم يرد، المشكلة تتطلب قطع غيار غير متوفرة..." />
                   <button onClick={submitError} className="w-full bg-red-600 text-white py-2 rounded-xl font-black text-sm">إرسال البلاغ</button>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

