          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mt-1">نظام الإدارة المركزي</p>
        </div>
        <nav className="mt-8 px-4 space-y-2">
          {[{id:'stats',l:'📊 الإحصائيات'},{id:'orders',l:'📦 الطلبات النشطة'},{id:'completed-log',l:'📜 سجل العمليات'},{id:'users',l:'👥 المستخدمين'}].map(item => (
            <button 
              key={item.id} 
              onClick={() => setActiveTab(item.id as any)} 
              className={`w-full text-right p-4 rounded-xl font-bold transition-all duration-300 ${activeTab === item.id ? 'bg-blue-600 text-white shadow-lg translate-x-1' : 'text-slate-400 hover:bg-slate-800'}`}
            >
