        </nav>
      </aside>

      <main className="flex-1 overflow-y-auto p-4 md:p-10">
        <header className="mb-10 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <h2 className="text-3xl font-extrabold text-slate-800">مرحباً، {user.name}</h2>
            <p className="text-slate-500 font-medium">مراقبة حية لكافة الأنشطة 🟢</p>
          </div>
          <div className="bg-white p-3 rounded-2xl shadow-sm border border-slate-100 flex items-center gap-3">
             <div className="w-3 h-3 bg-green-500 rounded-full animate-pulse"></div>
             <span className="text-xs font-bold text-slate-600 uppercase tracking-widest">Firestore Live</span>
          </div>
        </header>

        {currentFailedOrders.length > 0 && (
          <div className="mb-10 p-8 bg-red-50 border-r-8 border-red-600 rounded-3xl shadow-xl animate-fadeIn">
             <div className="flex items-center gap-5 mb-6">
                <div className="w-14 h-14 bg-red-600 text-white rounded-2xl flex items-center justify-center text-3xl animate-bounce shadow-lg">⚠️</div>
                <div>
                   <h3 className="text-2xl font-black text-red-900">تنبيه: مهام فاشلة / معطلة</h3>
                   <p className="text-sm font-bold text-red-600">هناك {currentFailedOrders.length} طلبات أبلغ الفنيون عن تعثرها</p>
                </div>
             </div>
             <div className="grid grid-cols-1 gap-4">
                {currentFailedOrders.map(o => (
                  <div key={o.id} className="bg-white p-6 rounded-2xl border border-red-100 flex flex-col md:flex-row justify-between items-center gap-6 shadow-sm hover:shadow-md transition-shadow">
                     <div className="flex-1">
                        <div className="flex items-center gap-2 mb-1">
                          <p className="font-black text-blue-900 text-lg">{o.customerName}</p>
                          <span className="bg-orange-100 text-orange-600 text-[10px] font-black px-2 py-0.5 rounded uppercase">{o.serviceType}</span>
                        </div>
                        <div className="bg-red-50 p-3 rounded-xl border border-red-100 mt-2">
                           <p className="text-xs font-black text-red-600 mb-1">ملاحظة الفني:</p>
                           <p className="text-sm text-red-800 font-bold italic">"{o.failureReason || 'لم يتم ذكر سبب'}"</p>
                        </div>
                        <div className="mt-3">
                           <p className="text-sm font-black text-slate-800">{o.technicianName}</p>
                           <p className="text-[10px] font-black text-orange-600 uppercase">الوظيفة: {o.technicianSpecialty}</p>
                           <p className="text-[10px] text-gray-400 font-bold">{o.technicianPhone}</p>
                        </div>
                     </div>
                     <div className="flex gap-3">
                        <button onClick={() => resolveError(o.id)} className="bg-emerald-500 hover:bg-emerald-600 text-white px-8 py-3 rounded-xl font-black text-xs shadow-lg transition-all active:scale-95">تم المراجعة والحل</button>
                     </div>
                  </div>
                ))}
             </div>
          </div>
        )}

        {activeTab === 'stats' && (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 animate-fadeIn">
            <StatCard title="مهام جارية" val={stats.active} color="from-blue-600 to-blue-800" />
            <StatCard title="أعطال نشطة" val={stats.failed} color="from-red-600 to-red-800" />
            <StatCard title="إجمالي النجاح" val={stats.completed} color="from-emerald-600 to-emerald-800" />
            <StatCard title="فنيين معتمدين" val={stats.techs} color="from-slate-700 to-slate-900" />
          </div>
        )}

        {(activeTab === 'orders' || activeTab === 'completed-log') && (
          <div className="bg-white rounded-[2.5rem] shadow-xl overflow-hidden border border-slate-100 animate-fadeIn mt-8">
            <div className="overflow-x-auto">
              <table className="w-full text-right border-collapse">
                <thead className="bg-slate-50 border-b border-slate-100">
                  <tr>
                    <th className="p-6 text-xs font-black text-slate-600 uppercase tracking-widest">العميل والموقع</th>
                    <th className="p-6 text-xs font-black text-slate-600 uppercase tracking-widest">الفني والبيانات</th>
                    <th className="p-6 text-xs font-black text-slate-600 uppercase tracking-widest text-center">الحالة</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {(activeTab === 'orders' ? orders.filter(o => o.status !== 'completed' && o.status !== 'failed') : orders.filter(o => o.status === 'completed' || (o.status === 'failed' && o.adminResolved))).map(o => (
                    <tr key={o.id} className="hover:bg-blue-50/40 transition-colors group">
                      <td className="p-6">
                        <p className="font-black text-slate-800 text-base">{o.customerName}</p>
                        <p className="text-[10px] text-orange-600 font-black flex items-center gap-1 mt-1">📍 {o.detailedLocation || o.address}</p>
                        <p className="text-[11px] text-slate-400 mt-1 line-clamp-1 italic">{o.description}</p>
                      </td>
                      <td className="p-6">
                        <div className="flex flex-col">
                           <p className="text-sm font-black text-blue-900">{o.technicianName || <span className="text-gray-300 italic">انتظار القبول</span>}</p>
                           {o.technicianSpecialty && (
                             <p className="text-[11px] text-orange-600 font-black mt-0.5 tracking-tight border-b border-orange-100 pb-0.5 w-fit">
                               الوظيفة: {o.technicianSpecialty}
                             </p>
                           )}
                           {o.technicianPhone && <p className="text-[10px] text-gray-500 font-bold mt-0.5">{o.technicianPhone}</p>}
                        </div>
                      </td>
                      <td className="p-6 text-center">
                        <span className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest ${
                          o.status === 'pending' ? 'bg-amber-100 text-amber-700' : 
                          o.status === 'assigned' ? 'bg-blue-100 text-blue-700' : 
                          o.status === 'completed' ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-700'
                        }`}>
                          {o.status === 'pending' ? 'انتظار' : o.status === 'assigned' ? 'جاري' : o.status === 'completed' ? 'تم' : 'فشل'}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activeTab === 'users' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-fadeIn mt-8">
            {users.map(u => (
              <div key={u.id} className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col justify-center items-center group hover:shadow-xl hover:-translate-y-1 transition-all duration-300 text-center">
                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center mb-4 text-2xl ${u.role === 'customer' ? 'bg-blue-50' : u.isApproved ? 'bg-emerald-50' : 'bg-amber-50 animate-pulse'}`}>
                  {u.role === 'customer' ? '👤' : '🛠️'}
                </div>
                <p className="font-black text-slate-800 text-lg leading-none mb-2">{u.name}</p>
                <p className="text-xs text-slate-400 font-bold mb-4">{u.phone}</p>

                <div className="flex flex-col items-center gap-3 w-full">
                  <div className="flex items-center gap-2">
                    <span className={`text-[9px] font-black px-4 py-1.5 rounded-full uppercase tracking-widest ${
                      u.role === 'customer' ? 'bg-blue-50 text-blue-600' : 'bg-emerald-50 text-emerald-600'
                    }`}>
                      {u.role === 'customer' ? 'عميل' : 'فني'}
                    </span>
                    {u.role === 'technician' && (
                      <span className={`text-[8px] font-black px-2 py-1 rounded-md uppercase ${u.isApproved ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                        {u.isApproved ? 'موثق' : 'غير موثق'}
                      </span>
                    )}
                  </div>

                  {u.role === 'technician' && (
                    <p className="text-[10px] font-black text-orange-600">تخصص: {u.specialty}</p>
                  )}

                  {/* زر الاعتماد يظهر للفنيين غير المعتمدين فقط */}
                  {u.role === 'technician' && !u.isApproved && (
                    <button 
                      onClick={() => approveTechnician(u.id)}
                      className="w-full mt-2 bg-blue-600 hover:bg-blue-700 text-white py-3 rounded-xl font-black text-xs shadow-lg transition-all active:scale-95"
                    >
                      اعتماد الفني الآن ✅
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </main>
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import { collection, addDoc, query, where, onSnapshot } from 'firebase/firestore';
import { db } from '../firebase';
import { User, Order } from '../types';

interface CustomerDashboardProps {
  user: User;
  onLogout: () => void;
}

const CustomerDashboard: React.FC<CustomerDashboardProps> = ({ user, onLogout }) => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [serviceType, setServiceType] = useState<string>('');
  const [description, setDescription] = useState('');
  const [detailedLocation, setDetailedLocation] = useState('');
  const [timing, setTiming] = useState('اليوم');
  const [hourIndex, setHourIndex] = useState(2); // الافتراضي ظهراً
  const [isOrdering, setIsOrdering] = useState(false);

  const hourOptions = [
    { label: 'صباحاً', range: '8ص - 11ص' },
    { label: 'ظهراً', range: '12ظ - 2م' },
    { label: 'عصراً', range: '3م - 5م' },
    { label: 'مساءً', range: '6م - 9م' },
    { label: 'ليلاً', range: '10م - 12ل' }
  ];

  useEffect(() => {
    const q = query(collection(db, 'orders'), where('customerId', '==', user.id));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const ordersData = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));
      setOrders(ordersData.sort((a, b) => b.createdAt - a.createdAt));
    });
    return () => unsubscribe();
  }, [user.id]);

  const handleCreateOrder = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!serviceType) return alert('يرجى اختيار نوع الخدمة أولاً');

    setIsOrdering(true);
    try {
      await addDoc(collection(db, 'orders'), {
        customerId: user.id,
        customerName: user.name,
        customerPhone: user.phone,
        address: user.address || '',
        detailedLocation,
        serviceType,
        description,
        preferredTiming: timing,
        specificTime: `${hourOptions[hourIndex].label} (${hourOptions[hourIndex].range})`,
        status: 'pending',
        createdAt: Date.now(),
        adminResolved: true 
      });
      alert('تم إرسال طلبك بنجاح! سيقوم الفني بالتواصل معك.');
      setServiceType('');
      setDescription('');
      setDetailedLocation('');
    } catch (err) {
      alert('فشل إرسال الطلب، يرجى المحاولة لاحقاً');
    } finally {
      setIsOrdering(false);
    }
  };

  // تم تحديث القائمة بناءً على طلب المستخدم: استبدال أجهزة بـ دش وحذف كاميرات
  const serviceOptions = ['سباك', 'كهربائي', 'نجار', 'فني دش', 'نقاش'];

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row font-sans">
      <aside className="w-full md:w-80 bg-white border-l border-gray-100 p-8 shadow-sm">
        <div className="mb-10 text-center">
           <div className="w-20 h-20 bg-blue-100 rounded-3xl flex items-center justify-center mx-auto mb-4 text-3xl">👤</div>
           <h2 className="text-xl font-black text-blue-900">{user.name}</h2>
           <p className="text-gray-400 font-bold text-sm">عميل الأسطى</p>
        </div>
        <div className="space-y-6">
           <h3 className="text-sm font-black text-blue-900/40 uppercase tracking-widest">طلباتي الحالية</h3>
           <div className="space-y-3 max-h-[400px] overflow-y-auto">
              {orders.filter(o => o.status !== 'completed').map(o => (
                <div key={o.id} className="p-4 bg-gray-50 rounded-2xl border-r-4 border-orange-500">
                   <p className="text-xs font-black text-blue-900 mb-1">{o.serviceType}</p>
                   {o.status === 'pending' ? (
                     <span className="text-[10px] font-bold text-gray-400 italic">بانتظار فني...</span>
                   ) : (
                     <div className="mt-2">
                        <p className="text-[10px] font-black text-orange-600">الفني: {o.technicianName}</p>
                        <p className="text-[9px] font-bold text-gray-400">({o.technicianSpecialty})</p>
                     </div>
                   )}
                </div>
              ))}
              {orders.filter(o => o.status !== 'completed').length === 0 && (
                <p className="text-xs text-gray-300 font-bold text-center py-4">لا توجد طلبات نشطة</p>
              )}
           </div>
        </div>
        <button onClick={onLogout} className="w-full mt-12 bg-red-50 text-red-500 font-black py-4 rounded-2xl hover:bg-red-500 hover:text-white transition-all">خروج</button>
      </aside>

      <main className="flex-1 p-4 md:p-8 overflow-y-auto">
        <div className="max-w-2xl mx-auto">
          <div className="bg-blue-600 text-white p-10 rounded-t-[3rem] text-center shadow-lg relative overflow-hidden">
             <div className="absolute top-0 right-0 p-4 opacity-10 text-9xl">📋</div>
             <h1 className="text-3xl font-black mb-2">طلب صيانة جديد</h1>
             <p className="text-blue-100 font-bold">أخبرنا بمشكلتك وسنرسل لك أفضل فني</p>
          </div>

          <form onSubmit={handleCreateOrder} className="bg-white p-8 md:p-12 rounded-b-[3rem] shadow-2xl space-y-10">
            <div>
              <h3 className="font-black text-gray-700 mb-4">1. اختر نوع الخدمة</h3>
              <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                {serviceOptions.map(opt => (
                  <button key={opt} type="button" onClick={() => setServiceType(opt)} className={`p-4 rounded-2xl font-bold transition-all border-2 ${serviceType === opt ? 'bg-blue-50 border-blue-600 text-blue-900 shadow-md scale-105' : 'bg-gray-50 border-transparent text-gray-500 hover:border-blue-200'}`}>{opt}</button>
                ))}
              </div>
            </div>

            <div>
              <h3 className="font-black text-gray-700 mb-4">2. وصف المشكلة</h3>
              <textarea required value={description} onChange={e => setDescription(e.target.value)} placeholder="اكتب تفاصيل العطل هنا..." className="w-full bg-gray-50 p-6 rounded-3xl border-2 border-transparent focus:border-blue-500 outline-none font-bold text-gray-700 min-h-[120px]" />
            </div>

            <div>
              <h3 className="font-black text-gray-700 mb-4">3. الموقع والموعد</h3>
              <input type="text" required value={detailedLocation} onChange={e => setDetailedLocation(e.target.value)} placeholder="العنوان بالتفصيل (الحي، الشارع، الشقة)..." className="w-full bg-gray-50 p-5 rounded-2xl border-2 border-transparent focus:border-blue-500 outline-none font-bold text-gray-700 mb-6" />

              <div className="bg-blue-50 p-6 rounded-3xl">
                <div className="flex justify-between mb-4">
                  {hourOptions.map((h, idx) => (
                    <button key={h.label} type="button" onClick={() => setHourIndex(idx)} className={`text-[10px] font-black transition-all ${hourIndex === idx ? 'text-orange-500 scale-125' : 'text-gray-400'}`}>{h.label}</button>
                  ))}
                </div>
                <input type="range" min="0" max="4" step="1" value={hourIndex} onChange={(e) => setHourIndex(parseInt(e.target.value))} className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-orange-500" />
                <div className="mt-6 bg-blue-900 text-white p-4 rounded-2xl flex items-center justify-between">
                   <div className="flex items-center gap-3">
                      <span className="text-2xl">🕗</span>
                      <div>
                         <p className="text-[10px] opacity-60 font-bold">الموعد المحدد</p>
                         <p className="text-sm font-black">{timing} • {hourOptions[hourIndex].label} ({hourOptions[hourIndex].range})</p>
                      </div>
                   </div>
                </div>
              </div>
            </div>

            <button type="submit" disabled={isOrdering} className="w-full bg-orange-500 hover:bg-orange-600 text-white font-black py-5 rounded-[2rem] shadow-xl transition-all transform hover:scale-[1.02] text-xl">
              {isOrdering ? 'جاري الإرسال...' : 'تأكيد الطلب 🚀'}
            </button>
          </form>
        </div>
      </main>
    </div>
  );
};

export default CustomerDashboard;

import React, { useState } from 'react';
import { collection, addDoc, query, where, getDocs } from 'firebase/firestore';
import { db } from '../firebase';
import { UserRole } from '../types';

interface RegisterProps {
  onSwitch: () => void;
}

const Register: React.FC<RegisterProps> = ({ onSwitch }) => {
  const [role, setRole] = useState<UserRole>('customer');
  const [showPassword, setShowPassword] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    password: '',
    address: '',
    securityQuestion: 'ما هو اسم مدرستك الابتدائية؟',
    securityAnswer: '',
    specialty: 'نجار',
    experience: 1,
    area: ''
  });
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  // تم تحديث التخصصات لتطابق خيارات الطلبات: نجار، كهربائي، سباك، فني دش، نقاش
  const specialties = ['نجار', 'كهربائي', 'سباك', 'فني دش', 'نقاش'];

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setError('');

    try {
      const q = query(collection(db, 'users'), where('phone', '==', formData.phone));
      const snap = await getDocs(q);
      if (!snap.empty) {
        setError('هذا الهاتف مسجل مسبقاً');
        setIsSubmitting(false);
        return;
      }

      await addDoc(collection(db, 'users'), {
        ...formData,
        role,
        isApproved: role === 'customer', // العميل معتمد تلقائياً، الفني يحتاج موافقة
        createdAt: Date.now()
      });
      setSuccess('تم إنشاء الحساب بنجاح! الفنيين يحتاجون لموافقة الإدارة قبل البدء.');
      setTimeout(onSwitch, 2500);
    } catch (err) {
      setError('حدث خطأ أثناء التسجيل');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen py-10 bg-gray-100 flex items-center justify-center px-4">
      <div className="bg-white w-full max-w-2xl p-8 rounded-2xl shadow-xl">
        <h2 className="text-3xl font-extrabold text-blue-900 mb-6 text-center">إنشاء حساب جديد</h2>

        <div className="flex bg-gray-100 p-1 rounded-lg mb-8">
          <button 
            type="button"
            onClick={() => setRole('customer')}
            className={`flex-1 py-2 rounded-md font-bold transition ${role === 'customer' ? 'bg-white shadow-md text-blue-800' : 'text-gray-500'}`}
          >عميل</button>
          <button 
            type="button"
            onClick={() => setRole('technician')}
            className={`flex-1 py-2 rounded-md font-bold transition ${role === 'technician' ? 'bg-white shadow-md text-blue-800' : 'text-gray-500'}`}
          >فني</button>
        </div>

        <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="col-span-1">
            <label className="block text-sm font-bold text-gray-700 mb-1">الاسم بالكامل</label>
            <input name="name" required onChange={handleInputChange} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
          </div>
          <div className="col-span-1">
            <label className="block text-sm font-bold text-gray-700 mb-1">رقم الهاتف</label>
            <input name="phone" required onChange={handleInputChange} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
          </div>
          <div className="col-span-1 relative">
            <label className="block text-sm font-bold text-gray-700 mb-1">كلمة المرور</label>
            <input 
              name="password" 
              type={showPassword ? "text" : "password"} 
              required 
              onChange={handleInputChange} 
              className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
            />
            <button 
              type="button" 
              onClick={() => setShowPassword(!showPassword)}
              className="absolute left-2 bottom-2 text-gray-400"
            >
              {showPassword ? '🙈' : '👁️'}
            </button>
          </div>
          <div className="col-span-1">
            <label className="block text-sm font-bold text-gray-700 mb-1">العنوان</label>
            <input name="address" required onChange={handleInputChange} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
          </div>

          <div className="col-span-2">
            <label className="block text-sm font-bold text-gray-700 mb-1">سؤال الأمان</label>
            <select name="securityQuestion" onChange={handleInputChange} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white">
              <option>ما هو اسم مدرستك الابتدائية؟</option>
              <option>ما هو اسم حيوانك الأليف؟</option>
              <option>ما هي مدينتك المفضلة؟</option>
            </select>
          </div>
          <div className="col-span-2">
            <label className="block text-sm font-bold text-gray-700 mb-1">إجابة سؤال الأمان</label>
            <input name="securityAnswer" required onChange={handleInputChange} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
          </div>

          {role === 'technician' && (
            <>
              <div className="col-span-1">
                <label className="block text-sm font-bold text-gray-700 mb-1">التخصص</label>
                <select name="specialty" value={formData.specialty} onChange={handleInputChange} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white">
                  {specialties.map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>
              <div className="col-span-1">
                <label className="block text-sm font-bold text-gray-700 mb-1">سنوات الخبرة</label>
                <input name="experience" type="number" required onChange={handleInputChange} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
              </div>
              <div className="col-span-2">
                <label className="block text-sm font-bold text-gray-700 mb-1">منطقة العمل</label>
                <input name="area" required onChange={handleInputChange} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
              </div>
            </>
          )}

          {error && <p className="col-span-2 text-red-500 text-sm font-bold text-center">{error}</p>}
          {success && <p className="col-span-2 text-green-500 text-sm font-bold text-center">{success}</p>}

          <div className="col-span-2 pt-4">
            <button
              type="submit"
              disabled={isSubmitting}
              className="w-full bg-blue-700 hover:bg-blue-800 text-white font-bold py-3 rounded-lg shadow transition-all disabled:opacity-50"
            >
              {isSubmitting ? 'جاري التسجيل...' : 'تسجيل الحساب'}
            </button>
            <button onClick={onSwitch} type="button" className="w-full mt-4 text-gray-500 hover:underline">رجوع لتسجيل الدخول</button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default Register;

import React, { useState, useEffect } from 'react';
import { collection, addDoc, query, where, onSnapshot } from 'firebase/firestore';
import { db } from '../firebase';
import { User, Order } from '../types';

interface CustomerDashboardProps {
  user: User;
  onLogout: () => void;
}

const CustomerDashboard: React.FC<CustomerDashboardProps> = ({ user, onLogout }) => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [serviceType, setServiceType] = useState<string>('');
  const [description, setDescription] = useState('');
  const [detailedLocation, setDetailedLocation] = useState('');
  const [timing, setTiming] = useState('اليوم');
  const [hourIndex, setHourIndex] = useState(2); // الافتراضي ظهراً
  const [isOrdering, setIsOrdering] = useState(false);

  const hourOptions = [
    { label: 'صباحاً', range: '8ص - 11ص' },
    { label: 'ظهراً', range: '12ظ - 2م' },
    { label: 'عصراً', range: '3م - 5م' },
    { label: 'مساءً', range: '6م - 9م' },
    { label: 'ليلاً', range: '10م - 12ل' }
  ];

  useEffect(() => {
    const q = query(collection(db, 'orders'), where('customerId', '==', user.id));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const ordersData = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));
      setOrders(ordersData.sort((a, b) => b.createdAt - a.createdAt));
    });
    return () => unsubscribe();
  }, [user.id]);

  const handleCreateOrder = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!serviceType) return alert('يرجى اختيار نوع الخدمة أولاً');

    setIsOrdering(true);
    try {
      await addDoc(collection(db, 'orders'), {
        customerId: user.id,
        customerName: user.name,
        customerPhone: user.phone,
        address: user.address || '',
        detailedLocation,
        serviceType,
        description,
        preferredTiming: timing,
        specificTime: `${hourOptions[hourIndex].label} (${hourOptions[hourIndex].range})`,
        status: 'pending',
        createdAt: Date.now(),
        adminResolved: true 
      });
      // تم تحديث الرسالة هنا بناءً على طلبك
      alert('تم إرسال طلبك بنجاح! يتم مراجعة الطلب الآن.');
      setServiceType('');
      setDescription('');
      setDetailedLocation('');
    } catch (err) {
      alert('فشل إرسال الطلب، يرجى المحاولة لاحقاً');
    } finally {
      setIsOrdering(false);
    }
  };

  // القائمة المحدثة: نجار، كهربائي، سباك، فني دش، نقاش
  const serviceOptions = ['سباك', 'كهربائي', 'نجار', 'فني دش', 'نقاش'];

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row font-sans">
      <aside className="w-full md:w-80 bg-white border-l border-gray-100 p-8 shadow-sm">
        <div className="mb-10 text-center">
           <div className="w-20 h-20 bg-blue-100 rounded-3xl flex items-center justify-center mx-auto mb-4 text-3xl">👤</div>
           <h2 className="text-xl font-black text-blue-900">{user.name}</h2>
           <p className="text-gray-400 font-bold text-sm">عميل الأسطى</p>
        </div>
        <div className="space-y-6">
           <h3 className="text-sm font-black text-blue-900/40 uppercase tracking-widest">طلباتي الحالية</h3>
           <div className="space-y-3 max-h-[400px] overflow-y-auto">
              {orders.filter(o => o.status !== 'completed').map(o => (
                <div key={o.id} className="p-4 bg-gray-50 rounded-2xl border-r-4 border-orange-500">
                   <p className="text-xs font-black text-blue-900 mb-1">{o.serviceType}</p>
                   {o.status === 'pending' ? (
                     <span className="text-[10px] font-bold text-gray-400 italic">يتم مراجعة الطلب...</span>
                   ) : (
                     <div className="mt-2">
                        <p className="text-[10px] font-black text-orange-600">الفني: {o.technicianName}</p>
                        <p className="text-[9px] font-bold text-gray-400">({o.technicianSpecialty})</p>
                     </div>
                   )}
                </div>
              ))}
              {orders.filter(o => o.status !== 'completed').length === 0 && (
                <p className="text-xs text-gray-300 font-bold text-center py-4">لا توجد طلبات نشطة</p>
              )}
           </div>
        </div>
        <button onClick={onLogout} className="w-full mt-12 bg-red-50 text-red-500 font-black py-4 rounded-2xl hover:bg-red-500 hover:text-white transition-all">خروج</button>
      </aside>

      <main className="flex-1 p-4 md:p-8 overflow-y-auto">
        <div className="max-w-2xl mx-auto">
          <div className="bg-blue-600 text-white p-10 rounded-t-[3rem] text-center shadow-lg relative overflow-hidden">
             <div className="absolute top-0 right-0 p-4 opacity-10 text-9xl">📋</div>
             <h1 className="text-3xl font-black mb-2">طلب صيانة جديد</h1>
             <p className="text-blue-100 font-bold">أخبرنا بمشكلتك وسنرسل لك أفضل فني</p>
          </div>

          <form onSubmit={handleCreateOrder} className="bg-white p-8 md:p-12 rounded-b-[3rem] shadow-2xl space-y-10">
            <div>
              <h3 className="font-black text-gray-700 mb-4">1. اختر نوع الخدمة</h3>
              <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                {serviceOptions.map(opt => (
                  <button key={opt} type="button" onClick={() => setServiceType(opt)} className={`p-4 rounded-2xl font-bold transition-all border-2 ${serviceType === opt ? 'bg-blue-50 border-blue-600 text-blue-900 shadow-md scale-105' : 'bg-gray-50 border-transparent text-gray-500 hover:border-blue-200'}`}>{opt}</button>
                ))}
              </div>
            </div>

            <div>
              <h3 className="font-black text-gray-700 mb-4">2. وصف المشكلة</h3>
              <textarea required value={description} onChange={e => setDescription(e.target.value)} placeholder="اكتب تفاصيل العطل هنا..." className="w-full bg-gray-50 p-6 rounded-3xl border-2 border-transparent focus:border-blue-500 outline-none font-bold text-gray-700 min-h-[120px]" />
            </div>

            <div>
              <h3 className="font-black text-gray-700 mb-4">3. الموقع والموعد</h3>
              <input type="text" required value={detailedLocation} onChange={e => setDetailedLocation(e.target.value)} placeholder="العنوان بالتفصيل (الحي، الشارع، الشقة)..." className="w-full bg-gray-50 p-5 rounded-2xl border-2 border-transparent focus:border-blue-500 outline-none font-bold text-gray-700 mb-6" />

              <div className="bg-blue-50 p-6 rounded-3xl">
                <div className="flex justify-between mb-4">
                  {hourOptions.map((h, idx) => (
                    <button key={h.label} type="button" onClick={() => setHourIndex(idx)} className={`text-[10px] font-black transition-all ${hourIndex === idx ? 'text-orange-500 scale-125' : 'text-gray-400'}`}>{h.label}</button>
                  ))}
                </div>
                <input type="range" min="0" max="4" step="1" value={hourIndex} onChange={(e) => setHourIndex(parseInt(e.target.value))} className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-orange-500" />
                <div className="mt-6 bg-blue-900 text-white p-4 rounded-2xl flex items-center justify-between">
                   <div className="flex items-center gap-3">
                      <span className="text-2xl">🕗</span>
                      <div>
                         <p className="text-[10px] opacity-60 font-bold">الموعد المحدد</p>
                         <p className="text-sm font-black">{timing} • {hourOptions[hourIndex].label} ({hourOptions[hourIndex].range})</p>
                      </div>
                   </div>
                </div>
              </div>
            </div>

            <button type="submit" disabled={isOrdering} className="w-full bg-orange-500 hover:bg-orange-600 text-white font-black py-5 rounded-[2rem] shadow-xl transition-all transform hover:scale-[1.02] text-xl">
              {isOrdering ? 'جاري الإرسال...' : 'تأكيد الطلب 🚀'}
            </button>
          </form>
        </div>
      </main>
    </div>
  );
};

