    { label: 'ظهراً', range: '12ظ - 2م' },
    { label: 'عصراً', range: '3م - 5م' },
    { label: 'مساءً', range: '6م - 9م' },
    { label: 'ليلاً', range: '10م - 12ل' }
  ];

  useEffect(() => {
    const unsubUser = onSnapshot(doc(db, 'users', user.id), (docSnap) => {
      if (docSnap.exists()) {
        const data = { id: docSnap.id, ...docSnap.data() } as User;
        setCurrentUserData(data);
        fetchFavoriteTechs(data.favoriteTechIds || []);
      }
    });

    const q = query(collection(db, 'orders'), where('customerId', '==', user.id));
    const unsubscribeOrders = onSnapshot(q, (snapshot) => {
      const ordersData = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));
      setOrders(ordersData.sort((a, b) => b.createdAt - a.createdAt));
    });

    return () => { unsubUser(); unsubscribeOrders(); };
  }, [user.id]);

  const fetchFavoriteTechs = async (ids: string[]) => {
    if (ids.length === 0) {
      setFavoriteTechs([]);
      return;
    }
    const q = query(collection(db, 'users'), where('__name__', 'in', ids));
    const snap = await getDocs(q);
    setFavoriteTechs(snap.docs.map(d => ({ id: d.id, ...d.data() } as User)));
  };

  const toggleFavorite = async (techId: string) => {
    const userRef = doc(db, 'users', user.id);
    const isFav = currentUserData.favoriteTechIds?.includes(techId);
    try {
      await updateDoc(userRef, {
        favoriteTechIds: isFav ? arrayRemove(techId) : arrayUnion(techId)
      });
    } catch (err) {
      alert('خطأ في تحديث قائمة المفضلين');
    }
  };

  const handleCreateOrder = async (e: React.FormEvent, directTech: User | null = null) => {
    e.preventDefault();
    const finalServiceType = directTech ? directTech.specialty : serviceType;
    if (!finalServiceType) return alert('يرجى اختيار نوع الخدمة أولاً');

    setIsOrdering(true);
    try {
      const orderPayload: any = {
        customerId: user.id,
        customerName: user.name,
        customerPhone: user.phone,
        address: user.address || '',
        detailedLocation,
        serviceType: finalServiceType,
        description,
        preferredTiming: timing,
        specificTime: `${hourOptions[hourIndex].label} (${hourOptions[hourIndex].range})`,
        status: directTech ? 'assigned' : 'pending', // إذا كان مباشر يتم إسناده فوراً
        createdAt: Date.now(),
        adminResolved: true 
      };

      if (directTech) {
        orderPayload.technicianId = directTech.id;
        orderPayload.technicianName = directTech.name;
        orderPayload.technicianSpecialty = directTech.specialty;
        orderPayload.technicianPhone = directTech.phone;
      }

      await addDoc(collection(db, 'orders'), orderPayload);
      alert(directTech ? `تم إرسال الطلب المباشر للأسطى ${directTech.name} بنجاح!` : 'تم إرسال طلبك بنجاح! يتم مراجعة الطلب الآن.');

      // ريست
      setServiceType('');
      setDescription('');
      setDetailedLocation('');
      setSelectedTechForOrder(null);
      setActiveTab('history');
    } catch (err) {
      alert('فشل إرسال الطلب، يرجى المحاولة لاحقاً');
    } finally {
      setIsOrdering(false);
    }
  };

  const serviceOptions = ['سباك', 'كهربائي', 'نجار', 'فني دش', 'نقاش'];

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row font-sans relative">

      {/* نافذة الطلب المباشر المنبثقة */}
      {selectedTechForOrder && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fadeIn">
          <div className="bg-white w-full max-w-xl rounded-[3rem] shadow-2xl overflow-hidden">
            <div className="bg-orange-500 p-6 text-white text-center relative">
               <button onClick={() => setSelectedTechForOrder(null)} className="absolute left-6 top-6 hover:scale-110 transition">✖️</button>
               <p className="text-xs font-black uppercase tracking-widest opacity-80">طلب صيانة مباشر</p>
               <h3 className="text-2xl font-black mt-1">الأسطى {selectedTechForOrder.name}</h3>
            </div>
            <form onSubmit={(e) => handleCreateOrder(e, selectedTechForOrder)} className="p-8 space-y-6">
               <div>
                  <label className="block text-xs font-black text-slate-400 mb-2">نوع الخدمة (تخصص الفني)</label>
                  <div className="bg-gray-100 p-4 rounded-2xl font-black text-blue-900">{selectedTechForOrder.specialty}</div>
               </div>
               <div>
                  <label className="block text-xs font-black text-slate-400 mb-2">وصف العطل</label>
                  <textarea required value={description} onChange={e => setDescription(e.target.value)} placeholder="مثلاً: صنبور المطبخ يسرب ماء..." className="w-full bg-gray-50 p-4 rounded-2xl border-none focus:ring-2 focus:ring-orange-500 outline-none font-bold text-sm min-h-[100px]" />
               </div>
               <div>
                  <label className="block text-xs font-black text-slate-400 mb-2">العنوان بالتفصيل</label>
                  <input required value={detailedLocation} onChange={e => setDetailedLocation(e.target.value)} placeholder="رقم العقار، الطابق، علامة مميزة..." className="w-full bg-gray-50 p-4 rounded-2xl border-none focus:ring-2 focus:ring-orange-500 outline-none font-bold text-sm" />
               </div>
               <div className="flex gap-4">
                  <button type="button" onClick={() => setSelectedTechForOrder(null)} className="flex-1 bg-gray-100 text-gray-500 font-black py-4 rounded-2xl">إلغاء</button>
                  <button type="submit" disabled={isOrdering} className="flex-2 bg-blue-900 text-white font-black py-4 px-8 rounded-2xl shadow-xl hover:bg-blue-800 transition-all">
                    {isOrdering ? 'جاري الإرسال...' : 'تأكيد الطلب المباشر 🚀'}
                  </button>
               </div>
            </form>
          </div>
        </div>
      )}

      {/* Sidebar */}
      <aside className="w-full md:w-80 bg-white border-l border-gray-100 flex flex-col shadow-sm">
        <div className="p-8 text-center">
           <div className="w-20 h-20 bg-blue-100 rounded-3xl flex items-center justify-center mx-auto mb-4 text-3xl">👤</div>
           <h2 className="text-xl font-black text-blue-900">{user.name}</h2>
           <p className="text-gray-400 font-bold text-sm">عميل الأسطى</p>
        </div>

        <nav className="px-6 space-y-2 mb-8">
           <button onClick={() => setActiveTab('new-order')} className={`w-full text-right p-4 rounded-2xl font-black transition-all ${activeTab === 'new-order' ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-400 hover:bg-gray-50'}`}>🆕 طلب جديد</button>
           <button onClick={() => setActiveTab('history')} className={`w-full text-right p-4 rounded-2xl font-black transition-all ${activeTab === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-400 hover:bg-gray-50'}`}>📜 سجل الطلبات</button>
        </nav>

        <div className="flex-1 px-6 overflow-y-auto">
           <h3 className="text-xs font-black text-blue-900/40 uppercase tracking-widest mb-4">⭐ الفنيين المفضلين</h3>
           <div className="space-y-4 pb-8">
              {favoriteTechs.map(tech => (
                <div key={tech.id} className="p-4 bg-orange-50 rounded-2xl border border-orange-100 relative group transition-all hover:shadow-md">
                   <div className="flex justify-between items-start mb-2">
                      <div>
                        <p className="text-xs font-black text-blue-900">{tech.name}</p>
                        <p className="text-[10px] font-bold text-orange-600">{tech.specialty}</p>
                      </div>
                      <button onClick={() => toggleFavorite(tech.id)} className="text-red-400 hover:text-red-600 transition">💔</button>
                   </div>
                   <button 
                    onClick={() => setSelectedTechForOrder(tech)}
                    className="w-full bg-white text-orange-600 border border-orange-200 py-1.5 rounded-lg text-[10px] font-black hover:bg-orange-500 hover:text-white transition-all mt-2"
                   >
                     اطلب الآن 🛠️
                   </button>
                </div>
              ))}
              {favoriteTechs.length === 0 && (
                <p className="text-[10px] text-gray-300 font-bold text-center italic py-4">لم تضف أي فني للمفضلين بعد</p>
              )}
           </div>
        </div>

        <div className="p-6 border-t border-gray-50">
          <button onClick={onLogout} className="w-full bg-red-50 text-red-500 font-black py-4 rounded-2xl hover:bg-red-500 hover:text-white transition-all">خروج</button>
        </div>
      </aside>

      <main className="flex-1 p-4 md:p-8 overflow-y-auto">
        {activeTab === 'new-order' ? (
          <div className="max-w-2xl mx-auto animate-fadeIn">
            <div className="bg-blue-600 text-white p-10 rounded-t-[3rem] text-center shadow-lg relative overflow-hidden">
               <div className="absolute top-0 right-0 p-4 opacity-10 text-9xl">📋</div>
               <h1 className="text-3xl font-black mb-2">طلب صيانة جديد</h1>
               <p className="text-blue-100 font-bold">أخبرنا بمشكلتك وسنرسل لك أفضل فني</p>
            </div>

            <form onSubmit={(e) => handleCreateOrder(e)} className="bg-white p-8 md:p-12 rounded-b-[3rem] shadow-2xl space-y-10">
              <div>
                <h3 className="font-black text-gray-700 mb-4">1. اختر نوع الخدمة</h3>
                <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                  {serviceOptions.map(opt => (
                    <button key={opt} type="button" onClick={() => setServiceType(opt)} className={`p-4 rounded-2xl font-bold transition-all border-2 ${serviceType === opt ? 'bg-blue-50 border-blue-600 text-blue-900 shadow-md scale-105' : 'bg-gray-50 border-transparent text-gray-500 hover:border-blue-200'}`}>{opt}</button>
                  ))}
                </div>
              </div>

              <div>
                <h3 className="font-black text-gray-700 mb-4">2. وصف المشكلة</h3>
                <textarea required value={description} onChange={e => setDescription(e.target.value)} placeholder="اكتب تفاصيل العطل هنا..." className="w-full bg-gray-50 p-6 rounded-3xl border-2 border-transparent focus:border-blue-500 outline-none font-bold text-gray-700 min-h-[120px]" />
              </div>

              <div>
                <h3 className="font-black text-gray-700 mb-4">3. الموقع والموعد</h3>
                <input type="text" required value={detailedLocation} onChange={e => setDetailedLocation(e.target.value)} placeholder="العنوان بالتفصيل (الحي، الشارع، الشقة)..." className="w-full bg-gray-50 p-5 rounded-2xl border-2 border-transparent focus:border-blue-500 outline-none font-bold text-gray-700 mb-6" />

                <div className="bg-blue-50 p-6 rounded-3xl">
                  <div className="flex justify-between mb-4">
                    {hourOptions.map((h, idx) => (
                      <button key={h.label} type="button" onClick={() => setHourIndex(idx)} className={`text-[10px] font-black transition-all ${hourIndex === idx ? 'text-orange-500 scale-125' : 'text-gray-400'}`}>{h.label}</button>
                    ))}
                  </div>
                  <input type="range" min="0" max="4" step="1" value={hourIndex} onChange={(e) => setHourIndex(parseInt(e.target.value))} className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-orange-500" />
                  <div className="mt-6 bg-blue-900 text-white p-4 rounded-2xl flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <span className="text-2xl">🕗</span>
                        <div>
                          <p className="text-[10px] opacity-60 font-bold">الموعد المحدد</p>
                          <p className="text-sm font-black">{timing} • {hourOptions[hourIndex].label} ({hourOptions[hourIndex].range})</p>
                        </div>
                    </div>
                  </div>
                </div>
              </div>

              <button type="submit" disabled={isOrdering} className="w-full bg-orange-500 hover:bg-orange-600 text-white font-black py-5 rounded-[2rem] shadow-xl transition-all transform hover:scale-[1.02] text-xl">
                {isOrdering ? 'جاري الإرسال...' : 'تأكيد الطلب 🚀'}
              </button>
            </form>
          </div>
        ) : (
          <div className="max-w-4xl mx-auto animate-fadeIn">
             <h2 className="text-3xl font-black text-blue-900 mb-8">سجل طلباتي</h2>
             <div className="grid grid-cols-1 gap-6">
                {orders.map(o => (
                  <div key={o.id} className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-gray-100 flex flex-col md:flex-row justify-between items-center gap-6 group hover:shadow-md transition-shadow">
                     <div className="flex-1">
                        <div className="flex items-center gap-3 mb-2">
                           <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase ${o.status === 'completed' ? 'bg-emerald-100 text-emerald-600' : o.status === 'assigned' ? 'bg-blue-100 text-blue-600' : 'bg-amber-100 text-amber-600'}`}>
                             {o.status === 'completed' ? 'مكتمل' : o.status === 'assigned' ? 'جاري العمل' : 'يتم المراجعة'}
                           </span>
                           <h3 className="font-black text-xl text-blue-900">{o.serviceType}</h3>
                        </div>
                        <p className="text-sm text-gray-500 font-medium mb-4">{o.description}</p>
                        <div className="flex items-center gap-4 text-[11px] font-bold text-gray-400">
                           <span>📅 {new Date(o.createdAt).toLocaleDateString('ar-EG')}</span>
                           <span>📍 {o.detailedLocation}</span>
                        </div>
                     </div>

                     {o.technicianId && (
                       <div className="flex flex-col items-center gap-2 bg-slate-50 p-4 rounded-2xl min-w-[150px]">
                          <p className="text-xs font-black text-slate-400 uppercase tracking-widest">الفني المختص</p>
                          <p className="font-black text-blue-900">{o.technicianName}</p>

                          <button 
                            onClick={() => toggleFavorite(o.technicianId!)}
                            className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-black transition-all ${
                              currentUserData.favoriteTechIds?.includes(o.technicianId!) 
                              ? 'bg-orange-500 text-white shadow-lg shadow-orange-500/20' 
                              : 'bg-white text-gray-400 border border-gray-200 hover:border-orange-500 hover:text-orange-500'
                            }`}
                          >
                            {currentUserData.favoriteTechIds?.includes(o.technicianId!) ? '❤️ في المفضلين' : '⭐ إضافة للمفضلين'}
                          </button>
                       </div>
                     )}
                  </div>
                ))}
                {orders.length === 0 && (
                  <div className="text-center py-20 bg-white rounded-[3rem] border-2 border-dashed border-gray-100">
                     <p className="text-gray-300 font-black italic text-xl">لا توجد طلبات سابقة</p>
                  </div>
                )}
             </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default CustomerDashboard;

export type UserRole = 'customer' | 'technician' | 'admin' | 'manager';

export interface User {
  id: string;
  name: string;
  phone: string;
  password?: string;
  address?: string;
  securityQuestion: string;
  securityAnswer: string;
  role: UserRole;
  specialty?: string; // For technicians
  experience?: number; // For technicians
  area?: string; // For technicians
  createdAt: number;
  isApproved?: boolean; // حقل الاعتماد
  favoriteTechIds?: string[]; // قائمة الفنيين المفضلين للعميل
}

export type OrderStatus = 'pending' | 'assigned' | 'completed' | 'failed';

export interface Order {
  id: string;
  customerId: string;
  customerName: string;
  customerPhone: string;
  address: string;
  detailedLocation?: string;
  serviceType: string;
  description?: string;
  preferredTiming?: string;
  specificTime?: string;
  status: OrderStatus;
  technicianId?: string;
  technicianName?: string;
  technicianSpecialty?: string;
  technicianPhone?: string;
  failureReason?: string; // الملاحظات في حال حدوث خطأ
  adminResolved?: boolean; // هل قام المدير بمراجعة الخطأ؟
  createdAt: number;
  rating?: number;
  feedback?: string;
  isDirect?: boolean; // هل هو طلب مباشر من قائمة المفضلين؟
}

export interface AppNotification {
  id: string;
  message: string;
  type: 'info' | 'success' | 'warning' | 'error';
  timestamp: number;
}

import React, { useState, useEffect } from 'react';
import { collection, addDoc, query, where, onSnapshot, doc, updateDoc, arrayUnion, arrayRemove, getDocs } from 'firebase/firestore';
import { db } from '../firebase';
import { User, Order } from '../types';

interface CustomerDashboardProps {
  user: User;
  onLogout: () => void;
}

const CustomerDashboard: React.FC<CustomerDashboardProps> = ({ user, onLogout }) => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [favoriteTechs, setFavoriteTechs] = useState<User[]>([]);
  const [currentUserData, setCurrentUserData] = useState<User>(user);
  const [serviceType, setServiceType] = useState<string>('');
  const [description, setDescription] = useState('');
  const [detailedLocation, setDetailedLocation] = useState('');
  const [timing, setTiming] = useState('اليوم');
  const [hourIndex, setHourIndex] = useState(2);
  const [isOrdering, setIsOrdering] = useState(false);
  const [activeTab, setActiveTab] = useState<'new-order' | 'history'>('new-order');

  // حالات الطلب المباشر
  const [selectedTechForOrder, setSelectedTechForOrder] = useState<User | null>(null);

  const hourOptions = [
    { label: 'صباحاً', range: '8ص - 11ص' },
    { label: 'ظهراً', range: '12ظ - 2م' },
    { label: 'عصراً', range: '3م - 5م' },
    { label: 'مساءً', range: '6م - 9م' },
    { label: 'ليلاً', range: '10م - 12ل' }
  ];

  useEffect(() => {
    // مراقبة بيانات العميل من قاعدة البيانات مباشرة لضمان مزامنة المفضلين
    const unsubUser = onSnapshot(doc(db, 'users', user.id), (docSnap) => {
      if (docSnap.exists()) {
        const data = { id: docSnap.id, ...docSnap.data() } as User;
        setCurrentUserData(data);
        fetchFavoriteTechs(data.favoriteTechIds || []);
      }
    });

    const q = query(collection(db, 'orders'), where('customerId', '==', user.id));
    const unsubscribeOrders = onSnapshot(q, (snapshot) => {
      const ordersData = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));
      setOrders(ordersData.sort((a, b) => b.createdAt - a.createdAt));
    });

    return () => { unsubUser(); unsubscribeOrders(); };
  }, [user.id]);

  const fetchFavoriteTechs = async (ids: string[]) => {
    if (ids.length === 0) {
      setFavoriteTechs([]);
      return;
    }
    // جلب بيانات الفنيين المفضلين من جدول المستخدمين
    const q = query(collection(db, 'users'), where('__name__', 'in', ids));
    const snap = await getDocs(q);
    setFavoriteTechs(snap.docs.map(d => ({ id: d.id, ...d.data() } as User)));
  };

  const toggleFavorite = async (techId: string) => {
    const userRef = doc(db, 'users', user.id);
    const isFav = currentUserData.favoriteTechIds?.includes(techId);
    try {
      // تحديث قاعدة البيانات فوراً
      await updateDoc(userRef, {
        favoriteTechIds: isFav ? arrayRemove(techId) : arrayUnion(techId)
      });
    } catch (err) {
      alert('خطأ في تحديث قائمة المفضلين بالقاعدة');
    }
  };

  const handleCreateOrder = async (e: React.FormEvent, directTech: User | null = null) => {
    e.preventDefault();
    const finalServiceType = directTech ? directTech.specialty : serviceType;
    if (!finalServiceType) return alert('يرجى اختيار نوع الخدمة أولاً');

    setIsOrdering(true);
    try {
      const orderPayload: any = {
        customerId: user.id,
        customerName: user.name,
        customerPhone: user.phone,
        address: user.address || '',
        detailedLocation,
        serviceType: finalServiceType,
        description,
        preferredTiming: timing,
        specificTime: `${hourOptions[hourIndex].label} (${hourOptions[hourIndex].range})`,
        status: directTech ? 'assigned' : 'pending',
        isDirect: !!directTech, // وسم الطلب المباشر
        createdAt: Date.now(),
        adminResolved: true 
      };

      if (directTech) {
        orderPayload.technicianId = directTech.id;
        orderPayload.technicianName = directTech.name;
        orderPayload.technicianSpecialty = directTech.specialty;
        orderPayload.technicianPhone = directTech.phone;
      }

      await addDoc(collection(db, 'orders'), orderPayload);
      alert(directTech ? `تم إرسال الطلب المباشر لـ ${directTech.name} بنجاح!` : 'تم إرسال طلبك بنجاح! يتم مراجعة الطلب الآن.');

      // إعادة تعيين الحقول
      setServiceType('');
      setDescription('');
      setDetailedLocation('');
      setSelectedTechForOrder(null);
      setActiveTab('history');
    } catch (err) {
      alert('فشل إرسال الطلب، يرجى المحاولة لاحقاً');
    } finally {
      setIsOrdering(false);
    }
  };

  const serviceOptions = ['سباك', 'كهربائي', 'نجار', 'فني دش', 'نقاش'];

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row font-sans relative">

      {/* نافذة الطلب المباشر المنبثقة */}
      {selectedTechForOrder && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fadeIn">
          <div className="bg-white w-full max-w-xl rounded-[3rem] shadow-2xl overflow-hidden">
            <div className="bg-orange-500 p-6 text-white text-center relative">
               <button onClick={() => setSelectedTechForOrder(null)} className="absolute left-6 top-6 hover:scale-110 transition">✖️</button>
               <p className="text-xs font-black uppercase tracking-widest opacity-80">طلب صيانة مباشر</p>
               <h3 className="text-2xl font-black mt-1">الأسطى {selectedTechForOrder.name}</h3>
            </div>
            <form onSubmit={(e) => handleCreateOrder(e, selectedTechForOrder)} className="p-8 space-y-6">
               <div>
                  <label className="block text-xs font-black text-slate-400 mb-2">نوع الخدمة (تخصص الفني)</label>
                  <div className="bg-gray-100 p-4 rounded-2xl font-black text-blue-900">{selectedTechForOrder.specialty}</div>
               </div>
               <div>
                  <label className="block text-xs font-black text-slate-400 mb-2">وصف العطل</label>
                  <textarea required value={description} onChange={e => setDescription(e.target.value)} placeholder="اكتب تفاصيل المشكلة هنا..." className="w-full bg-gray-50 p-4 rounded-2xl border-none focus:ring-2 focus:ring-orange-500 outline-none font-bold text-sm min-h-[100px]" />
               </div>
