                    }`}>
                      {u.role === 'customer' ? 'عميل' : 'فني'}
                    </span>
                    {u.role === 'technician' && (
                      <span className={`text-[9px] font-black px-4 py-2 rounded-full uppercase tracking-widest shadow-sm ${u.isApproved ? 'bg-emerald-500 text-white' : 'bg-red-500 text-white animate-pulse'}`}>
                        {u.isApproved ? 'موثق' : 'غير معتمد'}
                      </span>
                    )}
                  </div>

                  {u.role === 'technician' && (
                    <div className="pt-4 border-t border-slate-50 w-full">
                       <p className="text-[10px] font-black text-amber-600 uppercase tracking-widest mb-1">تخصص: {u.specialty}</p>
                       <p className="text-[10px] font-bold text-slate-300">الخبرة: {u.experience} سنة • {u.area}</p>
                    </div>
                  )}

                  {u.role === 'technician' && !u.isApproved && (
                    <button 
                      onClick={() => approveTechnician(u.id)}
                      className="w-full mt-6 bg-amber-500 hover:bg-amber-600 text-slate-900 py-5 rounded-[2rem] font-black text-sm shadow-2xl shadow-amber-500/30 transition-all active:scale-95"
                    >
                      اعتماد الأسطى فوراً ✅
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </main>
    </div>
  );
};

