import { User, Order } from '../types';

interface CustomerDashboardProps {
  user: User;
  onLogout: () => void;
}

const CustomerDashboard: React.FC<CustomerDashboardProps> = ({ user, onLogout }) => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [favoriteTechs, setFavoriteTechs] = useState<User[]>([]);
  const [currentUserData, setCurrentUserData] = useState<User>(user);
  const [serviceType, setServiceType] = useState<string>('');
  const [description, setDescription] = useState('');
  const [detailedLocation, setDetailedLocation] = useState('');
  const [timing, setTiming] = useState('اليوم');
  const [hourIndex, setHourIndex] = useState(2);
  const [isOrdering, setIsOrdering] = useState(false);
  const [activeTab, setActiveTab] = useState<'new-order' | 'history'>('new-order');
  const [selectedTechForOrder, setSelectedTechForOrder] = useState<User | null>(null);

  const hourOptions = [
    { label: 'صباحاً', range: '8ص - 11ص' },
    { label: 'ظهراً', range: '12ظ - 2م' },
    { label: 'عصراً', range: '3م - 5م' },
    { label: 'مساءً', range: '6م - 9م' },
    { label: 'ليلاً', range: '10م - 12ل' }
  ];

  useEffect(() => {
    const unsubUser = onSnapshot(doc(db, 'users', user.id), (docSnap) => {
      if (docSnap.exists()) {
        const data = { id: docSnap.id, ...docSnap.data() } as User;
        setCurrentUserData(data);
        fetchFavoriteTechs(data.favoriteTechIds || []);
      }
    });

    const q = query(collection(db, 'orders'), where('customerId', '==', user.id));
    const unsubscribeOrders = onSnapshot(q, (snapshot) => {
      const ordersData = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));
      setOrders(ordersData.sort((a, b) => b.createdAt - a.createdAt));
    });

    return () => { unsubUser(); unsubscribeOrders(); };
  }, [user.id]);

  const fetchFavoriteTechs = async (ids: string[]) => {
    if (ids.length === 0) {
      setFavoriteTechs([]);
      return;
    }
    const q = query(collection(db, 'users'), where('__name__', 'in', ids));
    const snap = await getDocs(q);
    setFavoriteTechs(snap.docs.map(d => ({ id: d.id, ...d.data() } as User)));
  };

  const toggleFavorite = async (techId: string) => {
    const userRef = doc(db, 'users', user.id);
    const isFav = currentUserData.favoriteTechIds?.includes(techId);
    try {
      await updateDoc(userRef, {
        favoriteTechIds: isFav ? arrayRemove(techId) : arrayUnion(techId)
      });
    } catch (err) {
      alert('خطأ في التحديث');
    }
  };

  const handleCreateOrder = async (e: React.FormEvent, directTech: User | null = null) => {
    e.preventDefault();
    const finalServiceType = directTech ? directTech.specialty : serviceType;
    if (!finalServiceType) return alert('يرجى اختيار نوع الخدمة أولاً');

    setIsOrdering(true);
    try {
      const orderPayload: any = {
        customerId: user.id,
        customerName: user.name,
        customerPhone: user.phone,
        address: user.address || '',
        detailedLocation,
        serviceType: finalServiceType,
        description,
        preferredTiming: timing,
        specificTime: `${hourOptions[hourIndex].label} (${hourOptions[hourIndex].range})`,
        status: directTech ? 'assigned' : 'pending',
        isDirect: !!directTech,
        createdAt: Date.now(),
        adminResolved: true 
      };

      if (directTech) {
        orderPayload.technicianId = directTech.id;
        orderPayload.technicianName = directTech.name;
        orderPayload.technicianSpecialty = directTech.specialty;
        orderPayload.technicianPhone = directTech.phone;
      }

      await addDoc(collection(db, 'orders'), orderPayload);
      setServiceType('');
      setDescription('');
      setDetailedLocation('');
      setSelectedTechForOrder(null);
      setActiveTab('history');
    } catch (err) {
      alert('فشل إرسال الطلب');
    } finally {
      setIsOrdering(false);
    }
  };

  const serviceOptions = [
    { name: 'سباك', icon: '🚰' },
    { name: 'كهربائي', icon: '⚡' },
    { name: 'نجار', icon: '🪚' },
    { name: 'فني دش', icon: '📡' },
    { name: 'نقاش', icon: '🎨' }
  ];

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row font-sans relative">

      {/* Modal - Direct Order */}
      {selectedTechForOrder && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-900/40 backdrop-blur-xl animate-fadeIn">
          <div className="bg-white w-full max-w-xl rounded-[3.5rem] shadow-2xl overflow-hidden border border-white/50">
            <div className="bg-amber-500 p-8 text-slate-900 text-center relative">
               <button onClick={() => setSelectedTechForOrder(null)} className="absolute left-8 top-1/2 -translate-y-1/2 w-10 h-10 bg-black/10 rounded-full flex items-center justify-center hover:bg-black/20 transition">✕</button>
               <p className="text-[10px] font-black uppercase tracking-[0.2em] opacity-60">طلب أسطى بالاسم</p>
               <h3 className="text-3xl font-black mt-1">{selectedTechForOrder.name}</h3>
            </div>
            <form onSubmit={(e) => handleCreateOrder(e, selectedTechForOrder)} className="p-10 space-y-8">
               <div className="grid grid-cols-2 gap-6">
                 <div>
                    <label className="block text-xs font-black text-slate-400 mb-2 uppercase">التخصص</label>
                    <div className="bg-slate-50 p-4 rounded-2xl font-black text-slate-800 border border-slate-100">{selectedTechForOrder.specialty}</div>
                 </div>
                 <div>
                    <label className="block text-xs font-black text-slate-400 mb-2 uppercase">الخبرة</label>
                    <div className="bg-slate-50 p-4 rounded-2xl font-black text-amber-600 border border-slate-100">{selectedTechForOrder.experience} سنة</div>
                 </div>
               </div>
               <div>
                  <label className="block text-xs font-black text-slate-400 mb-2 uppercase">وصف المشكلة</label>
                  <textarea required value={description} onChange={e => setDescription(e.target.value)} placeholder="مثلاً: تغيير طقم الحمام أو إصلاح عطل..." className="w-full bg-slate-50 p-5 rounded-3xl border-2 border-transparent focus:border-amber-500 focus:bg-white outline-none font-bold text-sm min-h-[120px] transition-all" />
               </div>
               <div>
                  <label className="block text-xs font-black text-slate-400 mb-2 uppercase">العنوان</label>
                  <input required value={detailedLocation} onChange={e => setDetailedLocation(e.target.value)} placeholder="الحي، الشارع، الشقة..." className="w-full bg-slate-50 p-5 rounded-2xl border-2 border-transparent focus:border-amber-500 focus:bg-white outline-none font-bold text-sm transition-all" />
               </div>
               <div className="flex gap-4 pt-4">
                  <button type="button" onClick={() => setSelectedTechForOrder(null)} className="flex-1 bg-slate-100 text-slate-400 font-black py-5 rounded-[2rem] hover:bg-slate-200 transition">تراجع</button>
                  <button type="submit" disabled={isOrdering} className="flex-[2] bg-slate-900 text-white font-black py-5 rounded-[2rem] shadow-2xl shadow-slate-900/30 hover:bg-slate-800 transition transform active:scale-95">
                    {isOrdering ? 'جاري الإرسال...' : 'تأكيد الحجز 👷‍♂️'}
                  </button>
               </div>
            </form>
          </div>
        </div>
      )}

      {/* Modern Sidebar */}
      <aside className="w-full md:w-80 bg-white border-l border-slate-100 flex flex-col shadow-sm z-40">
        <div className="p-10 text-center border-b border-slate-50">
           <div className="relative inline-block">
             <div className="w-24 h-24 bg-gradient-to-tr from-slate-900 to-slate-700 rounded-[2.5rem] flex items-center justify-center mx-auto mb-4 text-4xl shadow-2xl transform -rotate-6">👤</div>
             <div className="absolute -bottom-1 -right-1 w-8 h-8 bg-amber-500 rounded-full border-4 border-white flex items-center justify-center text-[10px] font-black">VIP</div>
           </div>
           <h2 className="text-2xl font-black text-slate-900 tracking-tight">{user.name}</h2>
           <p className="text-slate-400 font-bold text-xs uppercase tracking-widest mt-1">العميل الذهبي</p>
        </div>

        <nav className="p-8 space-y-4">
           <button onClick={() => setActiveTab('new-order')} className={`w-full text-right p-5 rounded-[2rem] font-black transition-all flex items-center justify-between group ${activeTab === 'new-order' ? 'bg-amber-500 text-slate-900 shadow-xl shadow-amber-500/20' : 'text-slate-400 hover:bg-slate-50'}`}>
              <span>🆕 حجز جديد</span>
              <span className={`w-2 h-2 rounded-full ${activeTab === 'new-order' ? 'bg-slate-900' : 'bg-transparent'}`}></span>
           </button>
           <button onClick={() => setActiveTab('history')} className={`w-full text-right p-5 rounded-[2rem] font-black transition-all flex items-center justify-between group ${activeTab === 'history' ? 'bg-amber-500 text-slate-900 shadow-xl shadow-amber-500/20' : 'text-slate-400 hover:bg-slate-50'}`}>
              <span>📜 سجل الطلبات</span>
              <span className={`w-2 h-2 rounded-full ${activeTab === 'history' ? 'bg-slate-900' : 'bg-transparent'}`}></span>
           </button>
        </nav>

        <div className="flex-1 px-8 overflow-y-auto custom-scroll">
           <div className="flex items-center justify-between mb-6">
             <h3 className="text-[10px] font-black text-slate-300 uppercase tracking-widest">⭐ الصنايعية المفضلة</h3>
             <span className="text-[10px] bg-slate-100 text-slate-500 px-2 py-0.5 rounded-full font-black">{favoriteTechs.length}</span>
           </div>
           <div className="space-y-4 pb-12">
              {favoriteTechs.map(tech => (
                <div key={tech.id} className="p-5 bg-white rounded-[2rem] border border-slate-100 shadow-sm hover:shadow-md transition-all group relative">
                   <div className="flex justify-between items-start">
                      <div onClick={() => setSelectedTechForOrder(tech)} className="cursor-pointer">
                        <p className="text-sm font-black text-slate-900 group-hover:text-amber-600 transition-colors">{tech.name}</p>
                        <p className="text-[10px] font-bold text-slate-400">{tech.specialty}</p>
                      </div>
                      <button onClick={() => toggleFavorite(tech.id)} className="text-red-300 hover:text-red-500 transition scale-125">✕</button>
                   </div>
                   <button 
                    onClick={() => setSelectedTechForOrder(tech)}
                    className="w-full bg-slate-900 text-white py-2 rounded-xl text-[10px] font-black mt-3 opacity-0 group-hover:opacity-100 transition-all transform translate-y-2 group-hover:translate-y-0"
                   >
                     اطلب الآن 👷‍♂️
                   </button>
                </div>
              ))}
              {favoriteTechs.length === 0 && (
                <div className="py-12 text-center border-2 border-dashed border-slate-100 rounded-[2rem]">
                   <p className="text-[10px] text-slate-300 font-black italic">القائمة فارغة</p>
                </div>
              )}
           </div>
        </div>

        <div className="p-8 border-t border-slate-50">
          <button onClick={onLogout} className="w-full bg-slate-50 text-slate-400 font-black py-4 rounded-[1.5rem] hover:bg-red-50 hover:text-red-500 transition-all duration-300">تسجيل خروج</button>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 p-6 md:p-12 overflow-y-auto">
        {activeTab === 'new-order' ? (
          <div className="max-w-4xl mx-auto animate-fadeIn">
            <header className="mb-12">
               <h1 className="text-5xl font-black text-slate-900 tracking-tighter mb-4">خلصانة في ثانية.. <br /> محتاج فني إيه؟</h1>
               <p className="text-slate-400 font-bold text-lg">اختر الخدمة وسنتولى الباقي عنك بكل احترافية.</p>
            </header>

            <form onSubmit={(e) => handleCreateOrder(e)} className="space-y-12">
              {/* Service Selection Bento */}
              <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                 {serviceOptions.map(opt => (
                   <button 
                    key={opt.name} 
                    type="button" 
                    onClick={() => setServiceType(opt.name)} 
                    className={`flex flex-col items-center justify-center p-8 rounded-[2.5rem] transition-all duration-500 border-4 ${serviceType === opt.name ? 'bg-amber-500 border-amber-600 shadow-2xl shadow-amber-500/30 -translate-y-2' : 'bg-white border-transparent hover:bg-slate-100'}`}
                   >
                     <span className="text-4xl mb-3">{opt.icon}</span>
                     <span className={`text-sm font-black ${serviceType === opt.name ? 'text-slate-900' : 'text-slate-500'}`}>{opt.name}</span>
                   </button>
                 ))}
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                <div className="space-y-8">
                  <div className="bg-white p-10 rounded-[3rem] shadow-sm border border-slate-100">
                    <h3 className="text-xs font-black text-slate-300 uppercase tracking-widest mb-6">تفاصيل العطل</h3>
                    <textarea 
                      required 
                      value={description} 
                      onChange={e => setDescription(e.target.value)} 
                      placeholder="اشرح المشكلة هنا بالتفصيل لنتمكن من مساعدتك..." 
                      className="w-full bg-slate-50 p-6 rounded-3xl border-none focus:ring-4 focus:ring-amber-500/10 outline-none font-bold text-slate-700 min-h-[200px] transition-all" 
                    />
                  </div>
                </div>

                <div className="space-y-8">
                   <div className="bg-white p-10 rounded-[3rem] shadow-sm border border-slate-100">
                      <h3 className="text-xs font-black text-slate-300 uppercase tracking-widest mb-6">المكان والموعد</h3>
                      <input 
                        type="text" 
                        required 
                        value={detailedLocation} 
                        onChange={e => setDetailedLocation(e.target.value)} 
                        placeholder="العنوان بالتفصيل..." 
                        className="w-full bg-slate-50 p-5 rounded-2xl border-none focus:ring-4 focus:ring-amber-500/10 outline-none font-bold text-slate-700 mb-8 transition-all" 
                      />

                      <div className="bg-slate-900 p-8 rounded-[2.5rem] text-white">
                         <div className="flex justify-between items-center mb-6">
                            <span className="text-xs font-black text-slate-500 uppercase tracking-widest">توقيت العمل</span>
                            <span className="text-amber-500 font-black text-sm">{timing}</span>
                         </div>
                         <div className="grid grid-cols-5 gap-2 mb-6">
                           {hourOptions.map((h, idx) => (
                             <button 
                               key={idx} 
                               type="button" 
                               onClick={() => setHourIndex(idx)} 
                               className={`h-12 rounded-xl text-[10px] font-black transition-all border-2 ${hourIndex === idx ? 'bg-amber-500 border-amber-500 text-slate-900' : 'border-slate-800 text-slate-500 hover:border-slate-700'}`}
                             >
                               {h.label}
                             </button>
                           ))}
                         </div>
                         <div className="text-center pt-4 border-t border-slate-800">
                            <p className="text-xs font-bold text-slate-400">سيصلك الفني في حدود</p>
                            <p className="text-xl font-black text-amber-500 mt-1">{hourOptions[hourIndex].range}</p>
                         </div>
                      </div>
                   </div>

                   <button 
                    type="submit" 
                    disabled={isOrdering} 
                    className="w-full bg-amber-500 hover:bg-amber-600 text-slate-900 font-black py-7 rounded-[3rem] shadow-2xl shadow-amber-500/30 transition-all transform hover:scale-[1.03] active:scale-95 text-2xl"
                   >
                    {isOrdering ? 'جاري الحجز...' : 'تأكيد الحجز 👷‍♂️'}
                   </button>
                </div>
              </div>
            </form>
          </div>
        ) : (
          <div className="max-w-5xl mx-auto animate-fadeIn">
             <div className="flex items-center justify-between mb-12">
               <h2 className="text-4xl font-black text-slate-900 tracking-tighter">تاريخ عملياتك</h2>
               <div className="text-xs font-black text-slate-400 uppercase bg-white px-6 py-3 rounded-full border border-slate-100 shadow-sm">إجمالي الطلبات: {orders.length}</div>
             </div>

             <div className="grid grid-cols-1 gap-8">
                {orders.map(o => (
                  <div key={o.id} className="bg-white p-10 rounded-[3.5rem] shadow-sm border border-slate-100 flex flex-col md:flex-row justify-between items-start md:items-center gap-10 hover:shadow-xl transition-all group">
                     <div className="flex-1 space-y-4">
                        <div className="flex items-center gap-4">
                           <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${
                             o.status === 'completed' ? 'bg-emerald-500 text-white' : 
                             o.status === 'assigned' ? 'bg-blue-500 text-white' : 
                             'bg-amber-500 text-slate-900'
                           }`}>
                             {o.status === 'completed' ? 'مكتمل' : o.status === 'assigned' ? 'قيد التنفيذ' : 'في الانتظار'}
                           </span>
                           {o.isDirect && <span className="text-[10px] font-black text-amber-600 bg-amber-50 px-3 py-1.5 rounded-full">طلب مباشر ⭐</span>}
                        </div>
                        <h3 className="text-3xl font-black text-slate-900 tracking-tight">{o.serviceType}</h3>
                        <p className="text-slate-400 font-bold leading-relaxed max-w-lg line-clamp-2">{o.description}</p>
                        <div className="flex flex-wrap items-center gap-6 pt-2">
                           <div className="flex items-center gap-2 text-[11px] font-black text-slate-500 bg-slate-50 px-4 py-2 rounded-full">
                              <span>📅</span>
                              <span>{new Date(o.createdAt).toLocaleDateString('ar-EG')}</span>
                           </div>
                           <div className="flex items-center gap-2 text-[11px] font-black text-slate-500 bg-slate-50 px-4 py-2 rounded-full">
                              <span>📍</span>
                              <span className="line-clamp-1">{o.detailedLocation}</span>
                           </div>
                        </div>
                     </div>

                     {o.technicianId ? (
                       <div className="bg-slate-900 p-8 rounded-[3rem] text-white min-w-[280px] text-center space-y-4 shadow-2xl relative overflow-hidden group">
                          <div className="absolute top-0 right-0 w-20 h-20 bg-amber-500/10 rounded-full -mr-10 -mt-10"></div>
                          <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">الفني المعين</p>
                          <p className="text-2xl font-black text-amber-500">{o.technicianName}</p>
                          <div className="text-xs font-bold text-slate-400 border-t border-slate-800 pt-4">
                             <p>📞 {o.technicianPhone}</p>
                          </div>
                          <button 
                            onClick={() => toggleFavorite(o.technicianId!)}
                            className={`w-full py-3 rounded-2xl text-[10px] font-black transition-all ${
                              currentUserData.favoriteTechIds?.includes(o.technicianId!) 
                              ? 'bg-amber-500 text-slate-900' 
                              : 'bg-slate-800 text-slate-400 hover:bg-slate-700'
                            }`}
                          >
                            {currentUserData.favoriteTechIds?.includes(o.technicianId!) ? '❤️ في المفضلين' : '⭐ إضافة للمفضلين'}
                          </button>
                       </div>
                     ) : (
                       <div className="bg-slate-50 p-10 rounded-[3rem] border-2 border-dashed border-slate-200 text-center min-w-[280px]">
                          <div className="w-12 h-12 bg-white rounded-full flex items-center justify-center mx-auto mb-4 animate-pulse">⏳</div>
                          <p className="text-xs font-black text-slate-400 uppercase tracking-widest">بانتظار قبول أسطى</p>
                       </div>
                     )}
                  </div>
                ))}
                {orders.length === 0 && (
                  <div className="text-center py-32 bg-white rounded-[4rem] border border-slate-100 shadow-sm">
                     <p className="text-slate-300 font-black italic text-2xl">لم تقم بأي حجز بعد</p>
                     <button onClick={() => setActiveTab('new-order')} className="mt-8 text-amber-600 font-black border-b-2 border-amber-600 pb-1">احجز أول أسطى الآن</button>
                  </div>
                )}
             </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default CustomerDashboard;

import React, { useState, useEffect, useRef } from 'react';
import { collection, query, onSnapshot, doc, updateDoc } from 'firebase/firestore';
import { db } from '../firebase';
import { User, Order } from '../types';

const StatCard = ({ title, val, icon, color }: { title: string, val: number, icon: string, color: string }) => {
  return (
    <div className={`bg-white p-10 rounded-[3rem] shadow-sm border-b-8 ${color} relative overflow-hidden group hover:shadow-2xl transition-all duration-500`}>
      <div className="flex items-center justify-between mb-6">
        <div className="text-4xl">{icon}</div>
        <div className="text-[10px] font-black text-slate-300 uppercase tracking-widest">{title}</div>
      </div>
      <p className="text-6xl font-black text-slate-900 tracking-tighter group-hover:scale-110 transition-transform">{val}</p>
    </div>
  );
};

interface AdminDashboardProps {
  user: User;
  onLogout: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user, onLogout }) => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [activeTab, setActiveTab] = useState<'stats' | 'orders' | 'completed-log' | 'users' | 'tech-performance'>('stats');
  const [selectedTechId, setSelectedTechId] = useState<string | null>(null);
  const prevOrdersCount = useRef<number | null>(null);

  useEffect(() => {
    const unsubOrders = onSnapshot(collection(db, 'orders'), (snap) => {
      const ordersData = snap.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));
      const sorted = ordersData.sort((a, b) => b.createdAt - a.createdAt);

      if (prevOrdersCount.current !== null && sorted.length > prevOrdersCount.current) {
        new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3').play().catch(() => {});
      }
      prevOrdersCount.current = sorted.length;
      setOrders(sorted);
    });

    const unsubUsers = onSnapshot(collection(db, 'users'), (snap) => {
      setUsers(snap.docs.map(doc => ({ id: doc.id, ...doc.data() } as User)));
    });

    return () => { unsubOrders(); unsubUsers(); };
  }, []);

  const resolveError = async (orderId: string) => {
    try {
      await updateDoc(doc(db, 'orders', orderId), { adminResolved: true });
      alert('تم اعتماد حل المشكلة ونقل الطلب للسجل المعتمد ✅');
    } catch (err) { alert('فشل التحديث'); }
  };

  const approveTechnician = async (userId: string) => {
    try {
      await updateDoc(doc(db, 'users', userId), { isApproved: true });
      alert('تم اعتماد الفني بنجاح!');
    } catch (err) { alert('فشل الاعتماد'); }
  };

  const stats = {
    active: orders.filter(o => o.status === 'pending' || o.status === 'assigned').length,
    failed: orders.filter(o => o.status === 'failed' && !o.adminResolved).length,
    completed: orders.filter(o => o.status === 'completed').length,
    techs: users.filter(u => u.role === 'technician' && u.isApproved).length,
  };

  // الطلبات التي بها مشاكل ولم يتم حلها إدارياً
  const currentFailedOrders = orders.filter(o => o.status === 'failed' && !o.adminResolved);

  const technicians = users.filter(u => u.role === 'technician' && u.isApproved);

  // دالة جلب أوردرات الفني (تشمل المكتملة والمتعثرة عشان الإدارة تشوف كل حاجة)
  const getTechOrders = (techId: string) => {
    return orders.filter(o => o.technicianId === techId && (o.status === 'completed' || o.status === 'failed'))
                 .sort((a, b) => b.createdAt - a.createdAt);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row font-sans">
      {/* Sidebar */}
      <aside className="w-full md:w-80 bg-slate-900 text-white shadow-2xl z-40 flex flex-col">
        <div className="p-12 text-center border-b border-white/5">
          <div className="inline-block bg-amber-500 text-slate-900 p-4 rounded-3xl transform -rotate-12 mb-6 shadow-2xl">
            <span className="text-4xl font-black">HQ</span>
          </div>
          <h1 className="text-3xl font-black tracking-tighter mb-1">الأسطى • الإدارة</h1>
          <p className="text-slate-500 text-[10px] font-black uppercase tracking-widest relative">
            مركز القيادة الوطني
            {currentFailedOrders.length > 0 && (
              <span className="absolute -top-1 -right-4 w-3 h-3 bg-red-500 rounded-full animate-ping"></span>
            )}
          </p>
        </div>

        <nav className="mt-8 px-8 space-y-3 flex-1 overflow-y-auto custom-scroll">
          {[
            {id:'stats',l:'📊 نظرة عامة', i: 'Dashboard'},
            {id:'orders',l:'📦 الطلبات النشطة', i: 'Live Orders'},
            {id:'tech-performance',l:'📈 أداء الأسطوات', i: 'Performance'},
            {id:'completed-log',l:'📜 سجل العمليات', i: 'Full History'},
            {id:'users',l:'👥 إدارة الفنيين', i: 'Staff'}
          ].map(item => (
            <button 
              key={item.id} 
              onClick={() => { setActiveTab(item.id as any); setSelectedTechId(null); }} 
              className={`w-full text-right p-5 rounded-[2rem] font-black transition-all duration-500 relative flex flex-col ${activeTab === item.id ? 'bg-amber-500 text-slate-900 shadow-2xl shadow-amber-500/20 translate-x-3' : 'text-slate-500 hover:text-white hover:bg-white/5'}`}
            >
              <div className="flex justify-between items-center">
                <span>{item.l}</span>
                {item.id === 'stats' && currentFailedOrders.length > 0 && (
                  <span className="bg-red-500 text-white text-[8px] px-2 py-1 rounded-full animate-bounce">{currentFailedOrders.length}</span>
                )}
              </div>
              <span className={`text-[8px] uppercase tracking-widest mt-0.5 ${activeTab === item.id ? 'text-slate-900/50' : 'text-slate-700'}`}>{item.i}</span>
            </button>
          ))}
        </nav>

        <div className="p-8 border-t border-white/5">
          <button onClick={onLogout} className="w-full bg-red-500/10 text-red-500 p-5 rounded-[2rem] font-black hover:bg-red-500 hover:text-white transition-all flex justify-center gap-3">
            <span>خروج آمن</span>
            <span>🔒</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto p-6 md:p-16 custom-scroll">
        {/* التنبيه الأحمر: يظهر الآن في كل الصفحات طالما هناك مشكلة لم تحل */}
        {currentFailedOrders.length > 0 && (
          <div className="mb-12 p-10 bg-red-600 rounded-[3.5rem] shadow-2xl shadow-red-600/20 text-white animate-fadeIn relative overflow-hidden">
             <div className="absolute -right-6 -bottom-6 opacity-10 text-9xl font-black rotate-12">⚠️</div>
             <div className="relative z-10">
                <div className="flex items-center gap-6 mb-8">
                   <div className="w-16 h-16 bg-white/20 backdrop-blur-md text-white rounded-[1.5rem] flex items-center justify-center text-3xl animate-bounce">🚨</div>
                   <div>
                      <h3 className="text-3xl font-black tracking-tighter">أعطال نشطة تحتاج قرارك!</h3>
                      <p className="text-sm font-bold opacity-80">يوجد {currentFailedOrders.length} طلبات متعثرة لم يتم حلها بعد.</p>
                   </div>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                   {currentFailedOrders.map(o => (
                     <div key={o.id} className="bg-white/10 backdrop-blur-xl p-6 rounded-[2.5rem] border border-white/10 flex flex-col justify-between items-start">
                        <div className="mb-4">
                           <div className="flex justify-between w-full items-start">
                              <h4 className="text-xl font-black">{o.customerName}</h4>
                              <span className="text-[10px] bg-white/20 px-3 py-1 rounded-full font-black">{o.serviceType}</span>
                           </div>
                           <p className="text-[10px] font-black text-red-200 mt-2 italic">السبب: {o.failureReason || 'عطل غير محدد'}</p>
                           <p className="text-[9px] text-white/50 mt-1 uppercase font-bold">بواسطة: {o.technicianName}</p>
                        </div>
                        <button onClick={() => resolveError(o.id)} className="w-full bg-white text-red-600 py-3 rounded-xl font-black text-xs hover:scale-105 transition shadow-xl">تأكيد حل المشكلة ✅</button>
                     </div>
                   ))}
                </div>
             </div>
          </div>
        )}

        <header className="mb-12 flex flex-col md:flex-row md:items-end justify-between gap-8">
          <div className="space-y-2">
            <div className="text-xs font-black text-amber-600 uppercase tracking-[0.3em] mb-4">مركز قيادة الأسطى</div>
            <h2 className="text-6xl font-black text-slate-900 tracking-tighter">
              {activeTab === 'tech-performance' ? 'أداء الأسطوات' : activeTab === 'completed-log' ? 'سجل العمليات الكامل' : `مرحباً، ${user.name}`}
            </h2>
            <p className="text-slate-400 font-bold text-xl">متابعة دقيقة لكل فني وحالة 📈</p>
          </div>
          {activeTab === 'tech-performance' && selectedTechId && (
            <button onClick={() => setSelectedTechId(null)} className="bg-slate-900 text-white px-8 py-4 rounded-2xl font-black text-sm flex items-center gap-3 shadow-xl hover:bg-slate-800 transition transform active:scale-95">
              <span>🔙 قائمة الفنيين</span>
            </button>
          )}
        </header>

        {activeTab === 'stats' && (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8 animate-fadeIn">
            <StatCard title="مهام جارية" val={stats.active} icon="🚚" color="border-blue-500" />
            <StatCard title="أعطال نشطة" val={stats.failed} icon="🛑" color="border-red-500" />
            <StatCard title="تم بنجاح" val={stats.completed} icon="🏆" color="border-emerald-500" />
            <StatCard title="الأسطوات المعتمدة" val={stats.techs} icon="👨‍🔧" color="border-amber-500" />
          </div>
        )}

        {/* سجل أداء الفنيين - مربوط بالكامل */}
        {activeTab === 'tech-performance' && (
          <div className="animate-fadeIn">
            {!selectedTechId ? (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {technicians.map(tech => {
                  const techOrders = getTechOrders(tech.id);
                  const successRate = techOrders.length > 0 ? (techOrders.filter(o => o.status === 'completed').length / techOrders.length * 100).toFixed(0) : 100;
                  return (
                    <div key={tech.id} className="bg-white p-10 rounded-[4rem] shadow-sm border border-slate-100 flex flex-col items-center group hover:shadow-2xl hover:-translate-y-2 transition-all duration-500">
                      <div className="w-24 h-24 bg-slate-900 text-white rounded-[2.5rem] flex items-center justify-center mb-6 text-4xl shadow-xl group-hover:bg-amber-500 group-hover:text-slate-900 transition-colors">👷‍♂️</div>
                      <h3 className="text-2xl font-black text-slate-900 tracking-tighter mb-1">{tech.name}</h3>
                      <p className="text-xs font-black text-amber-600 uppercase tracking-widest mb-6">{tech.specialty}</p>

                      <div className="grid grid-cols-2 gap-4 w-full mb-8">
                        <div className="bg-slate-50 p-4 rounded-3xl text-center border border-slate-100">
                          <p className="text-[8px] font-black text-slate-400 uppercase mb-1">إجمالي العمليات</p>
                          <p className="text-2xl font-black text-slate-900">{techOrders.length}</p>
                        </div>
                        <div className="bg-slate-50 p-4 rounded-3xl text-center border border-slate-100">
                          <p className="text-[8px] font-black text-slate-400 uppercase mb-1">نسبة النجاح</p>
                          <p className="text-2xl font-black text-emerald-500">{successRate}%</p>
                        </div>
                      </div>

                      <button onClick={() => setSelectedTechId(tech.id)} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-sm shadow-xl hover:bg-amber-500 hover:text-slate-900 transition-all flex items-center justify-center gap-3">
                        عرض التواريخ 📄
                      </button>
                    </div>
                  );
                })}
              </div>
            ) : (
              <div className="space-y-8 animate-fadeIn">
                <div className="bg-slate-900 p-12 rounded-[4rem] text-white flex flex-col md:flex-row justify-between items-center gap-8 relative overflow-hidden shadow-2xl">
                   <div className="absolute top-0 right-0 w-64 h-64 bg-amber-500/10 rounded-full blur-3xl -mr-32 -mt-32"></div>
                   <div className="flex items-center gap-8 relative z-10 text-right">
                      <div className="w-24 h-24 bg-amber-500 text-slate-900 rounded-[2.5rem] flex items-center justify-center text-4xl shadow-2xl">👷‍♂️</div>
                      <div>
                        <h3 className="text-4xl font-black tracking-tighter mb-1">{users.find(u => u.id === selectedTechId)?.name}</h3>
                        <p className="text-amber-500 font-black text-sm tracking-widest uppercase">سجل العمليات التاريخي للفني</p>
                      </div>
                   </div>
                </div>

                <div className="bg-white rounded-[4rem] shadow-sm border border-slate-100 overflow-hidden">
                   <div className="overflow-x-auto">
                     <table className="w-full text-right">
                       <thead className="bg-slate-900 text-white uppercase text-[10px] font-black tracking-[0.2em]">
                         <tr>
                           <th className="p-8">التاريخ والوقت</th>
                           <th className="p-8">العميل والموقع</th>
                           <th className="p-8">نوع الخدمة</th>
                           <th className="p-8 text-center">حالة العملية</th>
                         </tr>
                       </thead>
                       <tbody className="divide-y divide-slate-50">
                         {getTechOrders(selectedTechId).map(o => (
                           <tr key={o.id} className="hover:bg-slate-50/50 transition-colors group">
                             <td className="p-8 font-black text-slate-900">
                               {new Date(o.createdAt).toLocaleDateString('ar-EG')} <br />
                               <span className="text-[10px] text-slate-400">{new Date(o.createdAt).toLocaleTimeString('ar-EG')}</span>
                             </td>
                             <td className="p-8">
                               <p className="font-black text-slate-900">{o.customerName}</p>
                               <p className="text-xs text-slate-400">📍 {o.detailedLocation}</p>
                             </td>
                             <td className="p-8">
                               <span className="bg-slate-100 text-slate-900 px-4 py-1.5 rounded-full text-[10px] font-black border border-slate-200">{o.serviceType}</span>
                             </td>
                             <td className="p-8 text-center">
                               <span className={`px-4 py-1.5 rounded-full text-[10px] font-black ${o.status === 'completed' ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-700'}`}>
                                 {o.status === 'completed' ? 'نجحت ✅' : 'تعثرت ❌'}
                               </span>
                               {o.status === 'failed' && <p className="text-[8px] text-red-400 mt-2 font-bold italic">"{o.failureReason}"</p>}
                             </td>
                           </tr>
                         ))}
                       </tbody>
                     </table>
                   </div>
                </div>
              </div>
            )}
          </div>
        )}

        {/* سجل العمليات العام */}
        {(activeTab === 'orders' || activeTab === 'completed-log') && (
           <div className="bg-white rounded-[4rem] shadow-sm overflow-hidden border border-slate-100 animate-fadeIn mt-12">
            <div className="overflow-x-auto">
              <table className="w-full text-right">
                <thead className="bg-slate-900 text-white uppercase text-[10px] font-black tracking-[0.2em]">
                  <tr>
                    <th className="p-10">العميل والموقع</th>
                    <th className="p-10">الأسطى والبيانات</th>
                    <th className="p-10 text-center">حالة الطلب</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {(activeTab === 'orders' 
                    ? orders.filter(o => o.status === 'pending' || o.status === 'assigned' || (o.status === 'failed' && !o.adminResolved))
                    : orders.filter(o => o.status === 'completed' || (o.status === 'failed' && o.adminResolved))
                  ).map(o => (
                    <tr key={o.id} className="hover:bg-slate-50 transition-colors group">
                      <td className="p-10">
                        <p className="font-black text-slate-900 text-2xl tracking-tighter">{o.customerName}</p>
                        <p className="text-[10px] text-amber-600 font-black uppercase tracking-widest mt-1">📍 {o.detailedLocation}</p>
                        <p className="text-xs text-slate-400 font-bold mt-2 italic opacity-60">"{o.description}"</p>
                      </td>
                      <td className="p-10">
                        {o.technicianName ? (
                          <div className="bg-slate-50 p-6 rounded-3xl border border-slate-100 w-fit">
                             <p className="text-xl font-black text-slate-900">{o.technicianName}</p>
                             <p className="text-[10px] text-amber-600 font-black mt-1 uppercase tracking-widest">{o.technicianSpecialty}</p>
                          </div>
                        ) : (
                          <span className="text-slate-300 italic font-black text-xs animate-pulse">بانتظار قبول أسطى</span>
                        )}
                      </td>
                      <td className="p-10 text-center">
                        <div className="flex flex-col items-center gap-2">
                          <span className={`px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-widest shadow-sm ${
                            o.status === 'pending' ? 'bg-amber-100 text-amber-700' : 
                            o.status === 'assigned' ? 'bg-blue-100 text-blue-700' : 
                            o.status === 'completed' ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-700'
                          }`}>
                            {o.status === 'pending' ? 'في الانتظار' : o.status === 'assigned' ? 'جاري التنفيذ' : o.status === 'completed' ? 'تمت المهمة' : '⚠️ تعثرت'}
                          </span>
                          {o.status === 'failed' && !o.adminResolved && <span className="text-[8px] text-red-500 font-black animate-pulse">تتدخل إداري مطلوب 🛑</span>}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* إدارة المستخدمين */}
        {activeTab === 'users' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10 animate-fadeIn mt-12">
            {users.map(u => (
              <div key={u.id} className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-sm flex flex-col justify-center items-center group hover:shadow-2xl hover:-translate-y-2 transition-all duration-500 text-center relative overflow-hidden">
                <div className={`w-24 h-24 rounded-[2.5rem] flex items-center justify-center mb-8 text-4xl shadow-inner ${u.role === 'customer' ? 'bg-slate-50' : u.isApproved ? 'bg-emerald-50' : 'bg-amber-50 animate-pulse transform -rotate-12'}`}>
                  {u.role === 'customer' ? '👤' : '👷‍♂️'}
                </div>
                <h3 className="font-black text-slate-900 text-2xl tracking-tighter mb-2">{u.name}</h3>
                <p className="text-xs text-slate-400 font-bold mb-8 uppercase tracking-widest">📞 {u.phone}</p>

                <div className="flex flex-col items-center gap-4 w-full">
                  <div className="flex items-center gap-3">
                    <span className={`text-[9px] font-black px-5 py-2 rounded-full uppercase tracking-[0.2em] shadow-sm ${
                      u.role === 'customer' ? 'bg-slate-100 text-slate-500' : 'bg-slate-900 text-white'
                    }`}>
                      {u.role === 'customer' ? 'عميل' : 'فني'}
                    </span>
                    {u.role === 'technician' && (
                      <span className={`text-[9px] font-black px-4 py-2 rounded-full uppercase tracking-widest shadow-sm ${u.isApproved ? 'bg-emerald-500 text-white' : 'bg-red-500 text-white animate-pulse'}`}>
                        {u.isApproved ? 'موثق' : 'غير معتمد'}
                      </span>
                    )}
                  </div>
                  {u.role === 'technician' && !u.isApproved && (
                    <button onClick={() => approveTechnician(u.id)} className="w-full mt-6 bg-amber-500 hover:bg-amber-600 text-slate-900 py-5 rounded-[2rem] font-black text-sm shadow-2xl transition-all active:scale-95">
                      اعتماد الأسطى فوراً ✅
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </main>
    </div>
  );
};

export default AdminDashboard;
